    function spendTimeWithSpouse(activityId) {
        try {
            const result = Player.spendTimeWithSpouse(activityId);
            if (result && result.success) {
                toast(result.message, 'success');
                openCharacterDialog(); // refresh
            } else {
                toast((result && result.message) || 'Cannot spend time', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Error', 'danger');
        }
    }

    function buildSpouseDetailPanel(spouse) {
        if (!spouse) return '';
        const rel = Player.getRelationship ? Player.getRelationship(spouse.id) : { level: 0 };
        const revealed = Player.getRevealedInfo ? Player.getRevealedInfo(spouse.id) : { traits: {}, quirks: [] };
        const revealedCount = Object.keys(revealed.traits).length;

        let html = '<div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:8px;margin-top:8px;">';
        html += `<div style="font-weight:bold;margin-bottom:4px;">💑 ${spouse.firstName || 'Unknown'} ${spouse.lastName || ''}</div>`;
        html += `<div class="text-dim" style="font-size:0.8rem;">Age ${spouse.age} | 💛 Relationship: ${Math.floor(rel.level)}/100</div>`;

        // Trait bars
        if (revealedCount > 0) {
            html += '<div style="margin-top:6px;font-size:0.75rem;">';
            const traitNames = ['loyalty', 'ambition', 'frugality', 'intelligence', 'warmth', 'honesty'];
            for (const trait of traitNames) {
                const label = trait.charAt(0).toUpperCase() + trait.slice(1);
                if (trait in revealed.traits) {
                    const val = revealed.traits[trait];
                    if (typeof val === 'number') {
                        html += `<div style="display:flex;align-items:center;gap:4px;margin:2px 0;"><span style="width:85px;color:var(--gold);">${label}</span><div style="flex:1;height:8px;background:rgba(255,255,255,0.1);border-radius:4px;"><div style="width:${val}%;height:100%;background:var(--gold);border-radius:4px;"></div></div><span style="width:28px;text-align:right;">${val}</span></div>`;
                    } else {
                        html += `<div style="display:flex;align-items:center;gap:4px;margin:2px 0;"><span style="width:85px;color:var(--gold);">${label}</span><span>${val}</span></div>`;
                    }
                } else {
                    html += `<div style="display:flex;align-items:center;gap:4px;margin:2px 0;"><span style="width:85px;color:#666;">${label}</span><span style="color:#666;">???</span></div>`;
                }
            }
            html += '</div>';
        }

        // Quirks
        if (revealed.quirks.length > 0 && typeof SPOUSE_QUIRKS !== 'undefined') {
            html += '<div style="margin-top:4px;font-size:0.75rem;">';
            for (const qId of revealed.quirks) {
                const qDef = SPOUSE_QUIRKS.find(q => q.id === qId);
                if (qDef) {
                    const color = qDef.positive ? 'rgba(100,200,100,0.8)' : 'rgba(200,100,100,0.8)';
                    html += `<div style="color:${color};">${qDef.icon} ${qDef.name} — <span class="text-dim">${qDef.effect}</span></div>`;
                }
            }
            html += '</div>';
        }

        // Spend time buttons
        html += '<div style="margin-top:6px;font-size:0.75rem;font-weight:bold;">💬 Spend Time Together</div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:3px;margin-top:3px;">';
        if (typeof DATING_ACTIVITIES !== 'undefined') {
            for (const act of DATING_ACTIVITIES) {
                const disabled = (act.minRelationship && rel.level < act.minRelationship) || (act.cost > 0 && Player.gold < act.cost);
                const title = `${act.description} (${act.cost > 0 ? act.cost + 'g, ' : ''}${act.timeHours}h)`;
                html += `<button class="btn-hire ${disabled ? 'disabled' : ''}" data-action="spendTimeWithSpouse" data-id="${act.id}" style="font-size:0.7rem;padding:3px 6px;${disabled ? 'opacity:0.4;' : ''}" ${disabled ? 'disabled' : ''} title="${title}">${act.name}</button>`;
            }
        }
        html += '</div></div>';
        return html;
    }

    function proposeMarriage(personId) {
        try {
            const result = Player.marry(personId);
            if (result && result.success && result.startPlanning) {
                toast(result.message, 'success');
                setTimeout(function() { openWeddingPlanner(); }, 500);
            } else if (result && result.success) {
                toast(result.message, 'success');
                openHireDialog(); // refresh
            } else {
                toast((result && result.message) || 'Cannot marry', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Cannot marry', 'danger');
        }
    }

    function hirePerson(personId) {
        try {
            var result = Player.hireWorker(personId);
            if (result && result.success === false) {
                toast(result.message || 'Cannot hire this worker.', 'danger');
            } else {
                toast(result && result.message ? result.message : 'Worker hired!', 'success', 'my_business');
            }
            openHireDialog(); // refresh
        } catch (e) {
            toast(e.message || 'Cannot hire', 'danger');
        }
    }

    function fireWorker(personId) {
        try {
            var result = Player.fireWorker(personId);
            if (result && result.success === false) {
                toast(result.message || 'Cannot fire this worker.', 'danger');
            } else {
                toast(result && result.message ? result.message : 'Worker dismissed.', 'info');
            }
            openHireDialog(); // refresh
        } catch (e) {
            toast(e.message || 'Cannot fire', 'danger');
        }
    }

    function showAssignDialog(personId) {
        if (!Player.buildings || !Player.buildings.length) {
            toast('No buildings to assign to.', 'warning');
            return;
        }

        var person = null;
        try { person = Engine.findPerson(personId); } catch(e) {}
        var personTownId = person ? person.townId : Player.townId;
        var personName = person ? (person.firstName + ' ' + person.lastName) : 'Worker';
        var isTraveling = person && person._workerTraveling;

        if (isTraveling) {
            var destTown = Engine.findTown(person._workerTraveling.toTownId);
            toast(personName + ' is traveling to ' + (destTown ? destTown.name : '?') + '. Wait for arrival.', 'warning');
            return;
        }

        var personTown = Engine.findTown(personTownId);
        var personTownName = personTown ? personTown.name : '?';

        let html = '<div style="margin-bottom:8px;font-size:0.8rem;color:#aaa;">Worker: <b>' + personName + '</b> — Currently in: <b>' + personTownName + '</b>';
        if (person && person._playerHorse) html += ' 🐴';
        html += '</div>';
        html += '<div class="worker-list">';

        for (const building of Player.buildings) {
            const bt = findBuildingType(building.type);
            var bldTown = Engine.findTown(building.townId);
            var bldTownName = bldTown ? bldTown.name : '?';
            var sameAsTown = personTownId === building.townId;
            var _effWorkerMax = bt ? bt.workers + ((building.level || 1) - 1) : 0;
            var isFull = bt && building.workers && building.workers.length >= _effWorkerMax;
            var staffText = bt ? (building.workers ? building.workers.length : 0) + '/' + _effWorkerMax : '';

            html += `<div class="worker-row" style="flex-direction:column;align-items:stretch;${sameAsTown ? '' : 'border-left:2px solid rgba(200,150,50,0.4);padding-left:8px;'}">
                <div style="display:flex;justify-content:space-between;align-items:center;">
                    <div class="worker-info" style="flex:1;">
                        <div class="name">${bt ? bt.name : building.type} <span style="font-size:0.7rem;color:#888;">📍${bldTownName} • ${staffText}${isFull ? ' (Full)' : ''}</span></div>
                    </div>`;

            if (sameAsTown && !isFull) {
                html += `<button class="btn-assign" data-action="executeAssign" data-id="${personId}" data-val="${building.id}">Assign</button>`;
            } else if (!sameAsTown && !isFull) {
                html += `<button class="btn-assign" style="font-size:0.7rem;background:rgba(200,150,50,0.15);border-color:rgba(200,150,50,0.4);" data-action="showSendWorkerOptions" data-id="${personId}" data-val="${building.townId}" data-type="${building.id}">📍 Send There</button>`;
            } else {
                html += `<button class="btn-assign" disabled style="opacity:0.4;">Full</button>`;
            }

            html += `</div></div>`;
        }
        html += '</div>';

        openModal('📋 Assign Worker', html);
    }

    function showSendWorkerOptions(personId, destTownId, buildingId) {
        var person = null;
        try { person = Engine.findPerson(personId); } catch(e) {}
        var personName = person ? (person.firstName + ' ' + person.lastName) : 'Worker';
        var destTown = Engine.findTown(destTownId);
        var destName = destTown ? destTown.name : '?';
        var horsesOwned = (Player.inventory || {})['horses'] || 0;

        // Estimate transport cost
        var route = null;
        try { route = Engine.findPath(person ? person.townId : Player.townId, destTownId); } catch(e) {}
        var totalDist = 0;
        if (route) {
            for (var si = 0; si < route.length; si++) {
                var a = Engine.findTown(route[si].fromTownId);
                var b = Engine.findTown(route[si].toTownId);
                if (a && b) totalDist += Math.hypot(a.x - b.x, a.y - b.y);
            }
        }
        var transportCost = Math.max(10, Math.ceil(totalDist * 0.15));
        var walkDays = Math.max(1, Math.ceil(totalDist / ((CONFIG.CARAVAN_BASE_SPEED || 120) * 0.5)));
        var horseDays = Math.max(1, Math.ceil(totalDist / ((CONFIG.CARAVAN_BASE_SPEED || 120) * 1.5)));
        var transportDays = Math.max(1, Math.ceil(totalDist / ((CONFIG.CARAVAN_BASE_SPEED || 120) * 1.2)));

        var html = '<div style="margin-bottom:10px;font-size:0.85rem;">Send <b>' + personName + '</b> to <b>' + destName + '</b></div>';
        html += '<div style="display:flex;flex-direction:column;gap:8px;">';

        // Walk option (free)
        html += '<div style="padding:8px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.1);border-radius:6px;display:flex;justify-content:space-between;align-items:center;">';
        html += '<div><div style="font-weight:bold;font-size:0.8rem;">🚶 Walk (Free)</div>';
        html += '<div style="font-size:0.7rem;color:#aaa;">~' + walkDays + ' days • ⚠️ -5 satisfaction</div></div>';
        html += '<button class="btn-medieval" style="font-size:0.75rem;padding:4px 12px;" data-action="sendWorkerToTown_walk" data-person="' + personId + '" data-dest="' + destTownId + '">Send</button>';
        html += '</div>';

        // Horse option
        html += '<div style="padding:8px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.1);border-radius:6px;display:flex;justify-content:space-between;align-items:center;' + (horsesOwned < 1 ? 'opacity:0.5;' : '') + '">';
        html += '<div><div style="font-weight:bold;font-size:0.8rem;">🐴 Give Horse & Ride</div>';
        html += '<div style="font-size:0.7rem;color:#aaa;">~' + horseDays + ' days • Uses 1 horse from inventory' + (horsesOwned < 1 ? ' (none owned!)' : ' (' + horsesOwned + ' owned)') + '</div></div>';
        if (horsesOwned >= 1) {
            html += '<button class="btn-medieval" style="font-size:0.75rem;padding:4px 12px;" data-action="sendWorkerToTown_horse" data-person="' + personId + '" data-dest="' + destTownId + '">Send</button>';
        } else {
            html += '<button class="btn-medieval" disabled style="font-size:0.75rem;padding:4px 12px;opacity:0.4;">No Horse</button>';
        }
        html += '</div>';

        // Transport option (paid)
        html += '<div style="padding:8px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.1);border-radius:6px;display:flex;justify-content:space-between;align-items:center;">';
        html += '<div><div style="font-weight:bold;font-size:0.8rem;">🚐 Pay for Transport</div>';
        html += '<div style="font-size:0.7rem;color:#aaa;">~' + transportDays + ' days • Costs ' + transportCost + 'g</div></div>';
        html += '<button class="btn-medieval" style="font-size:0.75rem;padding:4px 12px;" data-action="sendWorkerToTown_transport" data-person="' + personId + '" data-dest="' + destTownId + '">Send</button>';
        html += '</div>';

        html += '</div>';
        var footer = '<button class="btn-medieval" data-action="showAssignDialog" data-id="' + personId + '">← Back</button>';
        openModal('📍 Send Worker', html, footer);
    }

    function executeAssign(personId, buildingId) {
        var result = Player.assignWorker(personId, buildingId);
        if (result && result.success) {
            toast(result.message || 'Worker assigned!', 'success');
            closeModal();
        } else {
            toast((result && result.message) || 'Cannot assign', 'warning');
        }
    }


    // §CARAVANS — Extracted to js/modules/ui_caravans.js

    // ── CHARACTER DIALOG ──

    function openRenamePlayer() {
        const body = `<div style="text-align:center;">
            <div style="margin-bottom:10px;">
                <label style="display:block;margin-bottom:4px;font-weight:bold;">First Name</label>
                <input type="text" id="renameFirst" class="char-input" maxlength="20" value="${Player.firstName || ''}" style="width:80%;padding:6px;font-size:1rem;" />
            </div>
            <div style="margin-bottom:10px;">
                <label style="display:block;margin-bottom:4px;font-weight:bold;">Last Name</label>
                <input type="text" id="renameLast" class="char-input" maxlength="20" value="${Player.lastName || ''}" style="width:80%;padding:6px;font-size:1rem;" />
            </div>
        </div>`;
        const footer = `<button class="btn-medieval" data-action="confirmRenamePlayer">✅ Confirm</button>
            <button class="btn-medieval" data-action="closeModal">Cancel</button>`;
        openModal('✏️ Change Name', body, footer);
    }

    function confirmRenamePlayer() {
        const firstEl = document.getElementById('renameFirst');
        const lastEl = document.getElementById('renameLast');
        const newFirst = firstEl ? firstEl.value.trim() : '';
        const newLast = lastEl ? lastEl.value.trim() : '';
        if (!newFirst && !newLast) { toast('Enter at least a first or last name.', 'warning'); return; }
        const result = Player.setPlayerName(newFirst, newLast);
        if (result.success) {
            toast(result.message, 'info');
            closeModal();
            openCharacterDialog();
        } else {
            toast(result.message, 'warning');
        }
    }

    function _buildKingdomRepBarsHtml() {
        var html = '';
        try {
            var kingdoms = Engine.getKingdoms();
            if (!kingdoms || kingdoms.length === 0) return '';
            html += '<div class="detail-section"><h3>🏰 Kingdom Reputation</h3>';
            for (var ki = 0; ki < kingdoms.length; ki++) {
                var k = kingdoms[ki];
                var rep = (Player.reputation || {})[k.id] || 0;
                var rankIdx = (Player.socialRank || {})[k.id] || 0;
                var rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];
                var repPct = Math.max(0, Math.min(100, rep));
                var repColor = rep >= 70 ? '#55a868' : rep >= 40 ? '#ccb974' : '#c44e52';
                var isCitizen = Player.citizenshipKingdomId === k.id;
                html += '<div style="margin-bottom:8px;">';
                html += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:2px;">';
                html += '<span style="font-size:0.82rem;color:' + (k.color || '#ccc') + ';">' + (isCitizen ? '★ ' : '') + k.name + '</span>';
                html += '<span style="font-size:0.75rem;color:#aaa;">' + rank.icon + ' ' + rank.name + '</span>';
                html += '</div>';
                html += '<div style="display:flex;align-items:center;gap:6px;">';
                html += '<div style="flex:1;background:rgba(0,0,0,0.4);border:1px solid #444;border-radius:3px;height:10px;position:relative;">';
                html += '<div style="height:100%;width:' + repPct + '%;background:' + repColor + ';border-radius:2px;transition:width 0.3s;"></div>';
                html += '</div>';
                html += '<span style="font-size:0.75rem;color:' + repColor + ';min-width:30px;text-align:right;">' + Math.floor(rep) + '</span>';
                html += '</div>';
                html += '</div>';
            }
            html += '</div>';
        } catch(e) {}
        return html;
    }

    function openCharacterDialog() {
        if (typeof Player === 'undefined') return;

        const sexIcon = Player.sex === 'F' ? '♀' : '♂';
        let spouseName = 'None';
        var _spousePortrait = '';
        if (Player.spouseId) {
            try {
                const spouse = Engine.findPerson(Player.spouseId);
                if (spouse) {
                    _spousePortrait = (Player.getPersonPortrait) ? Player.getPersonPortrait(spouse) : '';
                    spouseName = (_spousePortrait ? _spousePortrait + ' ' : '') + spouse.firstName + ' ' + spouse.lastName;
                }
            } catch (e) { /* no-op */ }
        }

        // Children info with teach buttons
        let childrenHtml = '';
        if (Player.childrenIds && Player.childrenIds.length > 0) {
            for (const childId of Player.childrenIds) {
                try {
                    const child = Engine.findPerson(childId);
                    if (child && child.alive) {
                        const childPortrait = (typeof Player !== 'undefined' && Player.getPersonPortrait) ? Player.getPersonPortrait(child) : '';
                        const childSexIcon = child.sex === 'F' ? '♀' : '♂';
                        const passed = (Player.skillPointsPassedToChild && Player.skillPointsPassedToChild[childId]) || 0;
                        childrenHtml += `<div class="detail-row">
                            <span class="label">${childPortrait || childSexIcon} ${child.firstName}</span>
                            <span class="value">Age ${child.age}${passed > 0 ? ' (📚 ' + passed + '/5 taught)' : ''}</span>
                        </div>`;
                        if (child.age >= 10 && passed < 5 && Player.skillPoints >= 3) {
                            childrenHtml += `<div style="margin-left:20px;margin-bottom:4px;">
                                <button class="btn-medieval" data-action="openTeachChildDialog" data-id="${childId}" style="font-size:0.7rem;padding:3px 10px;">📚 Teach Skill (3 SP → 1 SP)</button>
                            </div>`;
                        } else if (child.age >= 10 && passed >= 5) {
                            childrenHtml += `<div style="margin-left:20px;margin-bottom:4px;font-size:0.7rem;color:var(--text-muted);">Max skills taught ✓</div>`;
                        }
                    }
                } catch (e) { /* no-op */ }
            }
        }
        if (!childrenHtml) childrenHtml = '<div class="text-dim">No children</div>';

        var _playerPortrait = Player.portrait || '';
        var _portraitDisplay = _playerPortrait ? '<span style="font-size:2.5rem;vertical-align:middle;margin-right:8px;">' + _playerPortrait + '</span>' : '';

        let html = `<div id="char-tab-bar" style="display:flex;gap:6px;margin:-4px -4px 10px;padding:6px 4px 8px;border-bottom:1px solid rgba(255,255,255,0.08);position:sticky;top:0;background:#1e160c;z-index:5;">
            <button class="btn-medieval" data-action="charTabSwitch" data-id="character" style="font-size:0.85rem;padding:6px 18px;flex:1;">👤 Character</button>
            <button class="btn-medieval" data-action="charTabSwitch" data-id="equipment" style="font-size:0.85rem;padding:6px 18px;flex:1;">🎒 Equipment</button>
        </div>
        <div class="detail-section">
            <h3>Identity</h3>
            <div style="text-align:center;margin-bottom:8px;">${_portraitDisplay}</div>
            <div class="detail-row"><span class="label">Name</span>
                <span class="value">${Player.fullName || 'Unknown'} <button data-action="openRenamePlayer" style="cursor:pointer;background:none;border:none;padding:0 2px;font-size:0.85em;opacity:0.6;vertical-align:middle;" title="Change name">✏️</button></span></div>
            <div class="detail-row"><span class="label">Sex</span>
                <span class="value">${sexIcon} ${Player.sex === 'F' ? 'Female' : 'Male'}</span></div>
            <div class="detail-row"><span class="label">Age</span>
                <span class="value">${Player.age || '?'}</span></div>
            <div class="detail-row"><span class="label">Spouse</span>
                <span class="value">${spouseName}</span></div>
        </div>`;

        // ── Health Panel ──
        const injuries = Player.injuries || [];
        const illnesses = Player.illnesses || [];
        if (injuries.length > 0 || illnesses.length > 0) {
            html += '<div class="detail-section" style="border:1px solid rgba(200,50,50,0.3);background:rgba(200,50,50,0.04);">';
            html += '<h3>🏥 Health</h3>';
            for (let i = 0; i < injuries.length; i++) {
                const inj = injuries[i];
                const sevColor = inj.severity === 'severe' ? 'var(--danger)' : inj.severity === 'moderate' ? '#e67e22' : '#2ecc71';
                html += '<div class="detail-row"><span class="label">🩹 ' + inj.name + '</span>';
                html += '<span class="value" style="color:' + sevColor + ';">' + inj.severity + (inj.treated ? ' (treating)' : ' (untreated!)') + '</span></div>';
            }
            for (let i = 0; i < illnesses.length; i++) {
                const ill = illnesses[i];
                const sevColor = ill.severity === 'severe' ? 'var(--danger)' : ill.severity === 'moderate' ? '#e67e22' : '#2ecc71';
                const illName = ill.name || (ill.type ? ill.type.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) : 'Unknown Illness');
                html += '<div class="detail-row"><span class="label">🤒 ' + illName + '</span>';
                html += '<span class="value" style="color:' + sevColor + ';">' + ill.severity + (ill.treated ? ' (treating)' : ' (untreated!)') + '</span></div>';
            }
            // Treatment buttons
            html += '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;">';
            html += '<button class="btn-medieval" data-action="openHealthDialog" style="font-size:0.75rem;padding:4px 12px;">🏥 Treat Conditions</button>';
            html += '</div>';
            html += '</div>';
        } else {
            // Check if family/companions are sick — show health button even when player is healthy
            var _charSickComps = (typeof Player !== 'undefined' && Player.getTreatableCompanions) ? Player.getTreatableCompanions() : [];
            if (_charSickComps.length > 0) {
                html += '<div class="detail-section" style="border:1px solid rgba(200,130,50,0.3);background:rgba(200,130,50,0.04);">';
                html += '<h3>🏥 Health</h3>';
                html += '<div class="detail-row"><span class="label">You</span><span class="value" style="color:#2ecc71;">Healthy</span></div>';
                for (var _csci = 0; _csci < _charSickComps.length; _csci++) {
                    var _csc = _charSickComps[_csci];
                    var _cscIcon = _csc.condition === 'sick' ? '🤒' : '🩹';
                    var _cscColor = _csc.severity === 'severe' ? 'var(--danger)' : _csc.severity === 'moderate' ? '#e67e22' : '#d4a017';
                    var _cscRole = _csc.role ? _csc.role.charAt(0).toUpperCase() + _csc.role.slice(1) : _csc.type;
                    html += '<div class="detail-row"><span class="label">' + _cscIcon + ' ' + _csc.name + ' <span style="font-size:0.7rem;color:#888;">(' + _cscRole + ')</span></span>';
                    html += '<span class="value" style="color:' + _cscColor + ';">' + (_csc.conditionDetail || _csc.condition).replace(/_/g, ' ') + '</span></div>';
                }
                html += '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:6px;">';
                html += '<button class="btn-medieval" data-action="openHealthDialog" style="font-size:0.75rem;padding:4px 12px;">🏥 Treat Companions</button>';
                html += '</div>';
                html += '</div>';
            }
        }

        // ── Military Status ──
        if (Player.militaryRank) {
            const rankLabel = Player.getMilitaryRankLabel ? Player.getMilitaryRankLabel() : Player.militaryRank;
            html += '<div class="detail-section">';
            html += '<h3>🎖️ Military</h3>';
            html += '<div class="detail-row"><span class="label">Rank</span><span class="value">' + rankLabel + '</span></div>';
            html += '<div class="detail-row"><span class="label">Status</span><span class="value">' + (Player.militaryActive ? '⚔️ Active Duty' : '🏠 Retired') + '</span></div>';
            html += '<div class="detail-row"><span class="label">Battles Survived</span><span class="value">' + (Player.battlesSurvived || 0) + '</span></div>';
            html += '</div>';
        }

        html += `<div class="detail-section">
            <h3>Children</h3>
            ${childrenHtml}
        </div>`;

        // Spouse detail section (when married)
        if (Player.spouseId) {
            try {
                const spouse = Engine.findPerson(Player.spouseId);
                if (spouse) {
                    html += '<div class="detail-section">';
                    html += '<h3>💑 Spouse</h3>';
                    html += buildSpouseDetailPanel(spouse);
                    html += '</div>';
                }
            } catch (e) { /* no-op */ }
        }

        // Heir traits (if any)
        if (Player.heirTraits && Player.heirTraits.length > 0) {
            html += '<div class="detail-section"><h3>🏷️ Traits</h3>';
            for (const trait of Player.heirTraits) {
                if (trait === 'well_raised') html += '<div class="detail-row"><span class="label">⭐ Well-Raised</span><span class="value">+5% XP gain</span></div>';
                if (trait === 'orphan') html += '<div class="detail-row"><span class="label">🏚️ Orphan</span><span class="value">-5% sell prices, +10% crime detection reduction</span></div>';
            }
            html += '</div>';
        }

        // Equipment section — market-based with quality tiers
        var weaponDisplay = 'None';
        var armorDisplay = 'None';
        if (Player.weapon) {
            var w = Player.weapon;
            if (typeof w === 'object') {
                // v9p33river321: quality vocabulary unified to basic/good/excellent
                var qualColor = w.quality === 'excellent' ? '#ffd700' : w.quality === 'good' ? '#55a868' : 'var(--parchment)';
                weaponDisplay = '⚔️ ' + w.name + ' <span style="color:' + qualColor + ';font-size:0.75rem;">(' + w.quality + ')</span> +' + Math.round(w.combatBonus * 100) + '% survival';
            } else {
                weaponDisplay = '⚔️ Sword (+20% survival)';
            }
        }
        if (Player.armor) {
            var a = Player.armor;
            if (typeof a === 'object') {
                var qualColorA = a.quality === 'excellent' ? '#ffd700' : a.quality === 'good' ? '#55a868' : 'var(--parchment)';
                armorDisplay = '🛡️ ' + a.name + ' <span style="color:' + qualColorA + ';font-size:0.75rem;">(' + a.quality + ')</span> +' + Math.round(a.combatBonus * 100) + '% survival';
            } else {
                armorDisplay = '🛡️ Armor (+30% survival)';
            }
        }

        html += '<div class="detail-section" data-char-tab="equipment"><h3>Equipment</h3>';
        html += '<div class="detail-row"><span class="label">Weapon</span><span class="value">' + weaponDisplay + '</span></div>';
        html += '<div class="detail-row"><span class="label">Armor</span><span class="value">' + armorDisplay + '</span></div>';

        // Unequip buttons
        var unequipBtns = '';
        if (Player.weapon) {
            unequipBtns += '<button class="btn-medieval" data-action="unequipWeapon" style="font-size:0.75rem;padding:4px 10px;">❌ Unequip Weapon</button>';
        }
        if (Player.armor) {
            unequipBtns += '<button class="btn-medieval" data-action="unequipArmor" style="font-size:0.75rem;padding:4px 10px;">❌ Unequip Armor</button>';
        }
        if (unequipBtns) {
            html += '<div style="display:flex;gap:8px;margin-top:6px;">' + unequipBtns + '</div>';
        }

        // Available equipment from local market
        var availWeapons = [];
        var availArmor = [];
        try {
            availWeapons = Player.getAvailableEquipment('weapons') || [];
            availArmor = Player.getAvailableEquipment('armor') || [];
        } catch (e) { /* no-op */ }

        if (availWeapons.length > 0 || availArmor.length > 0) {
            html += '<div style="margin-top:10px;border-top:1px solid rgba(255,255,255,0.1);padding-top:8px;">';
            html += '<div style="font-size:0.8rem;color:var(--gold);margin-bottom:6px;">⚒️ Available at Local Market</div>';
            for (var wi = 0; wi < availWeapons.length; wi++) {
                var ew = availWeapons[wi];
                // v9p33river321: quality vocabulary unified to basic/good/excellent
                var qc = ew.quality === 'excellent' ? '#ffd700' : ew.quality === 'good' ? '#55a868' : 'var(--parchment)';
                var bannedTag = ew.isBanned ? ' <span style="color:var(--danger);font-size:0.65rem;cursor:help;" title="Banned items are illegal to make or sell, but legal to buy or own in small amounts.">🚫 BANNED</span>' : '';
                html += '<div style="display:flex;align-items:center;gap:8px;margin:3px 0;">';
                html += '<span style="font-size:0.8rem;">⚔️ ' + ew.name + ' <span style="color:' + qc + ';font-size:0.7rem;">(' + ew.quality + ')</span> +' + Math.round(ew.combatBonus * 100) + '%' + bannedTag + '</span>';
                html += '<button class="btn-medieval" data-action="buyWeapon" data-id="' + ew.id + '" style="font-size:0.7rem;padding:3px 10px;margin-left:auto;">' + ew.price + 'g</button>';
                html += '</div>';
            }
            for (var ai = 0; ai < availArmor.length; ai++) {
                var ea = availArmor[ai];
                var qca = ea.quality === 'excellent' ? '#ffd700' : ea.quality === 'good' ? '#55a868' : 'var(--parchment)';
                var bannedTagA = ea.isBanned ? ' <span style="color:var(--danger);font-size:0.65rem;cursor:help;" title="Banned items are illegal to make or sell, but legal to buy or own in small amounts.">🚫 BANNED</span>' : '';
                html += '<div style="display:flex;align-items:center;gap:8px;margin:3px 0;">';
                html += '<span style="font-size:0.8rem;">🛡️ ' + ea.name + ' <span style="color:' + qca + ';font-size:0.7rem;">(' + ea.quality + ')</span> +' + Math.round(ea.combatBonus * 100) + '%' + bannedTagA + '</span>';
                html += '<button class="btn-medieval" data-action="buyArmor" data-id="' + ea.id + '" style="font-size:0.7rem;padding:3px 10px;margin-left:auto;">' + ea.price + 'g</button>';
                html += '</div>';
            }
            html += '</div>';
        } else {
            html += '<div style="margin-top:8px;font-size:0.75rem;color:#888;font-style:italic;">No weapons or armor available at this market.</div>';
        }

        // Equippable items from inventory
        var invEquipHtml = '';
        var equipResources = ['swords', 'swords_good', 'swords_excellent', 'bows', 'bows_good', 'bows_excellent', 'armor', 'armor_good', 'armor_excellent'];
        for (var ei = 0; ei < equipResources.length; ei++) {
            var eResId = equipResources[ei];
            var eHeld = (Player.inventory || {})[eResId] || 0;
            if (eHeld <= 0) continue;
            var eRes = findResource(eResId);
            if (!eRes) continue;
            // Check if already equipped
            var isEquippedWeapon = Player.weapon && typeof Player.weapon === 'object' && CONFIG.EQUIPMENT_TYPES;
            var matchW = false;
            var matchA = false;
            if (CONFIG.EQUIPMENT_TYPES) {
                for (var mw = 0; mw < (CONFIG.EQUIPMENT_TYPES.weapons || []).length; mw++) {
                    if (CONFIG.EQUIPMENT_TYPES.weapons[mw].resource === eResId && Player.weapon && Player.weapon.id === CONFIG.EQUIPMENT_TYPES.weapons[mw].id) matchW = true;
                }
                for (var ma = 0; ma < (CONFIG.EQUIPMENT_TYPES.armor || []).length; ma++) {
                    if (CONFIG.EQUIPMENT_TYPES.armor[ma].resource === eResId && Player.armor && Player.armor.id === CONFIG.EQUIPMENT_TYPES.armor[ma].id) matchA = true;
                }
            }
            var alreadyEquipped = matchW || matchA;
            invEquipHtml += '<div style="display:flex;align-items:center;gap:8px;margin:3px 0;">';
            invEquipHtml += '<span style="font-size:0.8rem;">' + (eRes.icon || '') + ' ' + eRes.name + ' ×' + eHeld + '</span>';
            if (!alreadyEquipped) {
                invEquipHtml += '<button class="btn-medieval" data-action="equipFromInventoryUI" data-id="' + eResId + '" style="font-size:0.7rem;padding:3px 10px;margin-left:auto;">Equip</button>';
            } else {
                invEquipHtml += '<span style="font-size:0.7rem;color:#55a868;margin-left:auto;">✓ Equipped</span>';
            }
            invEquipHtml += '</div>';
        }
        if (invEquipHtml) {
            html += '<div style="margin-top:10px;border-top:1px solid rgba(255,255,255,0.1);padding-top:8px;">';
            html += '<div style="font-size:0.8rem;color:var(--gold);margin-bottom:6px;">🎒 Equip from Inventory</div>';
            html += invEquipHtml;
            html += '</div>';
        }

        html += '</div>';

        // Personal Guards section (array-based with names)
        html += buildGuardSectionHTML();

        // Check port status for ship operations
        let isAtPort = false;
        try {
            const currentTown = Engine.findTown(Player.townId);
            isAtPort = currentTown && currentTown.isPort;
        } catch (e) { /* no-op */ }

        // Ships section
        html += `<div class="detail-section" data-char-tab="equipment">
            <h3>⛵ Ships</h3>`;
        if (Player.ships && Player.ships.length > 0) {
            for (const ship of Player.ships) {
                const shipCondCfg = CONFIG.CONDITION_LEVELS ? CONFIG.CONDITION_LEVELS[ship.degradeCondition || 'new'] : null;
                const shipCondIcon = shipCondCfg ? shipCondCfg.icon : '✨';
                const shipCondName = shipCondCfg ? shipCondCfg.name : 'New';
                const shipCondColor = (ship.degradeCondition === 'breaking') ? 'color:var(--danger);' : (ship.degradeCondition === 'destroyed') ? 'color:#888;' : (ship.degradeCondition === 'used') ? 'color:var(--gold);' : 'color:#55a868;';
                const shipNeedsRepair = ship.degradeCondition === 'used' || ship.degradeCondition === 'breaking' || (ship.hullHealth !== undefined && ship.hullHealth < 100);
                const shipSt = CONFIG.SHIP_TYPES ? CONFIG.SHIP_TYPES[ship.type] : null;
                const shipRepairCost = Player.getShipPrice ? Math.floor(Player.getShipPrice(ship.type) * (ship.degradeCondition === 'breaking' ? 0.3 : 0.2)) : '?';
                const hullPct = ship.hullHealth !== undefined ? ship.hullHealth : 100;
                const hullColor = hullPct > 70 ? '#55a868' : hullPct > 30 ? 'var(--gold)' : 'var(--danger)';
                const effCap = Player.getShipEffectiveCapacity ? Player.getShipEffectiveCapacity(ship) : ship.capacity;
                html += `<div style="border:1px solid var(--border);padding:6px;margin-bottom:6px;border-radius:4px;">
                    <div class="detail-row">
                        <span class="label">${shipSt ? shipSt.icon : '⛵'} ${ship.name} ${shipCondIcon}</span>
                        <span class="value" style="${shipCondColor}">${shipCondName}${shipCondCfg && shipCondCfg.efficiency < 1 ? ' (' + Math.round(shipCondCfg.efficiency * 100) + '%)' : ''}</span>
                    </div>
                    <div style="font-size:0.75rem;color:#b0b0b0;margin-top:2px;">
                        Cap: ${effCap} | Spd: ${(ship.speed || 1.0).toFixed(1)}x | Pass: ${ship.passengers || 0} | 🛡️${ship.defense || 0} | 💣${ship.cannons || 0}
                    </div>
                    <div style="font-size:0.75rem;margin-top:2px;">
                        <span style="color:${hullColor}">Hull: ${hullPct}%</span>
                        ${(ship.addons && ship.addons.length > 0) ? ' | Addons: ' + ship.addons.map(function(a) { var ac = CONFIG.SHIP_ADDONS ? CONFIG.SHIP_ADDONS[a] : null; return ac ? ac.name : a; }).join(', ') : ''}
                    </div>
                    ${shipNeedsRepair && isAtPort ? '<button class="btn-trade buy" style="font-size:0.7rem;margin-top:4px;background:rgba(200,120,0,0.35);border-color:rgba(220,140,20,0.6);color:#f5deb3;" data-action="repairShip" data-id="' + ship.id + '">🔨 Repair (' + shipRepairCost + 'g)</button>' : ''}
                    ${isAtPort && ship.addons && ship.maxAddons && ship.addons.length < ship.maxAddons ? ' <button class="btn-trade buy" style="font-size:0.7rem;margin-top:4px;background:rgba(0,100,140,0.35);border-color:rgba(0,160,200,0.6);color:#c8e8f0;" data-action="showShipAddons" data-id="' + ship.id + '">🔧 Addons (' + ship.addons.length + '/' + ship.maxAddons + ')</button>' : ''}
                </div>`;
            }
        } else {
            html += `<div class="text-dim">No ships owned</div>`;
        }
        // v9p33river81: Build a Ship moved out of the Character menu entirely
        // (was duplicated here in addition to the Ships dialog). Build via the
        // dedicated Ships menu instead, or wherever ship-building is exposed.
        html += `</div>`;

        // ── Storage / Capacity Section ──
        html += `<div class="detail-section" data-char-tab="equipment"><h3>📦 Storage & Capacity</h3>`;

        // ── Horses Section ──
        var maxHorsesDisp = (CONFIG.MAX_HORSES || 2) + (Player.hasSkill && Player.hasSkill('horse_mastery') ? 2 : 0);
        html += `<div style="margin-bottom:8px;"><strong>🐴 Mounted Horses (${Player.horses ? Player.horses.length : 0}/${maxHorsesDisp})</strong></div>`;
        if (Player.horses && Player.horses.length > 0) {
            var invSaddles = (Player.inventory && Player.inventory.saddles) || 0;
            for (const horse of Player.horses) {
                html += `<div style="display:flex;justify-content:space-between;align-items:center;padding:3px 0;font-size:0.75rem;">`;
                html += `<span>🐴 <strong>${horse.name}</strong> — Stamina: ${horse.stamina}, Speed: ${horse.speed.toFixed(1)}x`;
                if (horse.saddled) html += ` <span style="color:#7cb342;">🪑 Saddled</span>`;
                html += `</span>`;
                html += `<div style="display:flex;gap:4px;">`;
                if (horse.saddled) {
                    html += `<button class="btn-medieval" data-action="unmountSaddle" data-id="${horse.id}" style="font-size:0.7rem;padding:2px 6px;">🪑 Remove Saddle</button>`;
                } else if (invSaddles > 0) {
                    html += `<button class="btn-medieval" data-action="mountSaddle" data-id="${horse.id}" style="font-size:0.7rem;padding:2px 6px;">🪑 Saddle</button>`;
                }
                html += `<button class="btn-medieval" data-action="dismountHorseUI" data-id="${horse.id}" style="font-size:0.7rem;padding:2px 6px;">⬇️ Dismount</button>`;
                html += `<button class="btn-medieval" data-action="sellHorse" data-id="${horse.id}" style="font-size:0.7rem;padding:2px 6px;">💰 Sell</button>`;
                html += `</div></div>`;
            }
            if (invSaddles > 0) {
                html += `<div style="font-size:0.65rem;color:#aaa;margin-top:2px;">🪑 ${invSaddles} saddle${invSaddles > 1 ? 's' : ''} in inventory</div>`;
            }
        } else {
            html += `<div style="font-size:0.72rem;color:var(--text-muted);margin-bottom:4px;">No horses mounted. Buy or mount from inventory. (+${CONFIG.HORSE_CARRY_BONUS || 40} carry each).</div>`;
        }
        // Mount from inventory
        var invHorses = (Player.inventory && Player.inventory.horses) || 0;
        if (invHorses > 0) {
            html += `<div style="margin-top:4px;"><button class="btn-medieval" data-action="mountHorseUI" style="font-size:0.75rem;padding:4px 10px;">🐴 Mount Horse from Inventory (${invHorses} available)</button></div>`;
        }

        // ── Horse Permit (Draft Animal Law) ──
        if (Player.townId) {
            var permitTown = Engine.findTown(Player.townId);
            var permitKingdom = permitTown ? Engine.findKingdom(permitTown.kingdomId) : null;
            if (permitKingdom && Engine.hasSpecialLaw && Engine.hasSpecialLaw(permitKingdom, 'draft_animal_law')) {
                var permitCfg = CONFIG.DRAFT_ANIMAL_LAW || {};
                var permitRank = Player.getEffectiveRank ? Player.getEffectiveRank(permitKingdom.id) : (Player.state.socialRank[permitKingdom.id] || 0);
                var permitExempt = permitRank >= (permitCfg.minRankExempt || 2);
                if (permitExempt) {
                    html += `<div style="font-size:0.72rem;color:#8b8;margin:4px 0;padding:4px 6px;background:rgba(0,100,0,0.15);border-radius:4px;">🐴 <strong>Draft Animal Law:</strong> You are exempt (Burgher+ rank).</div>`;
                } else {
                    var permit = Player.state.horsePermit ? Player.state.horsePermit[permitKingdom.id] : null;
                    var hasValidPermit = permit && permit.expiresDay > Engine.getDay();
                    if (hasValidPermit) {
                        var daysLeft = permit.expiresDay - Engine.getDay();
                        html += `<div style="font-size:0.72rem;color:#8b8;margin:4px 0;padding:4px 6px;background:rgba(0,100,0,0.15);border-radius:4px;">🐴 <strong>Horse Permit:</strong> Valid for ${daysLeft} more days in ${permitKingdom.name}.</div>`;
                    } else {
                        var permitCostMonthly = permitCfg.permitCostMonthly || 100;
                        var permitCostAnnual = permitCfg.permitCostAnnual || 1000;
                        html += `<div style="font-size:0.72rem;color:#c88;margin:4px 0;padding:4px 6px;background:rgba(140,30,30,0.25);border-radius:4px;">`;
                        html += `⚠️ <strong>${permitKingdom.name}</strong> requires a horse permit for commoners (Draft Animal Law).`;
                        html += `<br><button class="btn-medieval" data-action="buyHorsePermitAndOpenCharacterPanel" data-id="${permitKingdom.id}" data-val="monthly" style="font-size:0.7rem;padding:2px 8px;margin-top:4px;">🐴 30-Day Permit (${permitCostMonthly}g)</button>`;
                        html += ` <button class="btn-medieval" data-action="buyHorsePermitAndOpenCharacterPanel" data-id="${permitKingdom.id}" data-val="annual" style="font-size:0.7rem;padding:2px 8px;margin-top:4px;">🐴 Annual Permit (${permitCostAnnual}g)</button>`;
                        html += `</div>`;
                    }
                }
            }
        }

        const charCarriedWeight = Player.getCarriedWeight ? Player.getCarriedWeight() : 0;
        const charCarryCap = Player.getCarryCapacity ? Player.getCarryCapacity() : 20;
        const charContainer = Player.storageContainer && CONFIG.STORAGE_CONTAINERS[Player.storageContainer]
            ? CONFIG.STORAGE_CONTAINERS[Player.storageContainer] : null;
        const charContainerLabel = charContainer ? (charContainer.icon + ' ' + charContainer.name) : '🚶 None (on person)';
        html += `<div class="detail-row"><span class="label">Container</span><span class="value">${charContainerLabel}</span></div>`;
        // Dismount current container button
        if (charContainer) {
            html += `<div style="margin-top:3px;"><button class="btn-medieval" data-action="dismountContainerUI" style="font-size:0.7rem;padding:2px 8px;">⬇️ Dismount ${charContainer.name} to Inventory</button></div>`;
        }
        html += `<div class="detail-row"><span class="label">Carrying</span><span class="value">${Math.round(charCarriedWeight)} / ${charCarryCap} weight</span></div>`;

        // Mount from inventory — show containers the player has in inventory
        let mountHtml = '';
        var containerTypes = ['cart', 'small_wagon', 'wagon', 'large_wagon', 'backpack'];
        for (var mci = 0; mci < containerTypes.length; mci++) {
            var mcId = containerTypes[mci];
            var mcCfg = CONFIG.STORAGE_CONTAINERS[mcId];
            if (!mcCfg) continue;
            var invCount = (Player.inventory && Player.inventory[mcId]) || 0;
            if (invCount <= 0) continue;
            if (charContainer && mcCfg.capacityMult <= charContainer.capacityMult) continue;
            var horsesOk = (Player.horses ? Player.horses.length : 0) >= (mcCfg.horsesRequired || 0);
            var horseNote = !horsesOk ? ' (need ' + mcCfg.horsesRequired + ' 🐴)' : '';
            mountHtml += `<button class="btn-medieval" data-action="mountContainerUI" data-id="${mcId}" style="font-size:0.7rem;padding:3px 10px;margin:2px;${!horsesOk ? 'opacity:0.5;' : ''}" ${!horsesOk ? 'disabled' : ''}>${mcCfg.icon} Mount ${mcCfg.name} (${invCount} owned) — ${mcCfg.capacityMult * (CONFIG.PLAYER_BASE_CARRY || 20)} cap${horseNote}</button>`;
        }
        if (mountHtml) {
            html += `<div style="margin-top:4px;"><div style="font-size:0.75rem;color:var(--text-muted);margin-bottom:3px;">📦 Mount from inventory:</div><div style="display:flex;flex-wrap:wrap;gap:4px;">${mountHtml}</div></div>`;
        }

        // Available upgrades (craft from materials)
        // v9p33river337: backpack/cart/wagon crafting requires a home with
        // workshop in the player's current town (see Player.buyContainer
        // gate at player_inventory.js:917). Disable the button visually
        // and add a clear note if no workshop is available — previously
        // players had to click each button to discover the requirement.
        // EXCEPTION: if the player owns a ready-made copy in inventory
        // (bought from a market), they can equip it without a workshop.
        var _charHouseInTown = (typeof Player !== 'undefined' && Player.getHouseInTown) ? Player.getHouseInTown(Player.townId) : null;
        var _charHt = _charHouseInTown ? CONFIG.HOUSING_TYPES.find(function(h) { return h.id === _charHouseInTown.type; }) : null;
        var _charHasWorkshop = (_charHt && _charHt.hasWorkshop) || (_charHouseInTown && _charHouseInTown.addons && _charHouseInTown.addons.indexOf('workshop') >= 0);
        let upgradeHtml = '';
        for (const [cId, cCfg] of Object.entries(CONFIG.STORAGE_CONTAINERS)) {
            if (charContainer && cCfg.capacityMult <= charContainer.capacityMult) continue;
            let upgradeCost = cCfg.cost;
            if (charContainer) upgradeCost -= Math.floor(charContainer.cost * 0.5);
            let matStr = '';
            if (cCfg.materials) {
                matStr = ' + ' + Object.entries(cCfg.materials).map(function(e) {
                    var res = findResource(e[0]);
                    return (res ? res.icon || '' : '') + e[1];
                }).join(', ');
            }
            // v9p33river337: per-button workshop gate. Allow if player has
            // a ready-made one in inventory (no crafting needed).
            var _upgInvHas = (Player.inventory && Player.inventory[cId]) || 0;
            var _upgNeedsWorkshop = _upgInvHas <= 0 && !_charHasWorkshop;
            var _upgDisabled = _upgNeedsWorkshop ? ' disabled' : '';
            var _upgStyle = _upgNeedsWorkshop ? 'opacity:0.5;cursor:not-allowed;' : '';
            var _upgTitle = _upgNeedsWorkshop ? ' title="Requires a home with workshop in this town to craft"' : '';
            upgradeHtml += `<button class="btn-medieval" data-action="buyContainer" data-id="${cId}" style="font-size:0.7rem;padding:3px 10px;margin:2px;${_upgStyle}"${_upgDisabled}${_upgTitle}>${cCfg.icon} ${cCfg.name} (${upgradeCost}g${matStr}) — ${cCfg.capacityMult * (CONFIG.PLAYER_BASE_CARRY || 20)} cap</button>`;
        }
        if (upgradeHtml) {
            html += `<div style="margin-top:6px;"><div style="font-size:0.75rem;color:var(--text-muted);margin-bottom:4px;">Available upgrades:</div><div style="display:flex;flex-wrap:wrap;gap:4px;">${upgradeHtml}</div>`;
            // v9p33river337: explanatory note when the player lacks a workshop
            if (!_charHasWorkshop) {
                html += `<div style="font-size:0.7rem;color:#cc9966;margin-top:4px;font-style:italic;">⚠️ Crafting requires a home with workshop in this town. Buy a ready-made container from a market or canvas workshop instead.</div>`;
            }
            html += `</div>`;
        } else {
            html += `<div style="font-size:0.75rem;color:#55a868;margin-top:4px;">✅ Maximum container owned</div>`;
        }
        // Town storage summary
        if (Player.townId) {
            const charTownStorageCap = Player.getTownStorageCapacity ? Player.getTownStorageCapacity() : 0;
            const charTownStorageUsed = Player.getTownStorageUsed ? Player.getTownStorageUsed() : 0;
            if (charTownStorageCap > 0) {
                html += `<div style="margin-top:8px;border-top:1px solid var(--border);padding-top:6px;">`;
                html += `<div class="detail-row"><span class="label">📦 Town Warehouse</span><span class="value">${Math.round(charTownStorageUsed)} / ${charTownStorageCap} weight</span></div>`;
                const tsItems = (Player.townStorage && Player.townStorage[Player.townId]) || {};
                const tsEntries = Object.entries(tsItems).filter(([, q]) => q > 0);
                if (tsEntries.length > 0) {
                    html += `<div style="font-size:0.72rem;margin-top:4px;color:var(--text-muted);">Stored: `;
                    html += tsEntries.map(([rId, q]) => { const r = findResource(rId); return (r ? r.icon + ' ' : '') + (r ? r.name : rId) + ' (' + q + ')'; }).join(', ');
                    html += `</div>`;
                }
                html += `</div>`;
            } else {
                html += `<div style="font-size:0.72rem;color:var(--text-muted);margin-top:4px;">No warehouses in current town</div>`;
            }
        }
        html += `</div>`;

        html += `<div class="detail-section">
            <h3>Statistics</h3>
            <div class="detail-row"><span class="label">Net Worth</span>
                <span class="value gold-value">${formatGold(Player.getNetWorth ? Player.getNetWorth() : Player.gold)}</span></div>
            <div class="detail-row"><span class="label">Days Played</span>
                <span class="value">${Player.stats ? Player.stats.daysPlayed : 0}</span></div>
            <div class="detail-row"><span class="label">Trades Made</span>
                <span class="value">${Player.stats ? Player.stats.tradesCompleted : 0}</span></div>
            <div class="detail-row"><span class="label">Gold Earned</span>
                <span class="value">${formatGold(Player.stats ? Player.stats.totalGoldEarned : 0)}</span></div>
            <div class="detail-row"><span class="label">Gold Spent</span>
                <span class="value">${formatGold(Player.stats ? Player.stats.totalGoldSpent : 0)}</span></div>
        </div>`;

        // Notoriety section
        var _charNotoriety = Player.notoriety || 0;
        var _notColor = _charNotoriety >= (CONFIG.NOTORIETY_DANGER_THRESHOLD || 70) ? '#c44e52' : _charNotoriety >= 30 ? '#ccb974' : '#55a868';
        html += '<div class="detail-section"><h3>🕵️ Notoriety</h3>';
        html += '<div style="display:flex;align-items:center;gap:8px;">';
        html += '<div style="flex:1;background:rgba(0,0,0,0.4);border:1px solid #555;border-radius:4px;height:14px;position:relative;">';
        html += '<div style="height:100%;width:' + Math.min(100, _charNotoriety) + '%;background:' + _notColor + ';border-radius:3px;transition:width 0.3s;"></div>';
        html += '</div>';
        html += '<span style="font-size:0.85rem;color:' + _notColor + ';font-weight:bold;">' + Math.floor(_charNotoriety) + '/100</span>';
        html += '</div>';
        html += '<div style="font-size:0.72rem;color:#999;margin-top:4px;">How known you are to law enforcement. High notoriety increases detection chance for illegal activities.</div>';
        html += '</div>';

        // Kingdom reputation bars
        html += _buildKingdomRepBarsHtml();

        // Social Status section
        html += buildSocialStatusHtml();

        // ── War Advisory Section ──
        html += _buildWarAdvisoryHtml();

        // Journal & Financial Report buttons — moved to header area
        // (removed from here, now in title bar)

        openModal(`👤 ${Player.fullName || 'Character'}`, html);

        // v9p33river194: apply current tab (default character) after render
        setTimeout(function() { _applyCharTab(window._charActiveTab || 'character'); }, 0);

        // Inject buttons next to the modal title
        setTimeout(function() {
            var mt = document.getElementById('modalTitle');
            if (mt) {
                mt.innerHTML = mt.textContent +
                    ' <button class="btn-medieval" data-action="openJournal" style="font-size:0.65rem;padding:3px 10px;margin-left:10px;vertical-align:middle;">📖 Journal</button>' +
                    ' <button class="btn-medieval" data-action="openFinancialReport" style="font-size:0.65rem;padding:3px 10px;vertical-align:middle;">📊 Financial Report</button>' +
                    ' <button class="btn-medieval" data-action="openPlayerImpact" style="font-size:0.65rem;padding:3px 10px;vertical-align:middle;">🏆 Player Impact</button>' +
                    ' <button class="btn-medieval" data-action="openInventory" style="font-size:0.65rem;padding:3px 10px;vertical-align:middle;">📦 Inventory</button>';
            }
        }, 30);
    }

    // v9p33river194: tab switcher for the Character modal — toggles which
    // detail-section blocks are visible. 'character' = all sections without
    // data-char-tab="equipment"; 'equipment' = only those that DO have it.
    function _applyCharTab(tab) {
        var sections = document.querySelectorAll('.modal-body .detail-section');
        for (var i = 0; i < sections.length; i++) {
            var s = sections[i];
            var ct = s.getAttribute('data-char-tab') || 'character';
            s.style.display = (ct === tab) ? '' : 'none';
        }
        // Highlight active tab button
        var bar = document.getElementById('char-tab-bar');
        if (bar) {
            var btns = bar.querySelectorAll('button[data-action="charTabSwitch"]');
            for (var b = 0; b < btns.length; b++) {
                var isActive = btns[b].getAttribute('data-id') === tab;
                btns[b].style.opacity = isActive ? '1' : '0.55';
                btns[b].style.borderColor = isActive ? 'var(--gold)' : 'var(--panel-border)';
            }
        }
        window._charActiveTab = tab;
    }

    function _buildWarAdvisoryHtml() {
        if (typeof Player === 'undefined' || typeof Engine === 'undefined') return '';
        var allegiances = Player.warAllegiances || Player.state.warAllegiances || {};
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        var html = '';
        var hasAny = false;

        // Collect active war entries
        var activeEntries = [];
        var endedEntries = [];
        for (var warId in allegiances) {
            var alleg = allegiances[warId];
            var war = activeWars[warId];
            if (war) {
                activeEntries.push({ warId: warId, alleg: alleg, war: war });
            } else {
                endedEntries.push({ warId: warId, alleg: alleg });
            }
        }

        if (activeEntries.length === 0 && endedEntries.length === 0) return '';
        hasAny = true;

        html += '<div class="detail-section" style="border:1px solid rgba(200,80,80,0.3);background:rgba(200,80,80,0.04);">';
        html += '<h3>⚔️ War Status & Advisory</h3>';

        // Active wars
        for (var ai = 0; ai < activeEntries.length; ai++) {
            var entry = activeEntries[ai];
            var w = entry.war;
            var a = entry.alleg;
            var kA = Engine.findKingdom(w.kingdomA);
            var kB = Engine.findKingdom(w.kingdomB);
            var nameA = kA ? kA.name : 'Kingdom A';
            var nameB = kB ? kB.name : 'Kingdom B';
            var daysSinceStart = (Engine.getDay() - (w.startDay || 0));

            html += '<div style="background:rgba(0,0,0,0.25);border:1px solid rgba(200,80,80,0.25);border-radius:6px;padding:10px;margin-bottom:8px;">';
            html += '<div style="font-weight:bold;color:#ff6644;margin-bottom:6px;">🔥 ' + nameA + ' vs ' + nameB + ' <span style="font-size:0.75rem;color:#888;">(Day ' + daysSinceStart + ' of war)</span></div>';

            // Current allegiance
            var sideLabel, sideColor;
            if (a.side === 'neutral') {
                sideLabel = '🕊️ Neutral';
                sideColor = '#aab';
            } else {
                var sideK = Engine.findKingdom(a.side);
                sideLabel = '⚔️ Allied with ' + (sideK ? sideK.name : a.side);
                sideColor = '#4ecdc4';
            }
            html += '<div class="detail-row"><span class="label">Your Stance</span><span class="value" style="color:' + sideColor + ';">' + sideLabel + '</span></div>';

            // Advisory & consequences based on stance
            if (a.side === 'neutral') {
                html += '<div style="margin-top:8px;padding:8px;background:rgba(170,170,187,0.08);border-radius:4px;font-size:0.8rem;">';
                html += '<div style="color:#ccb974;font-weight:bold;margin-bottom:4px;">📋 Neutral Advisory</div>';
                html += '<div style="color:#bbb;margin-bottom:3px;">✅ You can trade freely with <strong>both</strong> kingdoms, including military goods.</div>';
                html += '<div style="color:#bbb;margin-bottom:3px;">✅ No reputation change on war end — no reward, but no punishment either.</div>';
                html += '<div style="color:#e67e22;margin-bottom:3px;">⚠️ <strong>Caution:</strong> Military goods sales to both sides are tracked. Keep them balanced!</div>';
                html += '<div style="color:#aaa;margin-bottom:2px;padding-left:12px;">• At <strong>3:1</strong> sales ratio → extra 10% tax from the disadvantaged kingdom</div>';
                html += '<div style="color:#aaa;margin-bottom:2px;padding-left:12px;">• At <strong>5:1</strong> ratio → risk of buildings being seized in the undersupplied kingdom</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• At <strong>10:1</strong> ratio → total asset seizure + reputation destroyed in that kingdom</div>';

                // Show current sales imbalance if any
                var salesA = a.salesA || 0;
                var salesB = a.salesB || 0;
                if (salesA > 0 || salesB > 0) {
                    var maxSales = Math.max(salesA, salesB, 1);
                    var minSales = Math.min(salesA, salesB);
                    var ratio = minSales > 0 ? (maxSales / minSales) : (maxSales > 0 ? maxSales : 0);
                    var ratioColor = ratio >= 5 ? '#c44e52' : ratio >= 3 ? '#e67e22' : '#55a868';
                    html += '<div style="margin-top:6px;padding-top:6px;border-top:1px solid rgba(255,255,255,0.08);">';
                    html += '<div style="color:#aaa;margin-bottom:3px;">📊 Military sales: <strong>' + nameA + '</strong>: ' + salesA + ' | <strong>' + nameB + '</strong>: ' + salesB + '</div>';
                    if (ratio > 1) {
                        html += '<div style="color:' + ratioColor + ';">Ratio: ' + ratio.toFixed(1) + ':1 ' + (ratio >= 5 ? '— ⚠️ DANGER!' : ratio >= 3 ? '— ⚠️ Taxed' : '— Safe') + '</div>';
                    }
                    html += '</div>';
                }
                html += '</div>';
            } else {
                // Allied with a side
                var alliedK = Engine.findKingdom(a.side);
                var enemyId = a.side === w.kingdomA ? w.kingdomB : w.kingdomA;
                var enemyK = Engine.findKingdom(enemyId);
                var alliedName = alliedK ? alliedK.name : 'your ally';
                var enemyName = enemyK ? enemyK.name : 'the enemy';

                html += '<div style="margin-top:8px;padding:8px;background:rgba(78,205,196,0.08);border-radius:4px;font-size:0.8rem;">';
                html += '<div style="color:#4ecdc4;font-weight:bold;margin-bottom:4px;">📋 Allied Advisory</div>';
                html += '<div style="color:#bbb;margin-bottom:3px;">✅ Trade freely with <strong>' + alliedName + '</strong> — they appreciate your support.</div>';
                html += '<div style="color:#c44e52;margin-bottom:3px;">🚫 <strong>Cannot</strong> sell military goods (weapons, armor, horses) to <strong>' + enemyName + '</strong>.</div>';
                html += '<div style="color:#c44e52;margin-bottom:3px;">🚫 Cannot hire workers in military/horse buildings in <strong>' + enemyName + '</strong>.</div>';
                html += '<div style="color:#e67e22;margin-bottom:3px;">⚠️ +50% bandit/soldier encounters and +25% danger traveling in <strong>' + enemyName + '</strong>.</div>';
                html += '<div style="color:#bbb;margin-bottom:6px;">💡 Non-military trade with ' + enemyName + ' is still allowed but may draw suspicion.</div>';
                // Military sales tracking
                var _salesTotal = a.militarySalesTotal || 0;
                if (_salesTotal > 0) {
                    html += '<div style="color:#aaa;margin-bottom:6px;">📊 Military goods/horses sold to ' + alliedName + ': <strong>' + _salesTotal + '</strong> (scales rewards/penalties)</div>';
                }
                html += '<div style="color:#ccb974;font-weight:bold;margin-bottom:4px;">If ' + alliedName + ' wins:</div>';
                html += '<div style="color:#55a868;margin-bottom:2px;padding-left:12px;">• +5 to +20 kingdom reputation with ' + alliedName + ' (scales with military sales & status)</div>';
                html += '<div style="color:#55a868;margin-bottom:2px;padding-left:12px;">• +10 relationship with the king, +5 with all nobles</div>';
                html += '<div style="color:#55a868;margin-bottom:2px;padding-left:12px;">• 🎖️ War Hero achievement</div>';
                html += '<div style="color:#55a868;margin-bottom:2px;padding-left:12px;">• One guaranteed petition (no signatures needed)</div>';
                html += '<div style="color:#55a868;margin-bottom:4px;padding-left:12px;">• Gold reward (up to 5,000g, scales with contributions & status)</div>';
                html += '<div style="color:#c44e52;font-weight:bold;margin-bottom:4px;">If ' + alliedName + ' loses:</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• -10 to -20 rep with <strong>both</strong> kingdoms</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• -10 relationship with <strong>both</strong> kings, -5 with all nobles</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• Up to 5,000g retribution payment</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• Buildings in ' + enemyName + ' territory seized</div>';
                html += '<div style="color:#c44e52;margin-bottom:2px;padding-left:12px;">• Possible jail time (winning king decides)</div>';
                html += '</div>';
            }

            // Change allegiance button (allowed for non-nobles, with penalties)
            var _isNobleInAlly = a.side !== 'neutral' && Player.state && Player.state.socialRank && (Player.state.socialRank[a.side] || 0) >= 4;
            html += '<div style="margin-top:6px;text-align:center;">';
            if (_isNobleInAlly) {
                html += '<button class="btn-medieval" disabled style="font-size:0.75rem;padding:4px 12px;opacity:0.4;cursor:not-allowed;">🔄 Change Allegiance</button>';
                html += '<div style="font-size:0.7rem;color:#c44e52;margin-top:3px;">⚠️ Nobles cannot change allegiance.</div>';
            } else {
                html += '<button class="btn-medieval" data-action="_reopenWarChoice" data-id="' + entry.warId + '" style="font-size:0.75rem;padding:4px 12px;">🔄 Change Allegiance</button>';
                if (a.side !== 'neutral') {
                    html += '<div style="font-size:0.7rem;color:#e67e22;margin-top:3px;">⚠️ Changing costs -20 rep from current ally, -10 king relationship, -5 all nobles.</div>';
                }
            }
            html += '</div>';

            html += '</div>';
        }

        // Ended wars (brief summary)
        if (endedEntries.length > 0) {
            html += '<div style="margin-top:6px;border-top:1px solid rgba(255,255,255,0.1);padding-top:6px;">';
            html += '<div style="font-size:0.75rem;color:#888;margin-bottom:4px;">Past Wars:</div>';
            for (var ei = 0; ei < endedEntries.length; ei++) {
                var ended = endedEntries[ei];
                var sLabel = ended.alleg.side === 'neutral' ? '🕊️ Neutral' : '⚔️ Sided with ' + (Engine.findKingdom(ended.alleg.side) ? Engine.findKingdom(ended.alleg.side).name : ended.alleg.side);
                html += '<div style="font-size:0.75rem;color:#777;margin-bottom:2px;">' + sLabel + ' — War ended</div>';
            }
            html += '</div>';
        }

        html += '</div>';
        return html;
    }

    function _reopenWarChoice(warId) {
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        var war = activeWars[warId];
        if (!war) { toast('This war has ended.', 'warning'); return; }
        var kA = Engine.findKingdom(war.kingdomA);
        var kB = Engine.findKingdom(war.kingdomB);
        closeModal();
        showWarAllegiancePopup({
            warId: warId,
            kingdomA: war.kingdomA,
            kingdomB: war.kingdomB,
            nameA: kA ? kA.name : 'Kingdom A',
            nameB: kB ? kB.name : 'Kingdom B',
            strengthA: war.strengthAtStart ? (war.strengthAtStart[war.kingdomA] || 0) : 0,
            strengthB: war.strengthAtStart ? (war.strengthAtStart[war.kingdomB] || 0) : 0
        });
    }

    // ═══════════════════════════════════════════════════════════
    //  FINANCIAL REPORT
    // ═══════════════════════════════════════════════════════════
    function openFinancialReport() {
        if (typeof Player === 'undefined') return;

        var ledger = Player.state.financialLedger || [];
        var currentDay = Engine.getDay();
        var cutoff = currentDay - 30;

        if (ledger.length === 0) {
            openModal('📊 Financial Report', '<div style="padding:20px;text-align:center;color:#aaa;">No financial data yet. Transactions will be tracked going forward.</div>');
            return;
        }

        // Filter to last 30 days
        var recent = [];
        for (var i = 0; i < ledger.length; i++) {
            if (ledger[i].day >= cutoff) recent.push(ledger[i]);
        }

        // Category display config
        var categoryInfo = {
            trading: '📈 Trading',
            jobs: '💼 Jobs',
            rent_income: '🏠 Rental Income',
            caravan_sales: '🐪 Caravan Sales',
            kingdom_sales: '👑 Kingdom Sales',
            land: '🏞️ Land',
            loans: '💰 Loans',
            buildings: '🏭 Buildings',
            building_sales: '🏭 Building Sales',
            wages: '👷 Wages',
            caravan_wages: '🐪 Caravan Wages',
            caravan_costs: '🐪 Caravan Costs',
            travel: '🗺️ Travel',
            taxes: '🏛️ Taxes',
            fines: '⚖️ Fines',
            licenses: '📜 Licenses',
            food_drink: '🍞 Food & Drink',
            housing: '🏠 Housing',
            guild: '⚔️ Guild Fees',
            debt_payment: '💸 Debt Payments',
            bankruptcy: '💥 Bankruptcy',
            other: '❓ Other'
        };

        // Group by category
        var incomeGroups = {};
        var expenseGroups = {};
        var totalIncome = 0;
        var totalExpenses = 0;

        for (var j = 0; j < recent.length; j++) {
            var entry = recent[j];
            var cat = entry.category || 'other';
            if (entry.amount >= 0) {
                if (!incomeGroups[cat]) incomeGroups[cat] = { total: 0, count: 0 };
                incomeGroups[cat].total += entry.amount;
                incomeGroups[cat].count++;
                totalIncome += entry.amount;
            } else {
                if (!expenseGroups[cat]) expenseGroups[cat] = { total: 0, count: 0 };
                expenseGroups[cat].total += Math.abs(entry.amount);
                expenseGroups[cat].count++;
                totalExpenses += Math.abs(entry.amount);
            }
        }

        function fmtGold(val) { return formatGold(Math.round(val)); }
        function posNeg(val) {
            if (val > 0) return 'color:#5ac85a';
            if (val < 0) return 'color:#e74c3c';
            return 'color:#aaa';
        }

        // Build income rows
        var incomeRows = '';
        var incCats = Object.keys(incomeGroups).sort(function(a, b) { return incomeGroups[b].total - incomeGroups[a].total; });
        for (var ic = 0; ic < incCats.length; ic++) {
            var ck = incCats[ic];
            var g = incomeGroups[ck];
            var label = categoryInfo[ck] || ('❓ ' + ck);
            incomeRows += '<div class="detail-row"><span class="label">' + label + ' <span style="color:#666;font-size:0.75rem;">(' + g.count + ')</span></span><span class="value" style="color:#5ac85a">' + fmtGold(g.total) + '</span></div>';
        }
        if (!incomeRows) incomeRows = '<div class="detail-row"><span class="label" style="color:#aaa;">No income in last 30 days</span><span class="value">—</span></div>';

        // Build expense rows
        var expenseRows = '';
        var expCats = Object.keys(expenseGroups).sort(function(a, b) { return expenseGroups[b].total - expenseGroups[a].total; });
        for (var ec = 0; ec < expCats.length; ec++) {
            var ek = expCats[ec];
            var ge = expenseGroups[ek];
            var elabel = categoryInfo[ek] || ('❓ ' + ek);
            expenseRows += '<div class="detail-row"><span class="label">' + elabel + ' <span style="color:#666;font-size:0.75rem;">(' + ge.count + ')</span></span><span class="value" style="color:#e74c3c">-' + fmtGold(ge.total) + '</span></div>';
        }
        if (!expenseRows) expenseRows = '<div class="detail-row"><span class="label" style="color:#aaa;">No expenses in last 30 days</span><span class="value">—</span></div>';

        // Summary calculations
        var netIncome = totalIncome - totalExpenses;
        var currentGold = Player.gold || 0;
        var projected30 = Math.round(currentGold + netIncome);

        // Recent transactions (last 20)
        var recentTx = '';
        var txList = ledger.slice(-20).reverse();
        for (var t = 0; t < txList.length; t++) {
            var tx = txList[t];
            var txColor = tx.amount >= 0 ? '#5ac85a' : '#e74c3c';
            var txSign = tx.amount >= 0 ? '+' : '';
            var txCatLabel = categoryInfo[tx.category] || ('❓ ' + (tx.category || 'other'));
            recentTx += '<div style="display:flex;justify-content:space-between;padding:2px 0;font-size:0.78rem;border-bottom:1px solid #222;">'
                + '<span style="color:#999;">Day ' + tx.day + '</span>'
                + '<span style="color:#ccc;flex:1;margin:0 8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + (tx.desc || txCatLabel) + '</span>'
                + '<span style="color:' + txColor + ';font-weight:bold;white-space:nowrap;">' + txSign + fmtGold(tx.amount) + '</span>'
                + '</div>';
        }

        var reportStyle = '<style>'
            + '.fin-report { font-size: 0.85rem; }'
            + '.fin-report h3 { color: #FFD700; margin: 14px 0 6px; border-bottom: 1px solid #333; padding-bottom: 4px; font-size: 0.95rem; }'
            + '.fin-report .detail-row { display: flex; justify-content: space-between; padding: 3px 0; }'
            + '.fin-report .label { color: #ccc; }'
            + '.fin-report .value { font-weight: bold; }'
            + '.fin-report .summary-box { background: #111122; border: 1px solid #333; border-radius: 6px; padding: 10px; margin-top: 12px; }'
            + '.fin-report .summary-row { display: flex; justify-content: space-between; padding: 4px 0; font-size: 0.9rem; }'
            + '.fin-report .summary-row.big { font-size: 1rem; border-top: 1px solid #444; padding-top: 8px; margin-top: 4px; }'
            + '</style>';

        var reportHtml = reportStyle + '<div class="fin-report" style="background:#1a1a2e;padding:12px;border-radius:8px;">'
            + '<h3>💰 Income (Last 30 Days)</h3>'
            + incomeRows
            + '<div class="detail-row" style="border-top:1px solid #333;margin-top:6px;padding-top:6px;">'
            + '<span class="label" style="color:#FFD700;font-weight:bold;">Total Income</span>'
            + '<span class="value" style="color:#5ac85a;font-weight:bold;">' + fmtGold(totalIncome) + '</span></div>'

            + '<h3>📉 Expenses (Last 30 Days)</h3>'
            + expenseRows
            + '<div class="detail-row" style="border-top:1px solid #333;margin-top:6px;padding-top:6px;">'
            + '<span class="label" style="color:#FFD700;font-weight:bold;">Total Expenses</span>'
            + '<span class="value" style="color:#e74c3c;font-weight:bold;">-' + fmtGold(totalExpenses) + '</span></div>'

            + '<div class="summary-box">'
            + '<div class="summary-row"><span style="color:#ccc;">Total Income (30d)</span><span style="color:#5ac85a;font-weight:bold;">' + fmtGold(totalIncome) + '</span></div>'
            + '<div class="summary-row"><span style="color:#ccc;">Total Expenses (30d)</span><span style="color:#e74c3c;font-weight:bold;">-' + fmtGold(totalExpenses) + '</span></div>'
            + '<div class="summary-row"><span style="color:#ccc;">Net Income (30d)</span><span style="' + posNeg(netIncome) + ';font-weight:bold;">' + (netIncome >= 0 ? '+' : '') + fmtGold(netIncome) + '</span></div>'
            + '<div class="summary-row"><span style="color:#ccc;">Current Gold</span><span style="color:#FFD700;font-weight:bold;">🪙 ' + fmtGold(currentGold) + '</span></div>'
            + '<div class="summary-row big"><span style="color:#FFD700;">Projected Gold (30 days)</span><span style="' + posNeg(projected30) + ';font-weight:bold;">🪙 ' + fmtGold(projected30) + '</span></div>'
            + '</div>';

        // Health status indicator (only if injured or sick)
        var _injuries = Player.injuries || [];
        var _illnesses = Player.illnesses || [];
        if (_injuries.length > 0 || _illnesses.length > 0) {
            reportHtml += '<div style="background:rgba(200,50,50,0.08);border:1px solid rgba(200,50,50,0.3);border-radius:6px;padding:8px 10px;margin-top:12px;">';
            reportHtml += '<div style="font-size:0.85rem;color:#e74c3c;font-weight:bold;margin-bottom:4px;">⚠️ Health Alert</div>';
            for (var _hi = 0; _hi < _injuries.length; _hi++) {
                var _hinj = _injuries[_hi];
                var _hinjSevColor = _hinj.severity === 'severe' ? '#e74c3c' : _hinj.severity === 'moderate' ? '#e67e22' : '#2ecc71';
                reportHtml += '<div style="display:flex;justify-content:space-between;padding:2px 0;font-size:0.8rem;">'
                    + '<span style="color:#ccc;">🩹 ' + (_hinj.name || 'Injury') + '</span>'
                    + '<span style="color:' + _hinjSevColor + ';font-weight:bold;">' + (_hinj.severity || 'mild') + '</span></div>';
            }
            for (var _si = 0; _si < _illnesses.length; _si++) {
                var _sill = _illnesses[_si];
                var _sillSevColor = _sill.severity === 'severe' ? '#e74c3c' : _sill.severity === 'moderate' ? '#e67e22' : '#2ecc71';
                var _sillName = _sill.name || (_sill.type ? _sill.type.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); }) : 'Unknown Illness');
                reportHtml += '<div style="display:flex;justify-content:space-between;padding:2px 0;font-size:0.8rem;">'
                    + '<span style="color:#ccc;">🤒 ' + _sillName + '</span>'
                    + '<span style="color:' + _sillSevColor + ';font-weight:bold;">' + (_sill.severity || 'mild') + '</span></div>';
            }
            reportHtml += '</div>';
        }

        reportHtml += '<details style="margin-top:14px;"><summary style="cursor:pointer;color:#FFD700;font-size:0.9rem;padding:4px 0;">📋 Recent Transactions (' + txList.length + ')</summary>'
            + '<div style="max-height:250px;overflow-y:auto;margin-top:6px;padding:4px;">' + recentTx + '</div></details>';

        // ── Debt Section ──
        var _debts = Player.state.debts || [];
        if (_debts.length > 0) {
            var _totalDebt = 0;
            for (var _ddi = 0; _ddi < _debts.length; _ddi++) _totalDebt += _debts[_ddi].amount;
            reportHtml += '<div style="background:rgba(200,50,50,0.12);border:1px solid rgba(200,50,50,0.4);border-radius:6px;padding:10px;margin-top:12px;">';
            reportHtml += '<div style="font-size:0.9rem;color:#e74c3c;font-weight:bold;margin-bottom:6px;">💸 Outstanding Debts — ' + formatGold(Math.floor(_totalDebt)) + ' total</div>';
            reportHtml += '<div style="font-size:0.7rem;color:#cc8844;margin-bottom:8px;">Interest: 10% every 90 days. Unpaid debts block promotions, building, and hiring.</div>';
            for (var _ddj = 0; _ddj < _debts.length; _ddj++) {
                var _dd = _debts[_ddj];
                var _ddAge = Engine.getDay() - (_dd.dayIncurred || 0);
                reportHtml += '<div style="background:rgba(0,0,0,0.3);border:1px solid #333;border-radius:4px;padding:6px 8px;margin-bottom:6px;">';
                reportHtml += '<div style="display:flex;justify-content:space-between;align-items:center;">';
                reportHtml += '<span style="color:#ccc;font-size:0.82rem;">' + escapeHtml(_dd.creditorName || 'Unknown') + '</span>';
                reportHtml += '<span style="color:#e74c3c;font-weight:bold;font-size:0.9rem;">' + formatGold(Math.floor(_dd.amount)) + '</span>';
                reportHtml += '</div>';
                reportHtml += '<div style="font-size:0.7rem;color:#888;margin-top:2px;">' + escapeHtml(_dd.reason || 'Unpaid fine') + ' · ' + _ddAge + ' days old</div>';
                // Pay buttons
                var _ddPayAmts = [10, 50, 100];
                reportHtml += '<div style="margin-top:4px;display:flex;gap:4px;flex-wrap:wrap;">';
                for (var _pk = 0; _pk < _ddPayAmts.length; _pk++) {
                    var _pAmt = Math.min(_ddPayAmts[_pk], Math.ceil(_dd.amount));
                    reportHtml += '<button class="btn-medieval" data-action="_payDebt" data-id="' + _dd.id + '" data-val="' + _pAmt + '" style="font-size:0.7rem;padding:2px 8px;">Pay ' + _pAmt + 'g</button>';
                }
                // Pay All button
                reportHtml += '<button class="btn-medieval" data-action="_payDebt" data-id="' + _dd.id + '" data-val="' + Math.ceil(_dd.amount) + '" style="font-size:0.7rem;padding:2px 8px;background:rgba(40,100,40,0.3);border-color:#4a4;">Pay All (' + formatGold(Math.ceil(_dd.amount)) + ')</button>';
                reportHtml += '</div></div>';
            }
            reportHtml += '<div style="text-align:center;margin-top:8px;">';
            reportHtml += '<button class="btn-medieval" data-action="_declareBankruptcy" style="font-size:0.8rem;padding:4px 16px;background:rgba(139,0,0,0.3);border-color:#8b0000;color:#e74c3c;">💥 Declare Bankruptcy</button>';
            reportHtml += '<div style="font-size:0.65rem;color:#888;margin-top:3px;">Erases all debts but seizes all gold, inventory & buildings. Rep damage.</div>';
            reportHtml += '</div></div>';
        }

        reportHtml += '<div style="text-align:center;margin-top:10px;font-size:0.7rem;color:#666;">'
            + 'Based on tracked transactions · Last 30 of ' + currentDay + ' days'
            + '</div></div>';

        openModal('📊 Financial Report', reportHtml);
    }

    // ═══════════════════════════════════════════════════════════
    //  JOURNAL / STORYBOOK UI
