    function showEventDetail(eventIndex) {
        var events = openEventLog._cachedEvents;
        if (!events || eventIndex == null || eventIndex >= events.length) return;
        var event = events[eventIndex];
        if (!event) return;

        var html = '<div class="event-detail-panel">';

        // Main message
        html += '<div class="event-detail-message" style="font-size:1.1rem;margin-bottom:12px;color:var(--gold-bright);">' + (event.message || event.description || 'Event') + '</div>';
        html += '<div class="event-detail-day" style="color:var(--text-dim);margin-bottom:12px;">Day ' + (event.day || '?') + '</div>';

        if (event.details) {
            // Error alert detail
            if (event.details.type === 'error_alert') {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:#c44e52;font-weight:bold;margin-bottom:4px;">🐛 Error Source: ' + (event.details.source || 'Unknown') + '</div>';
                html += '<pre style="color:var(--parchment);background:rgba(0,0,0,0.3);padding:8px;border-radius:4px;white-space:pre-wrap;word-break:break-all;font-size:0.8rem;max-height:300px;overflow-y:auto;">' + (event.details.fullError || 'No details') + '</pre>';
                html += '</div>';
            }

            // Royal Consultation — open consultation dialog
            if (event.details.type === 'royal_consultation' && event.details.kingdomId && event.details.decisionId) {
                html += '<div style="margin:12px 0;"><button class="btn-medieval" style="background:rgba(255,215,0,0.15);border-color:rgba(255,215,0,0.4);font-size:1rem;" data-action="closeModalAndOpenKingConsultationDialog" data-id="' + event.details.kingdomId + '" data-val="' + event.details.decisionId + '">👑 Respond to King\'s Proposal</button></div>';
            }

            // Cause
            if (event.details.cause) {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:var(--gold);font-weight:bold;margin-bottom:4px;">\uD83D\uDCD6 Why This Happened</div>';
                html += '<div style="color:var(--parchment);">' + event.details.cause + '</div>';
                html += '</div>';
            }

            // Effects
            if (event.details.effects && event.details.effects.length > 0) {
                html += '<div style="margin-bottom:10px;">';
                html += '<div style="color:var(--gold);font-weight:bold;margin-bottom:4px;">\u26A1 Effects</div>';
                html += '<ul style="margin:0;padding-left:20px;">';
                for (var ei = 0; ei < event.details.effects.length; ei++) {
                    html += '<li style="color:var(--parchment);margin-bottom:4px;">' + event.details.effects[ei] + '</li>';
                }
                html += '</ul></div>';
            }
        } else {
            html += '<div style="color:var(--text-dim);font-style:italic;">No additional details available for this event.</div>';
        }

        // ── Notification Filter Info & Mute Button ──
        var evtCategory = event.category || 'local_town';
        var evtMsg = event.message || event.description || '';
        var filterInfo = null;
        try { if (typeof Player !== 'undefined' && Player.getEventFilterInfo) filterInfo = Player.getEventFilterInfo(evtCategory, evtMsg); } catch(e) {}

        if (filterInfo) {
            var catLabel = evtCategory;
            var subLabel = null;
            var muteKey = evtCategory; // default: mute entire category
            var muteLabel = catLabel;

            // Look up human-readable labels from filterDefs
            var _fdLookup = _getFilterDefsLookup();
            if (_fdLookup[evtCategory]) catLabel = _fdLookup[evtCategory].label;
            if (filterInfo.subKey && _fdLookup[filterInfo.subKey]) {
                subLabel = _fdLookup[filterInfo.subKey].label;
                muteKey = filterInfo.subKey;
                muteLabel = subLabel;
            } else if (filterInfo.subKey) {
                // subKey exists but no label found — use the raw key as label
                var _parts = filterInfo.subKey.split('.');
                subLabel = _parts[_parts.length - 1].replace(/_/g, ' ');
                subLabel = subLabel.charAt(0).toUpperCase() + subLabel.slice(1);
                muteKey = filterInfo.subKey;
                muteLabel = subLabel;
            }

            html += '<div style="margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,215,0,0.15);">';
            html += '<div style="color:var(--text-dim);font-size:0.85rem;margin-bottom:6px;">📂 ' + catLabel + (subLabel ? ' › ' + subLabel : '') + '</div>';

            // Check current filter state
            var filters = {};
            try { if (typeof Player !== 'undefined' && Player.getNotificationFilters) filters = Player.getNotificationFilters(); } catch(e) {}
            var isCurrentlyOff = filters[muteKey] === false;

            if (isCurrentlyOff) {
                html += '<button class="btn-action" style="font-size:0.85rem;padding:4px 12px;background:rgba(50,180,50,0.2);border-color:rgba(50,180,50,0.5);" data-action="setNotifFilterAndShowEventDetail" data-key="' + muteKey + '" data-val="true" data-id="' + eventIndex + '">🔔 Unmute ' + muteLabel + '</button>';
            } else {
                html += '<button class="btn-action" style="font-size:0.85rem;padding:4px 12px;background:rgba(180,50,50,0.2);border-color:rgba(180,50,50,0.5);" data-action="setNotifFilterAndShowEventDetail" data-key="' + muteKey + '" data-val="false" data-id="' + eventIndex + '">🔇 Mute ' + muteLabel + '</button>';
            }
            html += '</div>';
        }

        // Universal location button — check all possible townId sources
        var locTownId = (event.details && event.details.townId) || event.townId || null;
        // Try to infer town from message if no explicit townId
        if (!locTownId) {
            try {
                var towns = Engine.getTowns();
                if (towns) {
                    var msg = (event.message || event.description || '').toLowerCase();
                    for (var _ti = 0; _ti < towns.length; _ti++) {
                        if (towns[_ti].name && msg.indexOf(towns[_ti].name.toLowerCase()) !== -1) {
                            locTownId = towns[_ti].id;
                            break;
                        }
                    }
                }
            } catch (e) { /* ignore */ }
        }
        if (locTownId) {
            html += '<button class="btn-action" style="margin-top:8px;" data-action="clickTown" data-id="' + locTownId + '">🗺️ View Location</button>';
        }

        html += '</div>';

        openModal('\uD83D\uDCCB Event Details', html, '<button class="btn-action" data-action="closeModal">Close</button>');
    }

    // ═══════════════════════════════════════════════════════════
    //  TOASTS / NOTIFICATIONS
    // ═══════════════════════════════════════════════════════════

    function toast(message, type, category, _skipEventLog) {
        type = type || 'info';
        category = category || 'my_actions';

        // Log to engine event log unless called from processEvents (prevents circular toast→log→process→toast loop)
        if (!_skipEventLog) {
            try {
                if (typeof Engine !== 'undefined' && Engine.getEvents && Engine.logEvent) {
                    var events = Engine.getEvents();
                    var day = Engine.getDay ? Engine.getDay() : 0;
                    var alreadyLogged = false;
                    // Check last 5 events for a duplicate within same day
                    for (var _di = events.length - 1; _di >= Math.max(0, events.length - 5); _di--) {
                        if (events[_di].day === day && events[_di].message === message) {
                            alreadyLogged = true;
                            break;
                        }
                    }
                    if (!alreadyLogged) {
                        Engine.logEvent(message, null, category);
                    }
                }
            } catch(e) { /* ignore logging errors */ }
        }

        // Check notification filter for popup suppression (toasts can be suppressed but log entry persists)
        if (typeof Player !== 'undefined' && Player.shouldShowNotification) {
            if (!Player.shouldShowNotification(category, null, message)) return;
        }

        // Master toast mute — suppress all popups except critical (death, jail, bankruptcy)
        if (_toastsMuted && category !== 'critical') return;

        // Regency fast-forward — suppress all toasts during time skip
        if (UI._regencyToastsSuppressed) return;

        const icons = { info: 'ℹ️', warning: '⚠️', danger: '🔴', success: '✅', achievement: '🏆' };
        const id = 'toast_' + (toastId++);

        // Store notification with index for detail lookup
        var notifIndex = notifications.length;
        notifications.push({ id, message, type, time: Date.now(), category: category });

        const toastEl = document.createElement('div');
        toastEl.className = `toast toast-${type}`;
        toastEl.id = id;
        toastEl.style.cursor = 'pointer';
        toastEl.innerHTML = `<span class="toast-icon">${icons[type] || ''}</span> ${message}`;
        toastEl.addEventListener('click', function() {
            dismissToast(id);
            // Open event log to show the most recent matching event
            openEventLog();
        });

        if (!el.toastContainer) return id;
        el.toastContainer.appendChild(toastEl);
        updateNotifCount();

        // Auto-dismiss after 5 seconds
        setTimeout(() => dismissToast(id), 5000);
    }

    function dismissToast(id) {
        const toastEl = document.getElementById(id);
        if (!toastEl) return;
        toastEl.classList.add('toast-out');
        setTimeout(() => {
            if (toastEl.parentNode) toastEl.parentNode.removeChild(toastEl);
        }, 300);
    }

    function updateNotifCount() {
        // Show count of unread events since last time log was opened
        // v9p33river306: was only counting Engine events — toast-only alerts
        // (notifications array, stored locally by toast()) never incremented
        // the bell. Combine both sources.
        var totalEvents = 0;
        try {
            var evts = Engine.getEvents();
            totalEvents = evts ? evts.length : 0;
        } catch (e) { totalEvents = 0; }
        var localUnread = 0;
        if (Array.isArray(notifications)) {
            // Count toasts newer than the engine-event cutoff
            for (var _ni = 0; _ni < notifications.length; _ni++) {
                if (!notifications[_ni]._seen) localUnread++;
            }
        }
        var unread = Math.max(0, totalEvents - _lastSeenEventCount) + localUnread;
        if (el.notifCount) {
            if (unread > 0) {
                el.notifCount.textContent = unread > 99 ? '99+' : unread;
                el.notifCount.classList.remove('hidden');
            } else {
                el.notifCount.classList.add('hidden');
            }
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  TOOLTIP
    // ═══════════════════════════════════════════════════════════

    function showTooltip(x, y, text) {
        if (!el.tooltip) return;
        el.tooltip.textContent = text;
        el.tooltip.classList.remove('hidden');
        // Position near cursor, keep on screen
        const ttw = el.tooltip.offsetWidth;
        const tth = el.tooltip.offsetHeight;
        let tx = x + 12;
        let ty = y + 12;
        if (tx + ttw > window.innerWidth - 8) tx = x - ttw - 8;
        if (ty + tth > window.innerHeight - 8) ty = y - tth - 8;
        if (tx < 4) tx = 4;
        if (ty < 4) ty = 4;
        el.tooltip.style.left = tx + 'px';
        el.tooltip.style.top = ty + 'px';
    }

    function hideTooltip() {
        if (el.tooltip) el.tooltip.classList.add('hidden');
    }

    // ═══════════════════════════════════════════════════════════
    //  CONTEXT MENU
    // ═══════════════════════════════════════════════════════════

    function showContextMenu(x, y, items) {
        if (!el.contextMenu) return;
        const container = el.contextMenu.querySelector('.context-menu-items');
        if (!container) return;
        let html = '';
        for (const item of items) {
            if (item.separator) {
                html += '<div class="ctx-separator"></div>';
            } else {
                html += `<div class="ctx-item ${item.disabled ? 'disabled' : ''}" data-action="ctxExec" data-cmd="${item.disabled ? '' : item.action}">
                    ${item.icon || ''} ${item.label}
                </div>`;
            }
        }
        container.innerHTML = html;
        el.contextMenu.classList.remove('hidden');

        // Position
        let cx = x;
        let cy = y;
        if (cx + 180 > window.innerWidth) cx = x - 180;
        if (cy + 200 > window.innerHeight) cy = y - 200;
        el.contextMenu.style.left = cx + 'px';
        el.contextMenu.style.top = cy + 'px';
    }

    function hideContextMenu() {
        if (el.contextMenu) el.contextMenu.classList.add('hidden');
    }

    // ═══════════════════════════════════════════════════════════
    //  WAR ALLEGIANCE POPUP
    // ═══════════════════════════════════════════════════════════

    function showWarAllegiancePopup(warEvent) {
        if (!warEvent) return;
        const nameA = warEvent.nameA || 'Kingdom A';
        const nameB = warEvent.nameB || 'Kingdom B';
        const strengthA = warEvent.strengthA || 0;
        const strengthB = warEvent.strengthB || 0;
        const warId = warEvent.warId;

        // Get military breakdown
        let breakdownA = { infantry: 0, archers: 0, cavalry: 0 };
        let breakdownB = { infantry: 0, archers: 0, cavalry: 0 };
        try {
            if (Engine.getMilitaryBreakdown) {
                breakdownA = Engine.getMilitaryBreakdown(warEvent.kingdomA) || breakdownA;
                breakdownB = Engine.getMilitaryBreakdown(warEvent.kingdomB) || breakdownB;
            }
        } catch (e) { /* no-op */ }

        // Build strength bars
        const maxStr = Math.max(strengthA, strengthB, 1);
        const barA = Math.round((strengthA / maxStr) * 10);
        const barB = Math.round((strengthB / maxStr) * 10);
        const barStrA = '█'.repeat(barA) + '░'.repeat(10 - barA);
        const barStrB = '█'.repeat(barB) + '░'.repeat(10 - barB);

        // Determine player context
        let contextLine = '';
        const pCitizenA = Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(warEvent.kingdomA) : (Player.citizenshipKingdomId === warEvent.kingdomA);
        const pCitizenB = Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(warEvent.kingdomB) : (Player.citizenshipKingdomId === warEvent.kingdomB);
        if (pCitizenA || pCitizenB) {
            const citizenName = pCitizenA ? nameA : nameB;
            contextLine = `As a citizen of <strong>${citizenName}</strong> with military trade interests, you must decide:`;
        } else {
            contextLine = 'As a merchant with military trade interests, you must decide:';
        }

        const bodyHtml = `
            <div style="text-align:center;padding:10px;">
                <h2 style="color:#c44e52;margin:0 0 10px 0;">⚔️ WAR DECLARED! ⚔️</h2>
                <p style="font-size:1.1em;margin-bottom:15px;"><strong>${nameA}</strong> has declared war on <strong>${nameB}</strong>!</p>
                <div style="background:#1a1a2e;padding:12px;border-radius:6px;margin-bottom:15px;text-align:left;font-family:monospace;">
                    <div style="margin-bottom:8px;"><strong>Military Comparison:</strong></div>
                    <div style="margin-bottom:4px;">${nameA}: <span style="color:#4ecdc4;">${barStrA}</span> ~${strengthA} strength</div>
                    <div style="font-size:0.85em;color:#888;margin-bottom:8px;">  ${(breakdownA.infantry || breakdownA.archers || breakdownA.cavalry) ? 'Infantry: ' + (breakdownA.infantry || 0) + ' | Archers: ' + (breakdownA.archers || 0) + ' | Cavalry: ' + (breakdownA.cavalry || 0) : 'Soldiers: ' + (breakdownA.soldiers || breakdownA.total || 0) + ' | Garrison: ' + (breakdownA.garrison || 0)}</div>
                    <div style="margin-bottom:4px;">${nameB}: <span style="color:#ff6b6b;">${barStrB}</span> ~${strengthB} strength</div>
                    <div style="font-size:0.85em;color:#888;">  ${(breakdownB.infantry || breakdownB.archers || breakdownB.cavalry) ? 'Infantry: ' + (breakdownB.infantry || 0) + ' | Archers: ' + (breakdownB.archers || 0) + ' | Cavalry: ' + (breakdownB.cavalry || 0) : 'Soldiers: ' + (breakdownB.soldiers || breakdownB.total || 0) + ' | Garrison: ' + (breakdownB.garrison || 0)}</div>
                </div>
                <p style="margin-bottom:15px;">${contextLine}</p>
            </div>
        `;

        const footerHtml = `
            <button class="btn" data-action="chooseWarAllegiance" data-kingdom="${warId}" data-choice="neutral" style="margin:4px;position:relative;" title="Stay Neutral&#10;&#10;✅ Trade freely with BOTH sides&#10;✅ No reputation change&#10;✅ No war-end reward or punishment&#10;&#10;⚠️ Military sales to both sides are tracked&#10;⚠️ Lopsided sales (2:1+) trigger warnings&#10;⚠️ At 3:1 ratio: extra 10% tax from disadvantaged side&#10;⚠️ At 5:1 ratio: building seizure risk&#10;⚠️ At 10:1 ratio: total asset seizure + reputation destroyed">🕊️ Stay Neutral</button>
            <button class="btn" data-action="chooseWarAllegiance" data-kingdom="${warId}" data-choice="${warEvent.kingdomA}" style="margin:4px;" title="Side with ${nameA}&#10;&#10;IMMEDIATE:&#10;✅ +5 reputation with ${nameA}&#10;❌ -5 reputation with ${nameB}&#10;❌ -5 relationship with ${nameB} king + nobles&#10;❌ Rank in ${nameB} becomes 'Enemy' (peasant privileges)&#10;❌ Cannot hire workers in military buildings in ${nameB}&#10;❌ +50% encounters, +25% danger in ${nameB} territory&#10;&#10;IF ${nameA} WINS:&#10;✅ +5 to +20 rep (scaled by military sales + status)&#10;✅ +10 king relationship, +5 all noble relationships&#10;✅ War Hero achievement&#10;✅ Guaranteed petition (no signatures needed)&#10;✅ Up to 5000g reward&#10;&#10;IF ${nameA} LOSES:&#10;❌ Up to 5000g retribution&#10;❌ -10 to -20 rep with BOTH kingdoms&#10;❌ -10 relationship with BOTH kings&#10;❌ -5 relationship with ALL nobles&#10;❌ Buildings in ${nameB} seized&#10;❌ Possible jail time&#10;&#10;⚠️ Choice is PERMANENT — cannot change sides!">⚔️ Side with ${nameA}</button>
            <button class="btn" data-action="chooseWarAllegiance" data-kingdom="${warId}" data-choice="${warEvent.kingdomB}" style="margin:4px;" title="Side with ${nameB}&#10;&#10;IMMEDIATE:&#10;✅ +5 reputation with ${nameB}&#10;❌ -5 reputation with ${nameA}&#10;❌ -5 relationship with ${nameA} king + nobles&#10;❌ Rank in ${nameA} becomes 'Enemy' (peasant privileges)&#10;❌ Cannot hire workers in military buildings in ${nameA}&#10;❌ +50% encounters, +25% danger in ${nameA} territory&#10;&#10;IF ${nameB} WINS:&#10;✅ +5 to +20 rep (scaled by military sales + status)&#10;✅ +10 king relationship, +5 all noble relationships&#10;✅ War Hero achievement&#10;✅ Guaranteed petition (no signatures needed)&#10;✅ Up to 5000g reward&#10;&#10;IF ${nameB} LOSES:&#10;❌ Up to 5000g retribution&#10;❌ -10 to -20 rep with BOTH kingdoms&#10;❌ -10 relationship with BOTH kings&#10;❌ -5 relationship with ALL nobles&#10;❌ Buildings in ${nameA} seized&#10;❌ Possible jail time&#10;&#10;⚠️ Choice is PERMANENT — cannot change sides!">⚔️ Side with ${nameB}</button>
        `;

        // Pause game during popup
        if (typeof Game !== 'undefined' && Game.setSpeed) {
            Game._preWarSpeed = Game.getSpeed ? Game.getSpeed() : 1;
            Game.setSpeed(0);
        }

        openModal('⚔️ War Declaration', bodyHtml, footerHtml);
    }

    function chooseWarAllegiance(warId, side) {
        if (typeof Player !== 'undefined' && Player.setWarAllegiance) {
            Player.setWarAllegiance(warId, side);
        }
        closeModal();
        // Restore game speed
        if (typeof Game !== 'undefined' && Game.setSpeed && Game._preWarSpeed) {
            Game.setSpeed(Game._preWarSpeed);
            Game._preWarSpeed = null;
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  BANKRUPTCY DIALOG
    // ═══════════════════════════════════════════════════════════

    function showBankruptcyDialog(debtAmount, choices, reason) {
        _bankruptcyLock = true;
        var reasonText = '';
        if (reason === 'voluntary') {
            reasonText = 'You have chosen to declare bankruptcy to discharge your debts.';
        } else if (reason === 'unpaid_debts') {
            reasonText = 'Your debts have gone unpaid for over 90 days. The kingdom has intervened.';
        } else {
            reasonText = 'You have been in debt for 7 consecutive days with no assets to seize.';
        }
        var bodyHtml = '<div style="padding:15px;text-align:center;">';
        bodyHtml += '<p style="color:#ff6b6b;font-size:18px;margin-bottom:10px;">💸 You are bankrupt!</p>';
        bodyHtml += '<p style="color:#ccc;font-size:14px;margin-bottom:5px;">' + reasonText + '</p>';
        bodyHtml += '<p style="color:#ff9;font-size:14px;margin-bottom:20px;">Outstanding debt: <strong>' + debtAmount + 'g</strong></p>';
        bodyHtml += '<p style="color:#aaa;font-size:13px;margin-bottom:15px;">The kingdom demands you choose your fate:</p>';
        bodyHtml += '</div>';

        bodyHtml += '<div style="display:flex;flex-direction:column;gap:10px;padding:0 15px 15px;">';

        for (var i = 0; i < choices.length; i++) {
            var ch = choices[i];
            var borderColor = ch.available ? (ch.id === 'indenture' ? '#c4a' : ch.id === 'military' ? '#a44' : ch.id === 'guild_loan' ? '#a80' : '#5a5') : '#444';
            var bgColor = ch.available ? (ch.id === 'indenture' ? '#3a1a2a' : ch.id === 'military' ? '#3a1a1a' : ch.id === 'guild_loan' ? '#2a1a0a' : '#1a2a1a') : '#1a1a1a';
            var opacity = ch.available ? '1' : '0.5';
            var cursor = ch.available ? 'pointer' : 'not-allowed';

            // Guild loan opens a sub-dialog instead of directly choosing
            var clickHandler = '';
            if (ch.available) {
                if (ch.id === 'guild_loan') {
                    clickHandler = 'data-action="showGuildLoanDialog"';
                } else {
                    clickHandler = 'data-action="handleBankruptcyChoice" data-id="' + ch.id + '"';
                }
            }

            bodyHtml += '<div ' + clickHandler + ' style="';
            bodyHtml += 'border:2px solid ' + borderColor + ';background:' + bgColor + ';padding:14px;border-radius:8px;';
            bodyHtml += 'cursor:' + cursor + ';opacity:' + opacity + ';transition:all 0.2s;text-align:left;"';
            if (ch.available) {
                bodyHtml += ' onmouseover="this.style.borderColor=\'#fff\';this.style.transform=\'scale(1.02)\'"';
                bodyHtml += ' onmouseout="this.style.borderColor=\'' + borderColor + '\';this.style.transform=\'scale(1)\'"';
            }
            bodyHtml += '>';

            bodyHtml += '<div style="font-size:15px;font-weight:bold;color:' + (ch.available ? '#fff' : '#666') + ';margin-bottom:6px;">' + ch.label + '</div>';
            bodyHtml += '<div style="font-size:12px;color:' + (ch.available ? '#ccc' : '#555') + ';margin-bottom:6px;">' + ch.description + '</div>';
            bodyHtml += '<div style="font-size:11px;color:' + (ch.available ? '#999' : '#444') + ';">' + ch.detail + '</div>';

            bodyHtml += '</div>';
        }

        bodyHtml += '</div>';

        // Save/Load/Main Menu buttons — always accessible during bankruptcy
        bodyHtml += '<div style="display:flex;gap:8px;justify-content:center;padding:10px 15px 15px;border-top:1px solid #333;margin-top:5px;">';
        bodyHtml += '<button data-action="_handler_14" style="padding:6px 14px;background:#2a3a2a;color:#9d9;border:1px solid #5a5;border-radius:4px;cursor:pointer;font-size:12px;">💾 Save</button>';
        bodyHtml += '<button data-action="_godLoadGame" style="padding:6px 14px;background:#2a2a3a;color:#99d;border:1px solid #55a;border-radius:4px;cursor:pointer;font-size:12px;">📂 Load</button>';
        bodyHtml += '<button data-action="backToMainMenu" style="padding:6px 14px;background:#3a2a1a;color:#da9;border:1px solid #a85;border-radius:4px;cursor:pointer;font-size:12px;">🏠 Main Menu</button>';
        bodyHtml += '</div>';

        openModal('💸 Bankruptcy', bodyHtml, '');

        // Hide close button — player MUST choose a bankruptcy option (like encounters)
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = 'none';
    }

    function showGuildLoanDialog() {
        if (typeof Player === 'undefined' || !Player.getGuildLoanOffers) return;

        var offers = Player.getGuildLoanOffers();

        var bodyHtml = '<div style="padding:15px;text-align:center;">';
        bodyHtml += '<p style="color:#ffa500;font-size:18px;margin-bottom:10px;">🏛️ Guild Loan Offers</p>';
        bodyHtml += '<p style="color:#ccc;font-size:13px;margin-bottom:15px;">Select a guild to borrow from. Terms: 10% annual interest, 2 year repayment, auto-payments every 30 days.</p>';
        bodyHtml += '</div>';

        bodyHtml += '<div style="display:flex;flex-direction:column;gap:8px;padding:0 15px 10px;max-height:400px;overflow-y:auto;">';

        for (var i = 0; i < offers.length; i++) {
            var offer = offers[i];
            var avail = offer.available;
            var borderColor = avail ? '#a80' : '#444';
            var bgColor = avail ? '#2a1a0a' : '#1a1a1a';
            var opacity = avail ? '1' : '0.5';
            var cursor = avail ? 'pointer' : 'not-allowed';

            var clickHandler = '';
            if (avail) {
                clickHandler = 'data-action="handleGuildLoanAccept" data-id="' + offer.guildId + '"';
            }

            bodyHtml += '<div ' + clickHandler + ' style="';
            bodyHtml += 'border:2px solid ' + borderColor + ';background:' + bgColor + ';padding:12px;border-radius:8px;';
            bodyHtml += 'cursor:' + cursor + ';opacity:' + opacity + ';transition:all 0.2s;text-align:left;"';
            if (avail) {
                bodyHtml += ' onmouseover="this.style.borderColor=\'#fff\';this.style.transform=\'scale(1.02)\'"';
                bodyHtml += ' onmouseout="this.style.borderColor=\'' + borderColor + '\';this.style.transform=\'scale(1)\'"';
            }
            bodyHtml += '>';

            bodyHtml += '<div style="font-size:14px;font-weight:bold;color:' + (avail ? '#fff' : '#666') + ';margin-bottom:4px;">';
            bodyHtml += (offer.guildIcon || '🏛️') + ' ' + (offer.guildName || offer.guildId);
            bodyHtml += '</div>';

            if (avail) {
                bodyHtml += '<div style="font-size:12px;color:#ccc;margin-bottom:4px;">';
                bodyHtml += 'Loan: <strong style="color:#ffd700;">' + offer.amount + 'g</strong>';
                bodyHtml += ' | Interest: ' + offer.totalInterest + 'g';
                bodyHtml += ' | Total repay: <strong>' + offer.totalRepay + 'g</strong>';
                bodyHtml += '</div>';
                bodyHtml += '<div style="font-size:11px;color:#999;">';
                bodyHtml += 'Monthly payment: ' + offer.monthlyPayment + 'g';
                bodyHtml += ' | ' + offer.numPayments + ' payments over ' + offer.termDays + ' days';
                bodyHtml += ' | Free ' + (offer.guildName || 'guild') + ' membership';
                bodyHtml += '</div>';
            } else {
                bodyHtml += '<div style="font-size:12px;color:#666;">' + (offer.reason || 'No loan available') + '</div>';
            }

            bodyHtml += '</div>';
        }

        bodyHtml += '</div>';

        var footerHtml = '<button class="btn-action" data-action="showBankruptcyDialogFromLoan" style="margin-right:8px;">← Back</button>';

        openModal('🏛️ Guild Loans', bodyHtml, footerHtml);
    }

    function showBankruptcyDialogFromLoan() {
        // Re-show the bankruptcy dialog (recalculate choices fresh)
        var debtAmount = 0;
        if (typeof Player !== 'undefined' && Player.state) {
            debtAmount = Math.abs(Player.state.gold);
        }
        var choices = [];
        if (typeof Player !== 'undefined' && Player.getBankruptcyChoices) {
            choices = Player.getBankruptcyChoices();
        }
        showBankruptcyDialog(debtAmount, choices);
    }

    function handleGuildLoanAccept(guildId) {
        if (typeof Player === 'undefined' || !Player.acceptGuildLoan) return;

        var result = Player.acceptGuildLoan(guildId);
        if (result.success) {
            _bankruptcyLock = false;
            var closeBtn = document.getElementById('btnCloseModal');
            if (closeBtn) closeBtn.style.display = '';
            closeModal();
            // Resume game
            if (typeof Game !== 'undefined' && Game.setSpeed) {
                Game.setSpeed(1);
            }
        } else {
            // Show error and stay on dialog
            if (typeof UI !== 'undefined' && UI.toast) {
                UI.toast('❌ ' + (result.message || 'Loan failed.'), 'danger');
            }
        }
    }

    function handleBankruptcyChoice(choice) {
        if (typeof Player !== 'undefined' && Player.handleBankruptcyChoice) {
            Player.handleBankruptcyChoice(choice);
        }
        // guild_loan is handled by showGuildLoanDialog, don't close/resume here
        if (choice === 'guild_loan') return;
        _bankruptcyLock = false;
        var closeBtn = document.getElementById('btnCloseModal');
        if (closeBtn) closeBtn.style.display = '';
        closeModal();
        // Resume game
        if (typeof Game !== 'undefined' && Game.setSpeed) {
            Game.setSpeed(1);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  SPY FAVOR DIALOG
    // ═══════════════════════════════════════════════════════════
    function showSpyFavorDialog(kingdomId) {
        if (typeof Player === 'undefined' || !Player.getSpyFavorChoices) return;
        var choices = Player.getSpyFavorChoices(kingdomId);
        if (!choices || choices.length === 0) return;

        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var bodyHtml = '<div style="margin-bottom:12px;font-size:14px;color:#c4a35a;">' +
            '👑 The King is so impressed by your spy work that he offers you a personal favor. Choose wisely — this is a rare opportunity!' +
            '</div>';

        for (var i = 0; i < choices.length; i++) {
            var ch = choices[i];
            bodyHtml += '<div data-action="handleSpyFavor" data-id="' + ch.id + '" style="' +
                'background:#1a1a2e;border:1px solid #444;border-radius:8px;padding:10px 14px;margin:6px 0;cursor:pointer;transition:border-color 0.2s,background 0.2s;' +
                '" onmouseenter="this.style.borderColor=\'#c4a35a\';this.style.background=\'#222244\'" onmouseleave="this.style.borderColor=\'#444\';this.style.background=\'#1a1a2e\'">' +
                '<div style="font-weight:bold;font-size:14px;color:#e0d5c0;">' + ch.label + '</div>' +
                '<div style="font-size:12px;color:#999;margin-top:4px;">' + ch.description + '</div>' +
                '<div style="font-size:11px;color:#c4a35a;margin-top:3px;">' + ch.detail + '</div>' +
                '</div>';
        }

        openModal('👑 Royal Favor', bodyHtml, '');
    }

    function handleSpyFavor(favorId) {
        if (typeof Player !== 'undefined' && Player.handleSpyFavor) {
            var result = Player.handleSpyFavor(favorId);
            if (result && result.message && typeof toast === 'function') {
                toast(result.success ? '✅ ' + result.message : '❌ ' + result.message, result.success ? 'success' : 'danger');
            }
        }
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
    }

    // ═══════════════════════════════════════════════════════════
    //  TOURNAMENT CONTINUE/FORFEIT DIALOG
    // ═══════════════════════════════════════════════════════════
    function showTournamentContinueDialog(result) {
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var bodyHtml = '<div style="text-align:center;margin-bottom:12px;">' +
            '<div style="font-size:24px;margin-bottom:8px;">🏟️ Round ' + (result.nextRound - 1) + ' Victory!</div>' +
            '<div style="color:#c4a35a;font-size:16px;margin-bottom:12px;">' + result.message.split('\n')[0] + '</div>' +
            '</div>';

        bodyHtml += '<div style="background:#1a1a2e;border:1px solid #444;border-radius:8px;padding:12px;margin:8px 0;text-align:center;">' +
            '<div style="font-size:14px;color:#e0d5c0;">⚔️ Round ' + result.nextRound + '</div>' +
            '<div style="font-size:13px;color:#999;margin-top:4px;">Prize: <span style="color:#c4a35a;">' + result.nextPrize + 'g</span> | Win chance: <span style="color:' + (result.nextWinChance >= 50 ? '#4ade80' : result.nextWinChance >= 25 ? '#fbbf24' : '#f87171') + ';">' + result.nextWinChance + '%</span></div>' +
            '</div>';

        bodyHtml += '<div style="display:flex;gap:10px;margin-top:14px;">' +
            '<button data-action="handleTournamentContinue" style="flex:1;padding:10px;background:#2d5a2d;color:#fff;border:1px solid #4ade80;border-radius:6px;cursor:pointer;font-size:14px;">⚔️ Fight Next Round</button>' +
            '<button data-action="handleTournamentForfeit" style="flex:1;padding:10px;background:#5a2d2d;color:#fff;border:1px solid #f87171;border-radius:6px;cursor:pointer;font-size:14px;">🏳️ Withdraw (Keep Winnings)</button>' +
            '</div>';

        openModal('🏟️ Tournament', bodyHtml, '');
    }

    function handleTournamentContinue() {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.continueTournament) {
            var result = Player.continueTournament();
            if (result && result.tournamentContinue) {
                setTimeout(function() { showTournamentContinueDialog(result); }, 300);
            }
        }
    }

    function handleTournamentForfeit() {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.forfeitTournament) {
            Player.forfeitTournament();
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  CUSTOMS INSPECTOR CONTRABAND DIALOG
    // ═══════════════════════════════════════════════════════════
    function showCustomsChoiceDialog(itemName, resourceId, kingdomId) {
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);
        var bodyHtml = '<div style="text-align:center;margin-bottom:12px;">' +
            '<div style="font-size:20px;margin-bottom:8px;">🔍 Contraband Found!</div>' +
            '<div style="color:#c4a35a;font-size:14px;">You discovered <strong>' + itemName + '</strong> while inspecting cargo.</div>' +
            '</div>';
        bodyHtml += '<div style="display:flex;gap:10px;margin-top:14px;">' +
            '<div data-action="handleCustomsChoice" data-choice="turn_in" style="flex:1;padding:12px;background:#1a2e1a;border:1px solid #4ade80;border-radius:8px;cursor:pointer;text-align:center;">' +
            '<div style="font-size:16px;">⚖️ Turn In</div>' +
            '<div style="font-size:12px;color:#999;margin-top:4px;">+10g bounty, +2 kingdom rep</div>' +
            '</div>' +
            '<div data-action="handleCustomsChoice" data-choice="keep" style="flex:1;padding:12px;background:#2e1a1a;border:1px solid #f87171;border-radius:8px;cursor:pointer;text-align:center;">' +
            '<div style="font-size:16px;">🤫 Pocket It</div>' +
            '<div style="font-size:12px;color:#999;margin-top:4px;">Keep 1x ' + itemName + ', +5 notoriety</div>' +
            '</div>' +
            '</div>';
        openModal('🔍 Customs Inspection', bodyHtml, '');
    }

    function handleCustomsChoice(choice) {
        closeModal();
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(1);
        if (typeof Player !== 'undefined' && Player.handleCustomsChoice) {
            Player.handleCustomsChoice(choice);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  AUTO-TRAVEL JOB STATUS (shown in work dialog)
    // ═══════════════════════════════════════════════════════════
    function getAutoTravelStatusHtml() {
        if (typeof Player === 'undefined' || !Player.getAutoTravelStatus) return '';
        var status = Player.getAutoTravelStatus();
        if (!status) return '';

        var html = '<div style="border:2px solid #c4a35a;padding:10px;margin-bottom:12px;border-radius:6px;background:rgba(196,163,90,0.08);">';
        html += '<h3 style="margin:0 0 6px 0;">🗺️ ' + status.name + ' — Active Mission</h3>';
        html += '<div class="detail-row"><span class="label">Status</span><span class="value">';
        if (status.status === 'traveling') html += '🚶 Traveling to ' + status.currentDestination;
        else if (status.status === 'working') html += '⚒️ Working at ' + status.currentDestination;
        else if (status.status === 'advancing') html += '📋 Preparing next leg...';
        html += '</span></div>';
        html += '<div class="detail-row"><span class="label">Progress</span><span class="value">' + status.completedLegs + ' / ' + status.totalLegs + ' stops</span></div>';
        html += '<div class="detail-row"><span class="label">Current Task</span><span class="value" style="font-size:0.75rem;">' + status.currentDescription + '</span></div>';
        html += '<div class="detail-row"><span class="label">Earned So Far</span><span class="value">🪙 ' + formatGold(status.totalPaid || 0) + 'g</span></div>';
        html += '<div class="detail-row"><span class="label">Days Elapsed</span><span class="value">' + status.daysElapsed + '</span></div>';

        // Show letters for messenger
        if (status.letters && status.letters.length > 0) {
            html += '<div style="margin-top:6px;font-size:0.75rem;color:#999;">';
            for (var i = 0; i < status.letters.length; i++) {
                var l = status.letters[i];
                html += (l.delivered ? '✅' : '📮') + ' ' + l.recipientName + ' in ' + l.townName + (l.delivered ? ' (delivered)' : '') + '<br>';
            }
            html += '</div>';
        }

        html += '<button class="btn-medieval" data-action="quitAutoTravelJob" style="margin-top:8px;font-size:0.8rem;padding:6px 16px;background:rgba(200,60,50,0.3);border-color:rgba(200,60,50,0.55);">🛑 Quit Mission</button>';
        html += '</div>';
        html += '<p class="text-dim">You cannot take other jobs while on an auto-travel mission. The mission progresses automatically.</p>';
        return html;
    }

    function quitAutoTravelJob() {
        if (typeof Player !== 'undefined' && Player.quitAutoTravelJob) {
            var result = Player.quitAutoTravelJob();
            if (result && result.message) {
                toast(result.message, result.success ? 'info' : 'warning');
            }
        }
        closeModal();
    }

    // ═══════════════════════════════════════════════════════════
    //  AUTO-WORK STATUS (shown in work dialog & overlay)
    // ═══════════════════════════════════════════════════════════
    function _getAutoWorkStatusHtml() {
        if (typeof Player === 'undefined' || !Player.getAutoWorkStatus) return '';
        var s = Player.getAutoWorkStatus();
        if (!s) return '';
        var daysActive = s.daysWorked || 0;
        var energyPct = Math.round((s.energy / (s.maxEnergy || 100)) * 100);
        var energyColor = energyPct > 50 ? '#2ecc71' : (energyPct > 25 ? '#e67e22' : '#c0392b');

        var html = '<div style="border:2px solid #4ade80;padding:10px;margin-bottom:12px;border-radius:6px;background:rgba(74,222,128,0.08);">';
        html += '<h3 style="margin:0 0 6px 0;">🔄 Auto-Work — ' + escapeHtml(s.jobName) + '</h3>';
        html += '<div class="detail-row"><span class="label">Status</span><span class="value">' + escapeHtml(s.currentAction) + '</span></div>';
        html += '<div class="detail-row"><span class="label">Days Worked</span><span class="value">' + daysActive + '</span></div>';
        html += '<div class="detail-row"><span class="label">Total Earned</span><span class="value">🪙 ' + formatGold(s.totalEarned || 0) + 'g</span></div>';
        if (s.weeklyPay) {
            html += '<div class="detail-row"><span class="label">Weekly Pay</span><span class="value">🪙 ' + s.weeklyPay + 'g/week</span></div>';
        }
        html += '<div class="detail-row"><span class="label">Energy</span><span class="value" style="color:' + energyColor + ';">' + Math.round(s.energy) + '/' + Math.round(s.maxEnergy) + ' (' + energyPct + '%)</span></div>';
        html += '<div class="detail-row"><span class="label">Hunger</span><span class="value">' + Math.round(s.hunger) + '/100</span></div>';
        html += '<div class="detail-row"><span class="label">Thirst</span><span class="value">' + Math.round(s.thirst) + '/100</span></div>';
        if (s.isTravel) {
            html += '<div style="margin-top:4px;font-size:0.75rem;color:#60a5fa;">🗺️ Travel mode (' + (s.paidTravel ? 'paid routes' : 'unpaid routes') + ')</div>';
        }
        html += '<button class="btn-medieval" data-action="stopAutoWorkUI" style="margin-top:8px;font-size:0.8rem;padding:6px 16px;background:rgba(200,60,50,0.3);border-color:rgba(200,60,50,0.55);">⏹️ Stop Working</button>';
        html += '</div>';
        html += '<p class="text-dim">Your character will automatically work, rest, eat, and drink. You can stop at any time.</p>';
        return html;
    }

    function startAutoWorkUI(jobIndex) {
        if (typeof Player === 'undefined' || !Player.startAutoWork) return;
        var idx = parseInt(jobIndex, 10);
        if (isNaN(idx)) return;
        var result = Player.startAutoWork(idx, {});
        if (result && result.success) {
            toast('🔄 ' + result.message, 'success');
        } else {
            toast((result && result.message) || 'Cannot start auto-work.', 'warning');
        }
        closeModal();
    }

    function stopAutoWorkUI() {
        if (typeof Player !== 'undefined' && Player.stopAutoWork) {
            var result = Player.stopAutoWork();
            if (result && result.message) {
                toast(result.message, result.success ? 'info' : 'warning');
            }
        }
        closeModal();
    }

    // ═══════════════════════════════════════════════════════════
    //  WIN / LOSE SCREEN
    // ═══════════════════════════════════════════════════════════

    function showWinScreen(message) {
        const endTitle = document.getElementById('endTitle');
        const endMessage = document.getElementById('endMessage');
        if (endTitle) { endTitle.textContent = '🏆 Victory!'; endTitle.style.color = '#c4a35a'; }
        if (endMessage) endMessage.textContent = message || 'You have built a legendary trade empire!';
        showEndStats();
        el.endScreen.classList.remove('hidden');
        el.endScreen.style.display = 'flex';
    }

    // ── REGENCY SCREEN ──

    function showRegencyScreen() {
        if (!Player.regencyMode || !Player.regencyData) return;
        // Hide health alert banner — heir is not sick
        var _ha = document.getElementById('healthAlert');
        if (_ha) _ha.classList.remove('visible');
        const rd = Player.regencyData;
        const threshold = (typeof REGENCY_THRESHOLDS !== 'undefined') ?
            REGENCY_THRESHOLDS.find(t => rd.regencyScore >= t.min && rd.regencyScore <= t.max) : null;

        let updatesHtml = '';
        const recentUpdates = (rd.monthlyUpdates || []).slice(-6);
        for (const upd of recentUpdates) {
            updatesHtml += `<div style="font-size:0.75rem;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);">${upd.message}</div>`;
        }
        if (!updatesHtml) updatesHtml = '<div class="text-dim">No updates yet.</div>';

        const yearsToGo = Math.max(0, CONFIG.COMING_OF_AGE - rd.heirAge);
        const heirSexIcon = rd.heirSex === 'F' ? '♀' : '♂';

        const spouseStatus = rd.spouseAlive ? '💚 Alive' : '⚰️ Deceased';
        const thresholdLabel = rd.thresholdLabel || 'Unknown';

        let revealedTraitsHtml = '';
        if (rd.revealedAtDeath) {
            const rTraits = rd.revealedAtDeath.traits || {};
            const rQuirks = rd.revealedAtDeath.quirks || [];
            if (Object.keys(rTraits).length > 0 || rQuirks.length > 0) {
                revealedTraitsHtml += '<div style="font-size:0.75rem;margin-top:6px;">';
                for (const [t, v] of Object.entries(rTraits)) {
                    const label = t.charAt(0).toUpperCase() + t.slice(1);
                    revealedTraitsHtml += `<span style="margin-right:8px;">${label}: ${typeof v === 'number' ? v : v}</span>`;
                }
                if (rQuirks.length > 0 && typeof SPOUSE_QUIRKS !== 'undefined') {
                    for (const qId of rQuirks) {
                        const qDef = SPOUSE_QUIRKS.find(q => q.id === qId);
                        if (qDef) revealedTraitsHtml += `<span style="margin-right:8px;">${qDef.icon} ${qDef.name}</span>`;
                    }
                }
                revealedTraitsHtml += '</div>';
            }
        }

        const html = `<div style="text-align:center;padding:12px;">
            <div style="font-size:1.4rem;font-weight:bold;margin-bottom:12px;">⚰️ REGENCY PERIOD</div>
            <div class="text-dim" style="margin-bottom:12px;">Your spouse manages the estate while your heir grows up.</div>

            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left;">
                <div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">
                    <div style="font-weight:bold;margin-bottom:4px;">👩 Regent: ${rd.spouseName}</div>
                    <div style="font-size:0.8rem;">Status: ${spouseStatus}</div>
                    <div style="font-size:0.8rem;">Outcome: <span style="color:var(--gold);">${thresholdLabel}</span></div>
                    <div style="font-size:0.8rem;">Score: ${rd.regencyScore}/100</div>
                    ${revealedTraitsHtml}
                </div>
                <div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">
                    <div style="font-weight:bold;margin-bottom:4px;">${heirSexIcon} Heir: ${rd.heirName}</div>
                    <div style="font-size:0.8rem;">Age: ${rd.heirAge} → ${CONFIG.COMING_OF_AGE} in ~${yearsToGo} years</div>
                    <div style="font-size:0.8rem;margin-top:8px;">💰 Estate: ${formatGold(rd.estateGold || 0)}</div>
                    <div style="font-size:0.8rem;">🏠 Buildings: ${rd.buildingsMaintained} maintained</div>
                    <div style="font-size:0.8rem;">🐫 Caravans: ${rd.caravansCopy ? rd.caravansCopy.length : 0}</div>
                </div>
            </div>

            <div style="border:1px solid rgba(196,163,90,0.1);border-radius:6px;padding:8px;margin-top:12px;text-align:left;">
                <div style="font-weight:bold;margin-bottom:4px;font-size:0.85rem;">📜 Recent Updates</div>
                ${updatesHtml}
            </div>

            <div style="margin-top:12px;font-size:0.8rem;color:#888;">
                Time continues to advance. Use speed controls to pass the years.
            </div>
        </div>`;

        openModal('⚰️ Regency', html);
    }

    function updateRegencyOverlay() {
        if (!Player.regencyMode || !Player.regencyData) return;
        // During fast-forward, the full-screen overlay handles display — skip the small banner
        if (UI._regencyToastsSuppressed) {
            _updateRegencyFastForward();
            return;
        }
        // Show a persistent regency bar in the HUD
        let overlay = document.getElementById('regencyOverlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'regencyOverlay';
            overlay.style.cssText = 'position:fixed;top:40px;left:50%;transform:translateX(-50%);background:rgba(30,25,20,0.95);border:1px solid var(--gold);border-radius:8px;padding:8px 16px;z-index:1000;cursor:pointer;font-size:0.8rem;text-align:center;';
            overlay.addEventListener('click', function() { showRegencyScreen(); });
            document.body.appendChild(overlay);
        }
        const rd = Player.regencyData;
        overlay.innerHTML = `⚰️ <b>Regency</b> | ${escapeHtml(rd.spouseName)} raises ${escapeHtml(rd.heirName)} (Age ${rd.heirAge}/${CONFIG.COMING_OF_AGE}) | 💰 ${formatGold(rd.estateGold || 0)} | <span style="color:var(--gold);">${escapeHtml(rd.thresholdLabel)}</span>`;
        overlay.style.display = '';
    }

    var _regencyFFStartTime = 0;
    var _regencyFFPaused = false;

    function _pauseRegencyFF() {
        _regencyFFPaused = true;
        // Temporarily clear suppression so setSpeed works
        var wasSuppressed = UI._regencyToastsSuppressed;
        UI._regencyToastsSuppressed = false;
        // Pause the game so the main thread is free for UI interaction
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);
        UI._regencyToastsSuppressed = wasSuppressed;
        // Hide the overlay so modals are visible
        var el = document.getElementById('regencyFastForward');
        if (el) el.style.display = 'none';
    }

    function _resumeRegencyFF() {
        if (!_regencyFFPaused) return;
        _regencyFFPaused = false;
        // Restore overlay
        var el = document.getElementById('regencyFastForward');
        if (el) el.style.display = 'flex';
        // Temporarily clear suppression so setSpeed works, then restore
        var wasSuppressed = UI._regencyToastsSuppressed;
        UI._regencyToastsSuppressed = false;
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(300);
        UI._regencyToastsSuppressed = wasSuppressed;
    }

    function showRegencyFastForward() {
        _regencyFFStartTime = performance.now();
        // Close any open modals
        closeModal();
        // Hide health alert banner — heir is not sick
        var _ha = document.getElementById('healthAlert');
        if (_ha) _ha.classList.remove('visible');
        // Create or show the full-screen regency overlay
        var el = document.getElementById('regencyFastForward');
        if (!el) {
            el = document.createElement('div');
            el.id = 'regencyFastForward';
            el.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:9999;background:rgba(10,8,4,0.95);display:flex;align-items:center;justify-content:center;';
            document.body.appendChild(el);
        }
        el.style.display = 'flex';
        // Hide the small regency overlay bar
        hideRegencyOverlay();
        _updateRegencyFastForward();
    }

    function _updateRegencyFastForward() {
        var el = document.getElementById('regencyFastForward');
        if (!el) return;
        if (!Player.regencyMode || !Player.regencyData) return;

        var rd = Player.regencyData;
        var yearsToGo = Math.max(0, CONFIG.COMING_OF_AGE - rd.heirAge);

        // Elapsed real time
        var elapsedMs = performance.now() - _regencyFFStartTime;
        var elapsedSec = Math.floor(elapsedMs / 1000);
        var elapsedMin = Math.floor(elapsedSec / 60);
        var elapsedSecR = elapsedSec % 60;
        var elapsedStr = elapsedMin > 0 ? (elapsedMin + 'm ' + elapsedSecR + 's') : (elapsedSecR + 's');

        // Estimate remaining time based on actual elapsed pace
        var startAge = rd._ffStartAge != null ? rd._ffStartAge : rd.heirAge;
        if (rd._ffStartAge == null) rd._ffStartAge = rd.heirAge;
        var yearsCompleted = rd.heirAge - startAge;
        var realTimeStr;
        if (yearsCompleted > 0 && elapsedSec > 0) {
            var secPerYear = elapsedSec / yearsCompleted;
            // Later years are more expensive — add 50% extra for each year of regency past 12
            var totalRegencyYears = yearsCompleted + yearsToGo;
            var normalYearsLeft = Math.max(0, Math.min(yearsToGo, 12 - yearsCompleted));
            var lateYearsLeft = Math.max(0, yearsToGo - normalYearsLeft);
            var estSecondsLeft = Math.ceil(secPerYear * (normalYearsLeft + lateYearsLeft * 1.5));
            var estMin = Math.floor(estSecondsLeft / 60);
            var estSec = estSecondsLeft % 60;
            realTimeStr = estMin > 0 ? (estMin + 'm ' + estSec + 's') : (estSec + 's');
        } else {
            realTimeStr = 'calculating...';
        }

        var heirSexIcon = rd.heirSex === 'F' ? '♀' : '♂';
        var spouseStatus = rd.spouseAlive ? '💚 Alive' : '⚰️ Deceased';

        // Recent updates (last 6)
        var updatesHtml = '';
        var recentUpdates = (rd.monthlyUpdates || []).slice(-6);
        for (var u = 0; u < recentUpdates.length; u++) {
            updatesHtml += '<div style="font-size:0.75rem;padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.05);">' + escapeHtml(recentUpdates[u].message) + '</div>';
        }
        if (!updatesHtml) updatesHtml = '<div style="color:#666;">Waiting for updates...</div>';

        // Progress bar
        var totalYears = CONFIG.COMING_OF_AGE - 1; // max years to wait (heir starts at age 1 min)
        var yearsElapsed = Math.max(0, rd.heirAge - 1);
        var pct = totalYears > 0 ? Math.min(100, Math.round((yearsElapsed / (CONFIG.COMING_OF_AGE - 1)) * 100)) : 100;

        // Quirks display
        var revealedTraitsHtml = '';
        if (rd.revealedAtDeath) {
            var rQuirks = rd.revealedAtDeath.quirks || [];
            if (rQuirks.length > 0 && typeof SPOUSE_QUIRKS !== 'undefined') {
                for (var qi = 0; qi < rQuirks.length; qi++) {
                    var qDef = null;
                    for (var qj = 0; qj < SPOUSE_QUIRKS.length; qj++) {
                        if (SPOUSE_QUIRKS[qj].id === rQuirks[qi]) { qDef = SPOUSE_QUIRKS[qj]; break; }
                    }
                    if (qDef) revealedTraitsHtml += '<span style="margin-right:8px;font-size:0.75rem;">' + qDef.icon + ' ' + escapeHtml(qDef.name) + '</span>';
                }
            }
        }

        el.innerHTML = '<div style="text-align:center;max-width:550px;width:90%;">' +
            '<div style="font-size:2rem;font-weight:bold;color:var(--gold);margin-bottom:8px;font-family:var(--font-display);">⚰️ REGENCY</div>' +
            '<div style="color:#aaa;margin-bottom:20px;font-size:0.9rem;">Time is passing while your heir grows up...</div>' +

            // Countdown
            '<div style="background:rgba(196,163,90,0.1);border:1px solid rgba(196,163,90,0.3);border-radius:8px;padding:16px;margin-bottom:16px;">' +
                '<div style="font-size:1.8rem;font-weight:bold;color:#fff;margin-bottom:4px;">' + heirSexIcon + ' ' + escapeHtml(rd.heirName) + ' — Age ' + rd.heirAge + '</div>' +
                '<div style="font-size:1.1rem;color:var(--gold);margin-bottom:10px;">⏳ ' + yearsToGo + ' years to go (~' + realTimeStr + ' real time)</div>' +
                // Progress bar
                '<div style="background:rgba(0,0,0,0.4);border-radius:4px;height:20px;overflow:hidden;margin-bottom:8px;">' +
                    '<div style="background:linear-gradient(90deg,#c4a35a,#e8d48b);height:100%;width:' + pct + '%;transition:width 0.5s;border-radius:4px;"></div>' +
                '</div>' +
                '<div style="font-size:0.75rem;color:#888;">Elapsed: ' + elapsedStr + ' | Speed: 300×</div>' +
            '</div>' +

            // Info panels
            '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;text-align:left;margin-bottom:16px;">' +
                '<div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">' +
                    '<div style="font-weight:bold;margin-bottom:4px;font-size:0.85rem;">👩 Regent: ' + escapeHtml(rd.spouseName) + '</div>' +
                    '<div style="font-size:0.8rem;">Status: ' + spouseStatus + '</div>' +
                    '<div style="font-size:0.8rem;">Outcome: <span style="color:var(--gold);">' + escapeHtml(rd.thresholdLabel) + '</span></div>' +
                    '<div style="font-size:0.8rem;">Score: ' + rd.regencyScore + '/100</div>' +
                    revealedTraitsHtml +
                '</div>' +
                '<div style="border:1px solid rgba(196,163,90,0.2);border-radius:6px;padding:10px;">' +
                    '<div style="font-weight:bold;margin-bottom:4px;font-size:0.85rem;">💰 Estate</div>' +
                    '<div style="font-size:0.8rem;">Gold: ' + formatGold(rd.estateGold || 0) + '</div>' +
                    '<div style="font-size:0.8rem;">🏠 Buildings: ' + rd.buildingsMaintained + ' maintained</div>' +
                    '<div style="font-size:0.8rem;">🐫 Caravans: ' + (rd.caravansCopy ? rd.caravansCopy.length : 0) + '</div>' +
                '</div>' +
            '</div>' +

            // Updates
            '<div style="border:1px solid rgba(196,163,90,0.1);border-radius:6px;padding:8px;text-align:left;max-height:140px;overflow-y:auto;">' +
                '<div style="font-weight:bold;margin-bottom:4px;font-size:0.85rem;">📜 Recent Updates</div>' +
                updatesHtml +
            '</div>' +

            // System buttons
            '<div style="margin-top:16px;display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">' +
                '<button id="regFF_save" style="padding:6px 16px;background:rgba(196,163,90,0.15);border:1px solid var(--gold);border-radius:4px;color:var(--gold);cursor:pointer;font-size:0.8rem;">💾 Save</button>' +
                '<button id="regFF_load" style="padding:6px 16px;background:rgba(196,163,90,0.15);border:1px solid var(--gold);border-radius:4px;color:var(--gold);cursor:pointer;font-size:0.8rem;">📂 Load</button>' +
                '<button id="regFF_settings" style="padding:6px 16px;background:rgba(196,163,90,0.15);border:1px solid var(--gold);border-radius:4px;color:var(--gold);cursor:pointer;font-size:0.8rem;">⚙️ Settings</button>' +
                '<button id="regFF_menu" style="padding:6px 16px;background:rgba(196,163,90,0.15);border:1px solid rgba(200,80,80,0.5);border-radius:4px;color:#c85050;cursor:pointer;font-size:0.8rem;">🏠 Main Menu</button>' +
            '</div>' +
        '</div>';

        // Bind buttons (re-bound each update since innerHTML is replaced)
        // Each button pauses regency FF so modals are visible above the overlay
        var btnSave = document.getElementById('regFF_save');
        var btnLoad = document.getElementById('regFF_load');
        var btnSettings = document.getElementById('regFF_settings');
        var btnMenu = document.getElementById('regFF_menu');
        if (btnSave) btnSave.addEventListener('click', function(e) {
            e.stopPropagation();
            _pauseRegencyFF();
            if (typeof Game !== 'undefined' && Game.showSaveSlotPicker) Game.showSaveSlotPicker();
        });
        if (btnLoad) btnLoad.addEventListener('click', function(e) {
            e.stopPropagation();
            _pauseRegencyFF();
            if (typeof Game !== 'undefined' && Game.showLoadSlotPicker) Game.showLoadSlotPicker();
        });
        if (btnSettings) btnSettings.addEventListener('click', function(e) {
            e.stopPropagation();
            _pauseRegencyFF();
            openSettings();
        });
        if (btnMenu) btnMenu.addEventListener('click', function(e) {
            e.stopPropagation();
            _pauseRegencyFF();
            if (confirm('Return to main menu? Unsaved progress will be lost.')) {
                UI._regencyToastsSuppressed = false;
                if (typeof Game !== 'undefined' && Game.showTitleScreen) Game.showTitleScreen();
            } else {
                _resumeRegencyFF();
            }
        });
    }

    function hideRegencyFastForward() {
        var el = document.getElementById('regencyFastForward');
        if (el) el.remove();
        // Also remove the small overlay
        hideRegencyOverlay();
    }

    function hideRegencyOverlay() {
        const overlay = document.getElementById('regencyOverlay');
        if (overlay) overlay.style.display = 'none';
    }

    function showLoseScreen(message) {
        // Pause game immediately
        if (typeof Game !== 'undefined' && Game.setSpeed) Game.setSpeed(0);

        var deathCause = '';
        if (typeof Player !== 'undefined' && Player.state) {
            deathCause = Player.state.deathCause || '';
        }

        var endTitle = document.getElementById('endTitle');
        var endMessage = document.getElementById('endMessage');
        if (endTitle) { endTitle.textContent = '💀 Defeat'; endTitle.style.color = '#c44e52'; }

        // Build cause of death message
        var loseMsg = '';
        if (message === 'No Heir' || message === 'Assassinated') {
            if (deathCause) {
                loseMsg = 'Cause of death: ' + deathCause + '.';
            } else if (message === 'Assassinated') {
                loseMsg = 'You were assassinated. Your enemies finally caught up with you.';
            } else {
                loseMsg = 'Your legacy dies with you. Without an heir, your name fades from history.';
            }
        } else if (message) {
            loseMsg = message;
        } else {
            loseMsg = 'Your merchant ventures have come to a bitter end.';
        }
        if (endMessage) endMessage.innerHTML = '<span style="font-size:1.1rem;color:#e8c080;">' + loseMsg + '</span>';

        showEndStats();
        el.endScreen.classList.remove('hidden');
        el.endScreen.style.display = 'flex';
    }

    function showEndStats() {
        var stats = (typeof Player !== 'undefined' && Player.stats) ? Player.stats : {};
        var endStats = document.getElementById('endStats');
        if (!endStats) return;

        var daysPlayed = stats.daysPlayed || (Engine.getDay ? Engine.getDay() : 0);
        var years = Math.floor(daysPlayed / (CONFIG.DAYS_PER_SEASON || 90));
        var days = daysPlayed % (CONFIG.DAYS_PER_SEASON || 90);
        var timeStr = years > 0 ? years + ' year' + (years > 1 ? 's' : '') + ', ' + days + ' day' + (days !== 1 ? 's' : '') : daysPlayed + ' day' + (daysPlayed !== 1 ? 's' : '');

        // Get highest rank achieved
        var highestRank = 0;
        var highestRankName = 'Peasant';
        if (typeof Player !== 'undefined' && Player.state) {
            var sr = Player.state.socialRank || {};
            for (var kid in sr) {
                if (sr[kid] > highestRank) highestRank = sr[kid];
            }
            if (typeof CONFIG !== 'undefined' && CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[highestRank]) {
                highestRankName = CONFIG.SOCIAL_RANKS[highestRank].name;
            }
        }

        // Achievement count
        var achCount = 0;
        var totalAch = 0;
        if (typeof Player !== 'undefined') {
            var pAch = Player.achievements || {};
            for (var ak in pAch) { if (pAch[ak] && pAch[ak].unlocked) achCount++; }
            if (typeof ACHIEVEMENTS !== 'undefined') {
                for (var _ta in ACHIEVEMENTS) totalAch++;
            }
        }

        endStats.innerHTML =
            '<span class="end-stat-label">Time Lived</span><span class="end-stat-value">' + timeStr + '</span>' +
            '<span class="end-stat-label">Gold Earned</span><span class="end-stat-value">' + formatGold(stats.totalGoldEarned || 0) + '</span>' +
            '<span class="end-stat-label">Trades Made</span><span class="end-stat-value">' + (stats.tradesCompleted || 0) + '</span>' +
            '<span class="end-stat-label">Buildings Owned</span><span class="end-stat-value">' + ((typeof Player !== 'undefined' && Player.buildings) ? Player.buildings.length : 0) + '</span>' +
            '<span class="end-stat-label">Highest Rank</span><span class="end-stat-value">' + highestRankName + '</span>' +
            '<span class="end-stat-label">Achievements</span><span class="end-stat-value">' + achCount + '/' + totalAch + '</span>' +
            '<div style="margin-top:14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;">' +
                '<button class="btn-medieval" data-action="openJournal" style="font-size:0.82rem;padding:5px 14px;">📖 Journal</button>' +
                '<button class="btn-medieval" data-action="openAchievementsDialog" style="font-size:0.82rem;padding:5px 14px;">🏆 Achievements</button>' +
                '<button class="btn-medieval" data-action="showBusinessLegacy" style="font-size:0.82rem;padding:5px 14px;background:linear-gradient(135deg,rgba(180,140,60,0.4),rgba(120,90,30,0.5));border:1px solid rgba(200,170,80,0.5);">📊 Business Legacy</button>' +
            '</div>';

        var btnEndOk = document.getElementById('btnEndOk');
        if (btnEndOk) btnEndOk.addEventListener('click', function() { el.endScreen.classList.add('hidden');
            el.endScreen.style.display = 'none';
            hideGameUI();
            el.titleScreen.classList.remove('hidden');
            el.titleScreen.style.display = 'flex'; });
    }

    // Business Legacy — comprehensive summary of the player's entire career
    function showBusinessLegacy() {
        if (typeof Player === 'undefined') return;
        var p = Player.state || {};
        var stats = Player.stats || {};
        var achStats = p.achievementStats || {};
        var day = Engine.getDay ? Engine.getDay() : 0;
        var years = Math.floor(day / (CONFIG.DAYS_PER_SEASON || 90));

        // Buildings summary
        var buildings = Player.buildings || [];
        var buildingTypes = {};
        for (var bi = 0; bi < buildings.length; bi++) {
            var bt = buildings[bi].type || 'unknown';
            buildingTypes[bt] = (buildingTypes[bt] || 0) + 1;
        }
        var buildHtml = '';
        if (buildings.length === 0) {
            buildHtml = '<div style="color:#888;">No buildings owned.</div>';
        } else {
            buildHtml = '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:340px;margin:0 auto;">';
            for (var btk in buildingTypes) {
                var bLabel = btk.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                buildHtml += '<span style="text-align:left;">' + bLabel + '</span><span style="color:#f0c040;text-align:right;">' + buildingTypes[btk] + '</span>';
            }
            buildHtml += '</div>';
        }

        // Production summary — goods produced by buildings
        var productionHtml = '';
        var totalProduced = {};
        for (var pi = 0; pi < buildings.length; pi++) {
            var bld = buildings[pi];
            if (bld.totalProduced) {
                for (var pk in bld.totalProduced) {
                    totalProduced[pk] = (totalProduced[pk] || 0) + bld.totalProduced[pk];
                }
            }
        }
        var prodEntries = [];
        for (var prk in totalProduced) { if (totalProduced[prk] > 0) prodEntries.push({ good: prk, qty: totalProduced[prk] }); }
        prodEntries.sort(function(a, b) { return b.qty - a.qty; });
        if (prodEntries.length === 0) {
            productionHtml = '<div style="color:#888;">No production recorded.</div>';
        } else {
            productionHtml = '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:340px;margin:0 auto;">';
            for (var pe = 0; pe < Math.min(prodEntries.length, 15); pe++) {
                var gLabel = prodEntries[pe].good.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                productionHtml += '<span style="text-align:left;">' + gLabel + '</span><span style="color:#90d090;text-align:right;">' + prodEntries[pe].qty + '</span>';
            }
            productionHtml += '</div>';
        }

        // Caravans summary
        var caravans = p.caravans || [];
        var caravansCompleted = stats.caravansCompleted || 0;

        // Top traded goods (sells)
        var sells = achStats.totalSells || {};
        var sellEntries = [];
        for (var sk in sells) { if (sells[sk] > 0) sellEntries.push({ good: sk, qty: sells[sk] }); }
        sellEntries.sort(function(a, b) { return b.qty - a.qty; });
        var top10Trades = '';
        if (sellEntries.length === 0) {
            top10Trades = '<div style="color:#888;">No goods sold.</div>';
        } else {
            top10Trades = '<div style="display:grid;grid-template-columns:auto 1fr auto;gap:2px 8px;max-width:340px;margin:0 auto;">';
            for (var ti = 0; ti < Math.min(sellEntries.length, 10); ti++) {
                var tLabel = sellEntries[ti].good.replace(/_/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
                top10Trades += '<span style="color:#888;">#' + (ti + 1) + '</span><span style="text-align:left;">' + tLabel + '</span><span style="color:#f0c040;text-align:right;">' + sellEntries[ti].qty + '</span>';
            }
            top10Trades += '</div>';
        }

        // Social status per kingdom
        var rankHtml = '';
        var sr = p.socialRank || {};
        var kingdoms = Engine.getKingdoms ? Engine.getKingdoms() : [];
        for (var ki = 0; ki < kingdoms.length; ki++) {
            var kd = kingdoms[ki];
            var rank = sr[kd.id] || 0;
            var rankName = (typeof CONFIG !== 'undefined' && CONFIG.SOCIAL_RANKS && CONFIG.SOCIAL_RANKS[rank]) ? CONFIG.SOCIAL_RANKS[rank].name : 'Peasant';
            var rep = (p.reputation && p.reputation[kd.id]) || 0;
            rankHtml += '<div style="display:flex;justify-content:space-between;gap:8px;"><span>' + kd.name + '</span><span style="color:#e8c080;">' + rankName + ' (Rep: ' + Math.round(rep) + ')</span></div>';
        }
        if (!rankHtml) rankHtml = '<div style="color:#888;">No kingdoms.</div>';

        // Gold summary
        var goldEarned = stats.totalGoldEarned || 0;
        var goldSpent = stats.totalGoldSpent || 0;
        var finalGold = Player.gold || 0;

        // Generation
        var generation = achStats.generation || 1;

        var body =
            '<div style="max-height:65vh;overflow-y:auto;padding:4px 8px;text-align:center;font-size:0.88rem;color:#d4c4a0;">' +
            '<h3 style="color:#f0c040;margin:4px 0 10px;">📊 The Legacy of ' + (p.fullName || 'Unknown') + '</h3>' +
            '<div style="color:#aaa;font-size:0.8rem;margin-bottom:10px;">Generation ' + generation + ' · ' + years + ' year' + (years !== 1 ? 's' : '') + ' in business</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">💰 Financial Summary</div>' +
            '<div style="display:grid;grid-template-columns:1fr auto;gap:2px 12px;max-width:300px;margin:0 auto;">' +
            '<span>Total Gold Earned</span><span style="color:#90d090;">' + formatGold(goldEarned) + '</span>' +
            '<span>Total Gold Spent</span><span style="color:#d09090;">' + formatGold(goldSpent) + '</span>' +
            '<span>Net Profit</span><span style="color:' + (goldEarned - goldSpent >= 0 ? '#90d090' : '#d09090') + ';">' + formatGold(goldEarned - goldSpent) + '</span>' +
            '<span>Final Gold</span><span style="color:#f0c040;">' + formatGold(finalGold) + '</span>' +
            '<span>Trades Completed</span><span style="color:#c0c0c0;">' + (stats.tradesCompleted || 0) + '</span>' +
            '</div></div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">🏗️ Buildings (' + buildings.length + ')</div>' +
            buildHtml + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">⚒️ Total Production</div>' +
            productionHtml + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">🐪 Caravans</div>' +
            '<div>Active: ' + caravans.length + ' · Completed: ' + caravansCompleted + '</div>' +
            '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">📈 Top Goods Sold</div>' +
            top10Trades + '</div>' +

            '<div style="background:rgba(60,50,30,0.4);border:1px solid rgba(180,150,80,0.3);border-radius:6px;padding:8px;margin-bottom:10px;">' +
            '<div style="color:#f0c040;font-weight:bold;margin-bottom:4px;">👑 Status Across Kingdoms</div>' +
            rankHtml + '</div>' +

            '</div>';

        var footer = '<button class="btn-medieval" data-action="closeModal">Close</button>';
        openModal('📊 Business Legacy', body, footer);
    }

    // ═══════════════════════════════════════════════════════════
    //  ACTION HELPERS (called from onclick attributes)
    //  EXTRACTED TO: js/modules/ui_actions.js
    //  Functions registered on UI namespace by the module.
    // ═══════════════════════════════════════════════════════════

    // ═══════════════════════════════════════════════════════════
    //  UTILITY
    // ═══════════════════════════════════════════════════════════

    function formatGold(n) {
        if (n >= 10000) return (n / 1000).toFixed(1) + 'k';
        return Math.floor(n).toLocaleString();
    }

    function capitalize(s) {
        return s.charAt(0).toUpperCase() + s.slice(1);
    }

    function formatStrategy(s) {
        if (!s) return '—';
        return s.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    }

    function findResource(id) {
        for (const key in RESOURCE_TYPES) {
            if (RESOURCE_TYPES[key].id === id) return RESOURCE_TYPES[key];
        }
        return null;
    }

    function findBuildingType(id) {
        for (const key in BUILDING_TYPES) {
            if (BUILDING_TYPES[key].id === id) return BUILDING_TYPES[key];
        }
        return null;
    }

    // ═══════════════════════════════════════════════════════════
    //  PUBLIC API
    // ═══════════════════════════════════════════════════════════

    // ── KINGDOMS PAGE ──

    function showKingdomTowns(kingdomId) {
        var kingdom = Engine.findKingdom(kingdomId);
        if (!kingdom) { toast('Kingdom not found.', 'error'); return; }
        var allTowns = Engine.getTowns();
        var towns = allTowns.filter(function(t) { return t.kingdomId === kingdomId; });
        var roads = [];
        var seaRoutes = [];
        try { roads = Engine.getRoads(); } catch(e) {}
        try { seaRoutes = Engine.getSeaRoutes(); } catch(e) {}

        var html = '<div style="margin-bottom:10px;">';
        html += '<button class="btn-medieval" data-action="openKingdomsDialog" style="font-size:0.8rem;padding:4px 12px;">← Back to Kingdoms</button>';
        html += ' <span style="font-size:0.9rem;color:' + (kingdom.color || '#ccc') + ';font-weight:bold;margin-left:8px;">' + kingdom.name + ' — ' + towns.length + ' towns</span>';
        html += '</div>';

        html += '<div style="display:flex;flex-direction:column;gap:8px;max-height:60vh;overflow-y:auto;">';
        for (var ti = 0; ti < towns.length; ti++) {
            var town = towns[ti];
            var pop = town.population || 0;
            var prosp = Math.round(town.prosperity || 0);
            var cat = town.category || 'village';
            var catLabel = cat.charAt(0).toUpperCase() + cat.slice(1).replace('_', ' ');

            // Road connections
            var connNames = [];
            for (var ri = 0; ri < roads.length; ri++) {
                var rd = roads[ri];
                if (rd.fromTownId === town.id || rd.toTownId === town.id) {
                    var otherId = rd.fromTownId === town.id ? rd.toTownId : rd.fromTownId;
                    var other = Engine.findTown(otherId);
                    if (other) connNames.push(other.name);
                }
            }
            // Sea connections
            var seaNames = [];
            for (var si = 0; si < seaRoutes.length; si++) {
                var sr = seaRoutes[si];
                if (sr.fromTownId === town.id || sr.toTownId === town.id) {
                    var seaOtherId = sr.fromTownId === town.id ? sr.toTownId : sr.fromTownId;
                    var seaOther = Engine.findTown(seaOtherId);
                    if (seaOther) seaNames.push(seaOther.name);
                }
            }

            // Key buildings (unique types, max 6)
            var bldNames = [];
            var seenBld = {};
            for (var bi = 0; bi < (town.buildings || []).length; bi++) {
                var bt = Engine.findBuildingType(town.buildings[bi].type);
                var bName = bt ? bt.name : town.buildings[bi].type;
                if (!seenBld[bName]) { seenBld[bName] = true; bldNames.push(bName); }
                if (bldNames.length >= 6) break;
            }

            // Security and happiness
            var security = Math.round(town.security || 0);
            var happiness = Math.round(town.happiness || 50);

            // Is player here?
            var isHere = typeof Player !== 'undefined' && Player.townId === town.id;

            html += '<div style="border:1px solid var(--border);border-radius:6px;padding:10px;' + (isHere ? 'border-left:3px solid #55a868;' : '') + '">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<strong style="font-size:0.95rem;">' + town.name + '</strong>';
            html += '<span style="font-size:0.8rem;color:var(--text-muted);">' + catLabel + '</span>';
            html += '</div>';
            html += '<div style="display:flex;flex-wrap:wrap;gap:10px;font-size:0.82rem;margin:4px 0;color:var(--text-muted);">';
            html += '<span>👥 ' + pop + '</span>';
            html += '<span>📊 ' + prosp + '%</span>';
            html += '<span>🛡️ ' + security + '</span>';
            html += '<span>😊 ' + happiness + '</span>';
            if (town.isPort) html += '<span>🚢 Port</span>';
            if (town.isIsland) html += '<span>🏝️ Island</span>';
            if (isHere) html += '<span style="color:#55a868;font-weight:bold;">📍 You are here</span>';
            html += '</div>';
            if (connNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">🛤️ Roads: ' + connNames.join(', ') + '</div>';
            if (seaNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">⚓ Sea: ' + seaNames.join(', ') + '</div>';
            if (bldNames.length > 0) html += '<div style="font-size:0.78rem;color:var(--text-muted);">🏗️ ' + bldNames.join(', ') + (Object.keys(seenBld).length < (town.buildings || []).length ? '…' : '') + '</div>';
            html += '</div>';
        }
        html += '</div>';

        openModal('🏘️ ' + kingdom.name + ' — Towns', html);
    }

    // ═══════════════════════════════════════════════════════════
    //  SUCCESSION ELECTION VOTING UI
    // ═══════════════════════════════════════════════════════════

    var _electionShown = {};

    function _checkPendingElection() {
        if (typeof Player === 'undefined' || typeof Engine === 'undefined') return;
        var playerKingdomId = Player.citizenshipKingdomId || Player.kingdomId;
        if (!playerKingdomId) return;
        try {
            var election = Engine.getPendingElection(playerKingdomId);
            if (!election) { _electionShown[playerKingdomId] = false; return; }
            if (_electionShown[playerKingdomId]) return; // already shown this election
            _electionShown[playerKingdomId] = true;
            // Small delay so toast renders first
            setTimeout(function() { showElectionVotingModal(playerKingdomId, election); }, 500);
        } catch (e) { /* engine not ready */ }
    }

    function showElectionVotingModal(kingdomId, election) {
        if (!election || !election.candidates) return;
        var kingdom = Engine.getKingdom ? Engine.getKingdom(kingdomId) : Engine.findKingdom(kingdomId);
        var kName = kingdom ? kingdom.name : 'the Kingdom';
        var daysLeft = Math.max(0, 30 - (Engine.getDay() - election.startDay));

        var html = '';
        html += '<div style="text-align:center;margin-bottom:12px;">';
        html += '<div style="font-size:1.1rem;color:#ffd700;margin-bottom:4px;">👑 Succession Election</div>';
        html += '<div style="font-size:0.85rem;color:#ccc;">' + election.deadKingName + ' has died with no heir.</div>';
        html += '<div style="font-size:0.8rem;color:#aaa;">The Royal Council of ' + kName + ' must elect a new ruler.</div>';
        html += '<div style="font-size:0.75rem;color:#888;margin-top:4px;">⏳ ' + daysLeft + ' days until auto-resolution</div>';
        html += '</div>';

        html += '<div style="display:grid;gap:8px;max-height:400px;overflow-y:auto;padding:4px;">';
        // Sort: player first, then by score descending
        var sorted = election.candidates.slice().sort(function(a, b) {
            if (a.isPlayer) return -1;
            if (b.isPlayer) return 1;
            return b.score - a.score;
        });
        for (var i = 0; i < sorted.length; i++) {
            var c = sorted[i];
            var borderColor = c.isPlayer ? 'rgba(100,200,255,0.6)' : 'rgba(180,160,120,0.4)';
            var bgColor = c.isPlayer ? 'rgba(100,200,255,0.08)' : 'rgba(40,35,25,0.6)';
            var youTag = c.isPlayer ? ' <span style="color:#4dc8ff;font-size:0.7rem;">(YOU)</span>' : '';
            html += '<div style="background:' + bgColor + ';border:1px solid ' + borderColor + ';border-radius:6px;padding:10px 12px;cursor:pointer;transition:background 0.15s;" ';
            html += 'onmouseover="this.style.background=\'rgba(255,215,0,0.12)\'" onmouseout="this.style.background=\'' + bgColor + '\'" ';
            html += 'data-action="_castElectionVote" data-kingdom="' + kingdomId + '" data-id="' + c.id + '" data-name="' + c.name.replace(/'/g, '') + '">';
            html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
            html += '<div>';
            html += '<div style="font-size:0.95rem;color:#e8d5a3;font-weight:bold;">' + c.name + youTag + '</div>';
            html += '<div style="font-size:0.75rem;color:#aaa;">' + (c.occupation.charAt(0).toUpperCase() + c.occupation.slice(1)) + ', Age ' + c.age + '</div>';
            html += '</div>';
            html += '<div style="text-align:right;">';
            html += '<div style="font-size:0.8rem;color:#ffd700;">💰 ' + Math.round(c.gold).toLocaleString() + 'g</div>';
            html += '</div>';
            html += '</div>';
            // Stats bar
            html += '<div style="display:flex;gap:12px;margin-top:6px;font-size:0.7rem;color:#999;">';
            html += '<span>🧠 Int: ' + c.intelligence + '</span>';
            html += '<span>⚔️ Ambition: ' + c.ambition + '</span>';
            html += '<span>👥 Charisma: ' + c.charisma + '</span>';
            html += '</div>';
            html += '</div>';
        }
        html += '</div>';

        html += '<div style="text-align:center;margin-top:10px;font-size:0.75rem;color:#888;">';
        html += 'Click a candidate to cast your vote. Your endorsement carries great weight as Royal Advisor.';
        html += '</div>';

        var footer = '<button class="btn-medieval" data-action="closeModal" style="font-size:0.8rem;padding:5px 18px;opacity:0.6;">Abstain (Let Others Decide)</button>';

        openModal('👑 Royal Election — ' + kName, html, footer);
    }

    function _castElectionVote(kingdomId, candidateId, candidateName) {
        var result = Engine.castElectionVote(kingdomId, candidateId);
        closeModal();
        if (result && result.success) {
            toast('👑 You cast your vote for ' + candidateName + '. The council deliberates...', 'success', 'critical');
        } else {
            toast('Election has already been resolved.', 'warning');
        }
        _electionShown[kingdomId] = false;
    }

    function openKingdomsDialog() {
        let kingdoms;
        try { kingdoms = Engine.getKingdoms(); } catch (e) { kingdoms = []; }
        if (!kingdoms || kingdoms.length === 0) {
            toast('No kingdoms to display.', 'warning');
            return;
        }

        // Kingdom cards
        let cardsHtml = '<div class="kingdom-cards">';
        for (const k of kingdoms) {
            const king = k.king ? Engine.findPerson(k.king) : null;
            const kingName = king ? king.firstName + ' ' + king.lastName : 'Unknown';
            const numTowns = k.territories ? (k.territories.size != null ? k.territories.size : (k.territories.length || 0)) : 0;
            const prosperityPct = Math.max(0, Math.min(100, k.prosperity || 0));
            const wealthLabel = k.gold > 10000 ? '💰 Wealthy' : k.gold > 5000 ? '💰 Moderate' : '💰 Poor';
            const isHome = typeof Player !== 'undefined' && Player.isPlayerCitizenOf ? Player.isPlayerCitizenOf(k.id) : (typeof Player !== 'undefined' && Player.citizenshipKingdomId ? k.id === Player.citizenshipKingdomId : false);
            const rep = (typeof Player !== 'undefined' && Player.reputation) ? (Player.reputation[k.id] || 0) : 0;
            const rankIdx = (typeof Player !== 'undefined' && Player.socialRank) ? (Player.socialRank[k.id] || 0) : 0;
            const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

            // Foreign noble status for non-home kingdoms
            var foreignNobleStatus = '';
            if (!isHome && typeof Player !== 'undefined' && Player.getForeignNobleStatus) {
                var fns = Player.getForeignNobleStatus(k.id);
                if (fns === 'foreign_minor_noble') foreignNobleStatus = '<span style="color:#8ba;font-size:0.75rem;"> (Foreign Minor Noble)</span>';
                else if (fns === 'foreign_noble') foreignNobleStatus = '<span style="color:#8ba;font-size:0.75rem;"> (Foreign Noble)</span>';
                else if (fns === 'enemy_minor_noble') foreignNobleStatus = '<span style="color:#c44e52;font-size:0.75rem;"> (Enemy Minor Noble)</span>';
                else if (fns === 'enemy_noble') foreignNobleStatus = '<span style="color:#c44e52;font-size:0.75rem;"> (Enemy Noble)</span>';
            }

            // Laws
            let lawsHtml = '';
            if (k.laws) {
                if (k.laws.bannedGoods && k.laws.bannedGoods.length > 0) {
                    const banned = k.laws.bannedGoods.map(g => {
                        const res = Object.values(RESOURCE_TYPES).find(r => r.id === g);
                        return res ? res.icon + ' ' + res.name : g;
                    }).join(', ');
                    lawsHtml += `<div class="law-item" style="cursor:help;" title="Banned items are illegal to make or sell, but legal to buy or own in small amounts.">🚫 Banned: ${banned}</div>`;
                }
                lawsHtml += `<div class="law-item">💸 Tariff: ${Math.round((k.laws.tradeTariff || 0) * 100)}%</div>`;
                if (k.laws.conscription) lawsHtml += `<div class="law-item">⚔️ Conscription Active</div>`;
                if (k.laws.guildRestrictions) lawsHtml += `<div class="law-item">🔨 Guild Restrictions</div>`;
            }

            const _warEntries = k.atWar ? (k.atWar instanceof Set ? Array.from(k.atWar) : (Array.isArray(k.atWar) ? k.atWar : [])) : [];
            const warList = _warEntries.length > 0 ? _warEntries.map(wId => {
                const wk = kingdoms.find(kk => kk.id === wId);
                return wk ? wk.name : wId;
            }).join(', ') : '';

            // Goods taxes
            let goodsTaxHtml = '';
            if (k.laws && k.laws.goodsTaxes) {
                const taxEntries = Object.entries(k.laws.goodsTaxes);
                if (taxEntries.length > 0) {
                    const taxNames = taxEntries.map(([g, rate]) => {
                        const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === g);
                        return `${r ? r.icon : ''} ${r ? r.name : g} (${Math.round(rate * 100)}%)`;
                    }).join(', ');
                    goodsTaxHtml = `<div class="law-item">💸 Goods Taxes: ${taxNames}</div>`;
                }
            }

            // Restricted goods
            let restrictedHtml = '';
            if (k.laws && k.laws.restrictedGoods && k.laws.restrictedGoods.length > 0) {
                const rNames = k.laws.restrictedGoods.map(g => {
                    const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === g);
                    const hasLic = Player.hasLicense(k.id, g);
                    return `${r ? r.icon : ''} ${r ? r.name : g} ${hasLic ? '✅' : '🔒'}`;
                }).join(', ');
                restrictedHtml = `<div class="law-item" style="cursor:help;" title="Legal to buy. Illegal to sell or produce without a license. Purchase a license from the Kingdom menu.">🔒 Restricted: ${rNames}</div>`;
            }

            // Player licenses in this kingdom
            let playerLicHtml = '';
            const myLicenses = Player.licenses[k.id] || [];
            if (myLicenses.length > 0) {
                const licNames = myLicenses.map(g => {
                    var resId = typeof g === 'string' ? g : g.resourceId;
                    const r = Object.values(RESOURCE_TYPES).find(rr => rr.id === resId);
                    return r ? r.icon + ' ' + r.name : resId;
                }).join(', ');
                playerLicHtml = `<div class="kc-row" style="font-size:0.75rem;color:#55a868;">📜 Your Licenses: ${licNames}</div>`;
            }
            // Buy licenses button — show if kingdom has restricted goods with unlicensed items
            let licenseBtnHtml = '';
            if (k.laws && k.laws.restrictedGoods && k.laws.restrictedGoods.length > 0) {
                var _unlicensed = k.laws.restrictedGoods.filter(function(g) { return !Player.hasLicense(k.id, g); });
                if (_unlicensed.length > 0) {
                    licenseBtnHtml = '<div class="kc-row"><button class="btn-medieval" data-action="openKingdomLicenses" data-id="' + k.id + '" style="font-size:0.75rem;padding:4px 12px;color:#e8dcc8;background:rgba(180,140,50,0.2);border-color:rgba(180,140,50,0.4);">📜 Buy Licenses (' + _unlicensed.length + ' available)</button></div>';
                }
            }

            // Guard strength indicator
            let guardIcons = '';
            const kTowns = Engine.getTowns().filter(t => t.kingdomId === k.id);
            const avgSecurity = kTowns.length > 0 ? kTowns.reduce((s, t) => s + (t.security || 0), 0) / kTowns.length : 0;
            const guardLevel = avgSecurity > 70 ? '🛡️🛡️🛡️' : avgSecurity > 40 ? '🛡️🛡️' : avgSecurity > 15 ? '🛡️' : '⚠️';

            // War and alliance status
            var warStatusHtml = '';
            if (k.atWar && ((k.atWar instanceof Set && k.atWar.size > 0) || (Array.isArray(k.atWar) && k.atWar.length > 0))) {
                warStatusHtml = '<div class="kc-row" style="color:var(--danger);font-weight:bold;">⚔️ At War with: ' + warList + '</div>';
            } else {
                warStatusHtml = '<div class="kc-row" style="color:#55a868;">☮️ At Peace</div>';
            }

            var allianceHtml = '';
            var allies = k.alliances || [];
            if (allies.length > 0) {
                var allyNames = allies.map(function(aId) {
                    var ak = kingdoms.find(function(kk) { return kk.id === aId; });
                    var aType = (k.allianceMeta && k.allianceMeta[aId]) ? k.allianceMeta[aId].type : '';
                    var typeLabel = aType === 'offensive' ? '⚔' : aType === 'defensive' ? '🛡' : '';
                    return (ak ? ak.name : aId) + (typeLabel ? ' ' + typeLabel : '');
                }).join(', ');
                allianceHtml = '<div class="kc-row" style="color:#5dade2;">🤝 Allies: ' + allyNames + '</div>';
            } else {
                allianceHtml = '<div class="kc-row" style="color:#888;">🤝 No Alliances</div>';
            }

            cardsHtml += `<div class="kingdom-card ${isHome ? 'kingdom-home' : ''}" style="border-left: 4px solid ${k.color};">
                <div class="kc-header" style="color:${k.color};">${k.name}</div>
                <div class="kc-row">👑 King: ${kingName}</div>
                <div class="kc-row">🏘️ Towns: ${numTowns}</div>
                <div class="kc-row">📊 Prosperity: <span class="mini-bar"><span class="mini-fill" style="width:${prosperityPct}%;background:${k.color};"></span></span></div>
                <div class="kc-row">⚔️ Military: ${k.militaryStrength || 0}</div>
                <div class="kc-row">${wealthLabel}</div>
                <div class="kc-row" style="font-size:0.85rem;font-weight:bold;color:var(--gold);">📜 Tax: ${Math.round((k.taxRate || 0.1) * 100)}%</div>
                <div class="kc-row">Guard Strength: ${guardLevel}</div>
                ${warStatusHtml}
                ${allianceHtml}
                ${goodsTaxHtml}
                ${restrictedHtml}
                ${lawsHtml ? `<div class="kc-laws">${lawsHtml}</div>` : ''}
                ${playerLicHtml}
                ${licenseBtnHtml}
                ${isHome ? '<div class="kc-home-badge">★ YOUR HOME</div>' : ''}
                <div class="kc-row" style="margin-top:4px;font-size:0.8rem;">
                    <span style="color:#aaa;">Status:</span> ${rank.icon} <span style="color:#d4af37;">${rank.name}</span>${foreignNobleStatus}
                </div>
                <div style="margin-top:2px;">
                    <div style="display:flex;justify-content:space-between;font-size:0.75rem;margin-bottom:2px;">
                        <span style="color:#aaa;">Reputation:</span>
                        <span style="color:${rep >= 70 ? '#55a868' : rep >= 40 ? '#ccb974' : '#c44e52'};">${Math.floor(rep)}/100</span>
                    </div>
                    <div style="background:rgba(0,0,0,0.4);border:1px solid #444;border-radius:3px;height:8px;">
                        <div style="height:100%;width:${Math.max(0, Math.min(100, rep))}%;background:${k.color || '#ccb974'};border-radius:2px;transition:width 0.3s;"></div>
                    </div>
                </div>
                <div class="kc-buttons" style="display:flex;gap:4px;flex-wrap:wrap;margin-top:6px;">
                    <button class="kc-btn" data-action="towns" data-kid="${k.id}" title="View Towns">🏘️ Towns</button>
                    <button class="kc-btn" data-action="laws" data-kid="${k.id}" title="View Laws">📜 Laws</button>
                    <button class="kc-btn" data-action="trade" data-kid="${k.id}" title="Trade Routes">🏛️ Trade</button>
                    ${isHome ? '<button class="kc-btn" data-action="orders" data-kid="' + k.id + '" title="Kingdom Orders">📋 Orders</button>' : ''}
                    <button class="kc-btn" data-action="commissions" data-kid="${k.id}" title="Royal Commissions">📦 Commissions</button>
                    ${isHome ? '<button class="kc-btn" data-action="petition" data-kid="' + k.id + '" title="Submit Petition">📝 Petition</button>' : ''}
                    <button class="kc-btn" data-action="donate" data-kid="${k.id}" title="Donate Gold">💰 Donate</button>
                </div>
            </div>`;
        }
        cardsHtml += '</div>';

        // Diplomacy matrix
        let matrixHtml = '<div class="diplo-matrix"><table class="diplo-table"><tr><th></th>';
        for (const k of kingdoms) {
            matrixHtml += `<th style="color:${k.color};">${k.name.slice(0, 4)}</th>`;
        }
        matrixHtml += '</tr>';
        for (const ki of kingdoms) {
            matrixHtml += `<tr><td style="color:${ki.color};">${ki.name.slice(0, 4)}</td>`;
            for (const kj of kingdoms) {
                if (ki.id === kj.id) {
                    matrixHtml += '<td>──</td>';
                } else {
                    const rel = ki.relations[kj.id] || 0;
                    const atWar = ki.atWar && (ki.atWar.has ? ki.atWar.has(kj.id) : ki.atWar.includes(kj.id));
                    let emoji, cls;
                    if (atWar) { emoji = '💀'; cls = 'diplo-war'; }
                    else if (rel > 60) { emoji = '😊'; cls = 'diplo-ally'; }
                    else if (rel < -30) { emoji = '😡'; cls = 'diplo-hostile'; }
                    else { emoji = '😐'; cls = 'diplo-neutral'; }
                    matrixHtml += `<td class="${cls}" title="${ki.name}→${kj.name}: ${rel}">${emoji}</td>`;
                }
            }
            matrixHtml += '</tr>';
        }
        matrixHtml += '</table></div>';

        // Your Status summary
        const citizenK = Player.citizenshipKingdomId ? kingdoms.find(k => k.id === Player.citizenshipKingdomId) : null;
        const citizenName = citizenK ? citizenK.name : 'Stateless';
        const citizenColor = citizenK ? citizenK.color : '#888';
        const rankIdx = Player.citizenshipKingdomId ? (Player.socialRank[Player.citizenshipKingdomId] || 0) : 0;
        const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

        // Count kingdoms where player is citizen
        let citizenCountHtml = '';
        const citizenKingdomsList = [];
        if (Player.socialRank) {
            for (const kId in Player.socialRank) {
                if ((Player.socialRank[kId] || 0) >= 1) {
                    const ck = kingdoms.find(function(x) { return x.id === kId; });
                    citizenKingdomsList.push(ck ? ck.name : kId);
                }
            }
        }
        if (citizenKingdomsList.length > 1) {
            citizenCountHtml = `<div class="detail-row"><span class="label">All Citizenships</span>
                <span class="value">${citizenKingdomsList.join(', ')}</span></div>`;
        }

        let statusHtml = `<div class="your-status">
            <h3>Your Status</h3>
            <div class="detail-row"><span class="label">Primary Kingdom</span>
                <span class="value" style="color:${citizenColor};">${citizenName}</span></div>
            ${citizenCountHtml}
            <div class="detail-row"><span class="label">Rank</span>
                <span class="value">${rank.icon} ${rank.name} (${rankIdx + 1}/7)</span></div>`;

        // Jailed?
        if (Player.jailedUntilDay > 0 && Engine.getDay() < Player.jailedUntilDay) {
            statusHtml += `<div class="detail-row" style="color:var(--danger);"><span class="label">⛓️ Jailed</span>
                <span class="value">Until day ${Player.jailedUntilDay}</span></div>`;
        }
        if (Player.smugglingSkill > 0) {
            statusHtml += `<div class="detail-row"><span class="label">🗡️ Smuggling Skill</span>
                <span class="value">${Player.smugglingSkill}</span></div>`;
        }
        statusHtml += '</div>';

        // L4: World History button
        let historyBtnHtml = '<div style="text-align:center;margin:12px 0;">' +
            '<button class="btn-medieval" id="btnWorldChronicle" style="font-size:1rem;padding:8px 20px;' +
            'background:rgba(180,140,50,0.15);border-color:rgba(180,140,50,0.4);color:#e8dcc8;">' +
            '📜 World History Chronicle</button></div>';

        const html = historyBtnHtml + cardsHtml + matrixHtml + statusHtml;
        openModal('👑 Kingdoms of the Realm', html);

        // Attach kingdom card button handlers
        var kcBtns = document.querySelectorAll('.kc-btn');
        for (var bi = 0; bi < kcBtns.length; bi++) {
            kcBtns[bi].addEventListener('click', function(e) {
                var action = this.getAttribute('data-action');
                var kid = this.getAttribute('data-kid');
                if (action === 'towns') showKingdomTowns(kid);
                else if (action === 'laws') UI.openKingdomLawsPanel(kid);
                else if (action === 'trade') UI.showKingdomTradePanel(kid);
                else if (action === 'orders') UI.showKingdomOrdersPanel(kid);
                else if (action === 'commissions') UI.openRoyalCommissionsPanel(kid);
                else if (action === 'petition') UI.showPetitionsPanel();
                else if (action === 'donate') UI.openKingdomDonateDialog(kid);
            });
        }
        // L4: World History Chronicle button handler
        var btnChronicle = document.getElementById('btnWorldChronicle');
        if (btnChronicle) {
            btnChronicle.addEventListener('click', function() {
                openWorldChronicle();
            });
        }
    }

    // ============================================================
    // L4 — WORLD HISTORICAL CHRONICLE
    // ============================================================
    function openWorldChronicle() {
        var chronicle = [];
        try { chronicle = Engine.getWorldChronicle(); } catch(e) {}
        var currentDay = 0;
        try { currentDay = Engine.getDay(); } catch(e) {}

        // Categorize events
        var categories = {
            wars: { icon: '⚔️', label: 'Wars & Battles', events: [] },
            politics: { icon: '👑', label: 'Royal & Political', events: [] },
            revolts: { icon: '🔥', label: 'Revolts & Uprisings', events: [] },
            diplomacy: { icon: '🤝', label: 'Diplomacy & Treaties', events: [] },
            disasters: { icon: '💀', label: 'Disasters & Crises', events: [] },
            laws: { icon: '📜', label: 'Laws & Decrees', events: [] },
            social: { icon: '🎪', label: 'Feasts & Court', events: [] },
            status: { icon: '📜', label: 'Yearly Kingdom Status', events: [] }
        };

        var warTypes = ['war_declared', 'warDeclared', 'warEnded', 'peace', 'surrender', 'battle_result', 'siege_started', 'siege_ended'];
        var politicsTypes = ['king_death', 'coronation', 'succession', 'assassination', 'assassination_attempt', 'conspiracy_discovered', 'noble_revolt_execution', 'noble_revolt_stripped', 'solo_assassination', 'solo_assassination_failed', 'conspiracy_detected', 'conspiracy_assassination', 'conspiracy_coup', 'conspiracy_failed', 'noble_punishment', 'noble_execution', 'noble_exile'];
        var revoltTypes = ['revolt', 'town_revolt_win', 'town_revolt_lose', 'revolt_started', 'revolt_victory', 'revolt_suppressed'];
        var diploTypes = ['alliance_formed', 'alliance_broken', 'alliance_dissolved', 'non_aggression_pact', 'royal_marriage', 'territory_transfer', 'trade_agreement', 'mutual_defense_pact', 'border_accord', 'em_defection', 'peace_treaty', 'trade_deal'];
        var disasterTypes = ['kingdom_collapse', 'economic_collapse', 'kingdom_bankruptcy', 'plague_started', 'plague_ended'];
        var lawTypes = ['law_passed', 'law_repealed'];
        var socialTypes = ['feast_started', 'court_session'];
        var statusTypes = ['yearly_kingdom_summary'];

        for (var i = 0; i < chronicle.length; i++) {
            var evt = chronicle[i];
            var dtype = (evt.details && evt.details.type) ? evt.details.type : '';
            if (warTypes.indexOf(dtype) >= 0) categories.wars.events.push(evt);
            else if (politicsTypes.indexOf(dtype) >= 0) categories.politics.events.push(evt);
            else if (revoltTypes.indexOf(dtype) >= 0) categories.revolts.events.push(evt);
            else if (diploTypes.indexOf(dtype) >= 0) categories.diplomacy.events.push(evt);
            else if (disasterTypes.indexOf(dtype) >= 0) categories.disasters.events.push(evt);
            else if (lawTypes.indexOf(dtype) >= 0) categories.laws.events.push(evt);
            else if (socialTypes.indexOf(dtype) >= 0) categories.social.events.push(evt);
            else if (statusTypes.indexOf(dtype) >= 0) categories.status.events.push(evt);
            else categories.politics.events.push(evt); // default
        }

        // Helper: format day as year/season/day (1 year = 1 season = 90 days)
        function formatChronicleDay(day) {
            var dps = CONFIG.DAYS_PER_SEASON || 90;
            var year = Math.floor(day / dps) + 1;
            var dayInYear = (day % dps) + 1;
            var seasons = ['Spring', 'Summer', 'Autumn', 'Winter'];
            var season = seasons[(Math.floor(day / dps)) % 4] || 'Spring';
            return 'Year ' + year + ', ' + season + ' Day ' + dayInYear;
        }

        var html = '<div style="max-height:70vh;overflow-y:auto;padding:0 8px;">';
        html += '<p style="color:#aaa;font-style:italic;margin-bottom:12px;">A chronicle of the great events that have shaped this world. ' +
                'Total recorded events: ' + chronicle.length + '</p>';

        // Show categories with events
        var catKeys = ['wars', 'politics', 'revolts', 'diplomacy', 'disasters', 'laws', 'social'];
        for (var ci = 0; ci < catKeys.length; ci++) {
            var cat = categories[catKeys[ci]];
            if (cat.events.length === 0) continue;

            html += '<div style="margin:12px 0;">';
            html += '<h3 style="color:var(--gold);border-bottom:1px solid rgba(180,140,50,0.3);padding-bottom:4px;margin-bottom:8px;">' +
                    cat.icon + ' ' + escapeHtml(cat.label) + ' <span style="color:#888;font-size:0.8rem;">(' + cat.events.length + ')</span></h3>';

            // Show events newest first, cap at 30 per category
            var evts = cat.events.slice().reverse();
            var showCount = Math.min(evts.length, 30);
            for (var ei = 0; ei < showCount; ei++) {
                var e = evts[ei];
                var dayLabel = formatChronicleDay(e.day);
                var playerMark = e.playerInvolved ? ' <span style="color:var(--gold);">★</span>' : '';
                var msgText = escapeHtml(e.message).replace(/\n/g, '<br>').replace(/[⚔️🛡️👑🔥💀🎪⚖️🤝📜💰🏰🗡️🔗📨]/g, function(m) { return '<span>' + m + '</span>'; });

                html += '<div style="margin:4px 0;padding:4px 8px;border-left:2px solid rgba(180,140,50,0.2);font-size:0.85rem;">';
                html += '<span style="color:#888;font-size:0.75rem;">' + escapeHtml(dayLabel) + '</span>' + playerMark + '<br>';
                html += '<span style="color:#ddd;">' + msgText + '</span>';
                html += '</div>';
            }
            if (evts.length > 30) {
                html += '<div style="color:#888;font-size:0.75rem;text-align:center;">...and ' + (evts.length - 30) + ' earlier events</div>';
            }
            html += '</div>';
        }

        if (chronicle.length === 0) {
            html += '<p style="color:#888;text-align:center;margin:40px 0;">No major events have been recorded yet. History awaits...</p>';
        }

        html += '</div>';
        html += '<div style="text-align:center;margin-top:12px;">';
        html += '<button class="btn-medieval" data-action="openKingdomsDialog" style="padding:6px 16px;">← Back to Kingdoms</button>';
        html += '</div>';

        openModal('📜 World Chronicle — The History of the Realm', html);
    }

    // ── SOCIAL STATUS PAGE (in character dialog) ──

    function buildSocialStatusHtml() {
        const citizenKId = Player.citizenshipKingdomId;
        let kingdoms;
        try { kingdoms = Engine.getKingdoms(); } catch (e) { kingdoms = []; }
        const citizenK = citizenKId ? kingdoms.find(k => k.id === citizenKId) : null;
        const citizenName = citizenK ? citizenK.name : 'Stateless';
        const citizenColor = citizenK ? citizenK.color : '#888';
        const rankIdx = citizenKId ? (Player.socialRank[citizenKId] || 0) : 0;
        const rank = CONFIG.SOCIAL_RANKS[rankIdx] || CONFIG.SOCIAL_RANKS[0];

        let html = `<div class="detail-section">
            <h3>\uD83C\uDFDB\uFE0F Social Status</h3>
            <div class="detail-row"><span class="label">Active Kingdom</span>
                <span class="value" style="color:${citizenColor};">${citizenName}</span></div>
            <div class="detail-row"><span class="label">Active Rank</span>
                <span class="value">${rank.icon} ${rank.name}</span></div>
        </div>`;

        // All kingdoms — show every kingdom, not just those with rank
        const citizenKingdoms = [];
        for (const k of kingdoms) {
            const rankInK = (Player.socialRank && Player.socialRank[k.id]) ? Player.socialRank[k.id] : 0;
            citizenKingdoms.push({ id: k.id, name: k.name, color: k.color || '#888', rankIdx: rankInK });
        }
        // Sort: active kingdom first, then by rank descending
        citizenKingdoms.sort(function(a, b) {
            if (a.id === citizenKId) return -1;
            if (b.id === citizenKId) return 1;
            return b.rankIdx - a.rankIdx;
        });
        if (citizenKingdoms.length > 0) {
            // Auto-lock active kingdom to Lord+ kingdom if player has one
            const _lordK = citizenKingdoms.find(function(c) { return c.rankIdx >= 5; });
            if (_lordK && _lordK.id !== citizenKId && typeof Player !== 'undefined' && Player.setActiveCitizenship) {
                Player.state.citizenshipKingdomId = _lordK.id;
                citizenKId = _lordK.id;
            }
            html += '<div class="detail-section"><h3>\uD83C\uDFE0 Citizenships</h3>';
            for (const ck of citizenKingdoms) {
                const r = CONFIG.SOCIAL_RANKS[ck.rankIdx] || CONFIG.SOCIAL_RANKS[0];
                const isActive = ck.id === citizenKId;
                const activeLabel = isActive ? '<span style="color:#d4af37;font-weight:bold;font-size:0.75rem;margin-left:6px;">⭐ ACTIVE</span>' : '';
                // Hide Set Active if player is Lord+ (rank 5+) in any kingdom — that one is locked
                const hasLordKingdom = citizenKingdoms.some(function(c) { return c.rankIdx >= 5; });
                const lordKingdomId = hasLordKingdom ? citizenKingdoms.find(function(c) { return c.rankIdx >= 5; }).id : null;
                const isLocked = hasLordKingdom && lordKingdomId !== ck.id;
                const isLockedActive = hasLordKingdom && lordKingdomId === ck.id && !isActive;
                const setActiveBtn = (!isActive && !hasLordKingdom) ? `<button class="btn-medieval" data-action="setActiveCitizenship" data-id="${ck.id}" style="font-size:0.7rem;padding:2px 8px;margin-left:4px;background:rgba(212,175,55,0.25);border-color:rgba(212,175,55,0.5);color:#d4af37;">⭐ Set Active</button>` : '';
                const renounceBtn = ck.rankIdx >= 1 ? `<button class="btn-medieval" data-action="renounceKingdomUI" data-id="${ck.id}" style="font-size:0.7rem;padding:2px 8px;margin-left:4px;background:rgba(200,60,50,0.35);border-color:rgba(200,60,50,0.6);color:#f0d0a0;">\u274C Renounce</button>` : '';
                html += `<div class="detail-row" style="margin-bottom:4px;${isActive ? 'background:rgba(212,175,55,0.08);border-radius:4px;padding:2px 4px;' : ''}">
                    <span class="label" style="color:${ck.color};">${ck.name}${activeLabel}</span>
                    <span class="value">${r.icon} ${r.name}
                        <button class="btn-medieval" data-action="showRankProgressionPanel" data-id="${ck.id}" style="font-size:0.7rem;padding:2px 8px;margin-left:6px;">Details</button>
                        ${setActiveBtn}
                        ${renounceBtn}
                    </span>
                </div>`;
            }
            html += '</div>';
        }

        // Rank ladder for primary kingdom
        html += '<div class="detail-section"><h3>\uD83D\uDCCA Rank Ladder</h3><div class="rank-ladder">';
        for (let i = 0; i < CONFIG.SOCIAL_RANKS.length; i++) {
            const r = CONFIG.SOCIAL_RANKS[i];
            const isCurrent = i === rankIdx;
            const isAchieved = i <= rankIdx;
            html += `<div class="rank-step ${isCurrent ? 'rank-current' : ''} ${isAchieved ? 'rank-achieved' : 'rank-locked'}">
                <span class="rank-icon">${r.icon}</span>
                <span class="rank-name">${r.name}</span>
                <span class="rank-perks">\uD83D\uDC65${r.maxWorkers > 999 ? '\u221E' : r.maxWorkers} \uD83C\uDFE0${r.maxBuildings > 999 ? '\u221E' : r.maxBuildings}</span>
                ${!isAchieved ? `<span class="rank-req">${r.goldReq.toLocaleString()}g, ${r.repReq}rep</span>` : ''}
            </div>`;
        }
        html += '</div></div>';

        // Next rank progress
        if (citizenKId && rankIdx < CONFIG.SOCIAL_RANKS.length - 1) {
            const nextRank = CONFIG.SOCIAL_RANKS[rankIdx + 1];
            const goldEarned = (Player.goldEarnedInKingdom && Player.goldEarnedInKingdom[citizenKId]) || 0;
            const rep = (Player.reputation && Player.reputation[citizenKId]) || 0;
            const goldPct = nextRank.goldReq > 0 ? Math.min(100, Math.floor((goldEarned / nextRank.goldReq) * 100)) : 100;
            const repPct = nextRank.repReq > 0 ? Math.min(100, Math.floor((rep / nextRank.repReq) * 100)) : 100;

            // Check detailed requirements
            let reqChecklist = '';
            let _canPetition = false;
            if (Player.canPetitionForPromotion) {
                const check = Player.canPetitionForPromotion(citizenKId);
                if (check.reasons && check.reasons.length > 0) {
                    reqChecklist = '<div style="margin-top:8px;font-size:0.8rem;">';
                    for (const r of check.reasons) {
                        reqChecklist += `<div style="color:#ff8866;">\u274C ${r}</div>`;
                    }
                    reqChecklist += '</div>';
                } else if (check.can) {
                    _canPetition = true;
                    reqChecklist = '<div style="margin-top:8px;font-size:0.8rem;color:#66ff88;">\u2705 All requirements met!</div>';
                }
            }

            var _petBtnStyle = _canPetition
                ? 'margin-top:8px;font-size:0.85rem;padding:6px 16px;background:linear-gradient(180deg,#5aad35,#3a7a24);border-color:#5aad35;color:#fff;animation:petitionGlow 1.5s ease-in-out infinite;'
                : 'margin-top:8px;font-size:0.85rem;padding:6px 16px;';

            html += `<div class="detail-section"><h3>Next: ${nextRank.icon} ${nextRank.name}</h3>
                <div class="progress-row"><span class="label">Gold Earned</span>
                    <div class="progress-bar"><div class="progress-fill" style="width:${goldPct}%"></div></div>
                    <span class="value">${Math.floor(goldEarned).toLocaleString()}/${nextRank.goldReq.toLocaleString()}</span></div>
                <div class="progress-row"><span class="label">Kingdom Reputation</span>
                    <div class="progress-bar"><div class="progress-fill" style="width:${repPct}%"></div></div>
                    <span class="value">${Math.floor(rep)}/${nextRank.repReq}</span></div>
                ${nextRank.fee ? `<div class="detail-row"><span class="label">Fee</span><span class="value">${nextRank.fee.toLocaleString()}g</span></div>` : ''}
                ${nextRank.extraReq ? `<div class="detail-row"><span class="label">Requirements</span><span class="value" style="font-size:0.8rem;">${nextRank.extraReq}</span></div>` : ''}
                ${reqChecklist}
                <button class="btn-medieval" data-action="petitionPromotion" style="${_petBtnStyle}">\uD83D\uDCDC Petition for Promotion</button>
            </div>`;
        }

        // Change citizenship button (if in foreign town where player is not citizen)
        let currentTown;
        try { currentTown = Engine.findTown(Player.townId); } catch (e) { /* no-op */ }
        if (currentTown && Player.isPlayerCitizenOf && !Player.isPlayerCitizenOf(currentTown.kingdomId)) {
            const foreignK = kingdoms.find(k => k.id === currentTown.kingdomId);
            const foreignName = foreignK ? foreignK.name : 'Unknown';
            html += `<div class="detail-section">
                <button class="btn-medieval" data-action="changeCitizenship" data-id="${currentTown.kingdomId}" style="font-size:0.85rem;padding:6px 16px;">\uD83C\uDFDB\uFE0F Petition for ${foreignName} Citizenship</button>
            </div>`;
        }

        return html;
    }

    function petitionPromotion() {
        try {
            // Determine next rank index
            var citizenKId = Player.citizenshipKingdomId;
            var currentIdx = (Player.socialRank && citizenKId) ? (Player.socialRank[citizenKId] || 0) : 0;
            var nextIdx = currentIdx + 1;

            // If entering nobility (Minor Noble, index 4), show confirmation warning first
            if (nextIdx === 4) {
                _showNobilityConfirmation(citizenKId);
                return;
            }

            _executePetition();
        } catch (e) {
            toast(e.message || 'Promotion failed', 'danger');
        }
    }

    function _showNobilityConfirmation(kingdomId) {
        var kingdom = null;
        try { kingdom = Engine.findKingdom(kingdomId); } catch(e) {}
        var kingdomName = kingdom ? kingdom.name : 'the kingdom';

        var html = '<div style="padding:15px;">' +
            '<div style="text-align:center;margin-bottom:15px;">' +
            '<div style="font-size:2.5em;">⚠️👑</div>' +
            '<h3 style="color:#ff8888;margin:5px 0;">Entering the Nobility</h3>' +
            '<div style="color:var(--text-secondary);font-style:italic;">This decision will permanently change your relationship with ' + kingdomName + '.</div>' +
            '</div>' +

            '<div style="padding:12px;background:rgba(200,100,100,0.1);border:1px solid rgba(200,100,100,0.3);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#ff8888;font-weight:bold;margin-bottom:8px;">⚠️ You Will Be Bound to the Crown</div>' +
            '<div style="font-size:0.9em;color:#ddd;">' +
            '<p style="margin:6px 0;">By accepting the title of <b>Minor Noble</b>, you are swearing a binding oath of fealty to the King of ' + kingdomName + '. This is not merely a title — it is a <b>lifelong obligation</b> to the crown.</p>' +
            '</div></div>' +

            '<div style="padding:12px;background:rgba(200,100,100,0.08);border:1px solid rgba(200,100,100,0.25);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#ffaa66;font-weight:bold;margin-bottom:8px;">📋 Your Responsibilities as a Noble</div>' +
            '<div style="font-size:0.85em;">' +
            '<div style="margin:5px 0;">👑 <b>Royal Commissions</b> — The king will assign you personal tasks. Refusal costs reputation and may lead to demotion.</div>' +
            '<div style="margin:5px 0;">⚔️ <b>Wartime Production</b> — During war, you must produce weapons and armor on the king\'s schedule. Failure risks demotion.</div>' +
            '<div style="margin:5px 0;">📊 <b>Reputation Maintenance</b> — Your kingdom reputation must stay above 60 or you will be demoted back to Guildmaster.</div>' +
            '<div style="margin:5px 0;">🏛️ <b>Public Figure</b> — Criminal actions now carry reputation penalties. You are always watched.</div>' +
            '<div style="margin:5px 0;">🌍 <b>Foreign Entanglements</b> — Your foreign status is tied to your kingdom\'s diplomacy. War means losing foreign privileges.</div>' +
            '<div style="margin:5px 0;">💀 <b>Shared Fate</b> — If ' + kingdomName + ' falls to a conqueror, nobles face imprisonment, exile, or execution.</div>' +
            '</div></div>' +

            '<div style="padding:12px;background:rgba(100,200,100,0.08);border:1px solid rgba(100,200,100,0.25);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#66ff88;font-weight:bold;margin-bottom:8px;">✨ Noble Privileges</div>' +
            '<div style="font-size:0.85em;">' +
            '<div style="margin:4px 0;">🛡️ 4 personal guards paid by the kingdom</div>' +
            '<div style="margin:4px 0;">👑 Direct influence over the king\'s decisions</div>' +
            '<div style="margin:4px 0;">💍 Noble marriage opportunities</div>' +
            '<div style="margin:4px 0;">🌍 Automatic status in foreign kingdoms</div>' +
            '<div style="margin:4px 0;">📜 Propose laws and shape the kingdom\'s future</div>' +
            '<div style="margin:4px 0;">📉 10% trade tax discount</div>' +
            '</div></div>' +

            '<p style="text-align:center;color:#ffaa66;font-style:italic;margin:10px 0;">Once you enter the nobility, there is no going back to being a simple merchant. Are you certain?</p>' +
            '</div>';

        openModal('⚠️ Confirm: Enter the Nobility of ' + kingdomName, html,
            '<button class="btn-medieval" data-action="closeAnd_executePetition" style="background:linear-gradient(180deg,#5aad35,#3a7a24);border-color:#5aad35;margin-right:8px;">👑 Swear Fealty & Accept</button>' +
            '<button class="btn-medieval" data-action="closeModal">Cancel</button>'
        );
    }

    function _executePetition() {
        try {
            const result = Player.petitionForPromotion();
            if (result && result.success) {
                toast(result.message, 'success');
            } else if (result && result.nobleConflict) {
                // Show UI popup to confirm renouncing noble status in other kingdom
                _showNobleConflictPopup(result.conflictKingdomId, result.conflictKingdomName, result.targetKingdomId);
            } else {
                toast((result && result.message) || 'Cannot promote', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Promotion failed', 'danger');
        }
    }

    function _showNobleConflictPopup(conflictKingdomId, conflictKingdomName, targetKingdomId) {
        var targetName = 'the kingdom';
        try { var tk = Engine.findKingdom(targetKingdomId); if (tk) targetName = tk.name; } catch(e) {}

        var html = '<div style="padding:15px;">' +
            '<div style="text-align:center;margin-bottom:15px;">' +
            '<div style="font-size:2.5em;">⚔️👑</div>' +
            '<h3 style="color:#ff8888;margin:5px 0;">Noble Conflict</h3>' +
            '</div>' +
            '<div style="padding:12px;background:rgba(200,100,100,0.1);border:1px solid rgba(200,100,100,0.3);border-radius:6px;margin-bottom:12px;">' +
            '<p style="color:#ddd;">You are already a <b>Minor Noble</b> in <b>' + conflictKingdomName + '</b>. To become a noble in <b>' + targetName + '</b>, you must <b>renounce your nobility</b> in ' + conflictKingdomName + '.</p>' +
            '</div>' +
            '<div style="padding:12px;background:rgba(200,100,100,0.08);border:1px solid rgba(200,100,100,0.25);border-radius:6px;margin-bottom:12px;">' +
            '<div style="color:#ff8888;font-weight:bold;margin-bottom:8px;">⚠️ Consequences of Renouncing</div>' +
            '<div style="font-size:0.9em;">' +
            '<div style="margin:5px 0;">📉 <b>Demoted to Guildmaster</b> in ' + conflictKingdomName + '</div>' +
            '<div style="margin:5px 0;">🏰 <b>-30 Kingdom Reputation</b> in ' + conflictKingdomName + '</div>' +
            '<div style="margin:5px 0;">👑 <b>-20 Relationship</b> with the King of ' + conflictKingdomName + '</div>' +
            '<div style="margin:5px 0;">🤝 <b>-20 Relationship</b> with all nobles of ' + conflictKingdomName + '</div>' +
            '<div style="margin:5px 0;">🛡️ <b>Lose kingdom guards</b> from ' + conflictKingdomName + '</div>' +
            '</div></div>' +
            '<p style="text-align:center;color:#ffaa66;font-style:italic;">This cannot be undone. Are you sure?</p>' +
            '</div>';

        openModal('⚔️ Renounce Nobility in ' + conflictKingdomName + '?', html,
            '<button class="btn-medieval" data-action="confirmRenounceNoble" data-conflict="' + conflictKingdomId + '" data-target="' + targetKingdomId + '" style="background:linear-gradient(180deg,#c44,#922);border-color:#c44;margin-right:8px;">⚔️ Renounce & Proceed</button>' +
            '<button class="btn-medieval" data-action="closeModal">Cancel</button>'
        );
    }

    function confirmRenounceNoble(btn) {
        var conflictK = btn.getAttribute('data-conflict');
        var targetK = btn.getAttribute('data-target');
        if (!conflictK || !targetK) { toast('Missing kingdom data.', 'danger'); return; }
        closeModal();
        var result = Player.renounceNobleForPromotion(conflictK, targetK);
        if (result && result.success) {
            toast(result.message, 'success');
        } else if (result && result.nobleConflict) {
            _showNobleConflictPopup(result.conflictKingdomId, result.conflictKingdomName, result.targetKingdomId);
        } else {
            toast((result && result.message) || 'Promotion failed.', 'warning');
        }
    }

    function changeCitizenship(kingdomId) {
        try {
            const result = Player.petitionCitizenship(kingdomId);
            if (result && result.success) {
                toast(result.message, 'success');
                openCharacterDialog();
            } else {
                toast((result && result.message) || 'Cannot change citizenship', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Citizenship change failed', 'danger');
        }
    }

    function setActiveCitizenship(kingdomId) {
        try {
            const result = Player.setActiveCitizenship(kingdomId);
            if (result && result.success) {
                toast(result.message, 'success');
                openCharacterDialog();
            } else {
                toast((result && result.message) || 'Cannot set active citizenship', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Failed to set active citizenship', 'danger');
        }
    }

    // ── GIFT GIVING ──

    function openGiftDialog(personId) {
        const person = Engine.findPerson(personId);
        if (!person) { toast('Person not found.', 'warning'); return; }

        const rel = Player.getRelationship(personId);
        const relLabel = Player.getRelationshipLabel(rel.level);

        // Gift preferences
        var knownPrefs = Player.getKnownGiftPreferences ? Player.getKnownGiftPreferences(personId) : {};
        var prefHtml = '';
        if (knownPrefs.favorite || knownPrefs.hated) {
            prefHtml += '<div style="padding:6px;margin:4px 0;border:1px solid rgba(255,215,0,0.3);border-radius:6px;background:rgba(255,215,0,0.05);font-size:0.8rem;">';
            prefHtml += '<div style="font-weight:bold;margin-bottom:2px;">🔍 Known Preferences</div>';
            if (knownPrefs.favorite) {
                var favRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === knownPrefs.favorite; });
                prefHtml += '<div style="color:#2ecc40;">💖 Loves: ' + (favRes ? favRes.icon + ' ' + favRes.name : knownPrefs.favorite) + ' (+10 per item!)</div>';
            }
            if (knownPrefs.hated) {
                var hateRes = Object.values(RESOURCE_TYPES).find(function(r) { return r.id === knownPrefs.hated; });
                prefHtml += '<div style="color:#e74c3c;">😠 Hates: ' + (hateRes ? hateRes.icon + ' ' + hateRes.name : knownPrefs.hated) + ' (-5 per item!)</div>';
            }
            prefHtml += '</div>';
        }

        let itemsHtml = '';
        for (const [resId, qty] of Object.entries(Player.inventory || {})) {
            if (qty <= 0) continue;
            const res = Object.values(RESOURCE_TYPES).find(r => r.id === resId);
            if (!res) continue;
            var badge = '';
            if (knownPrefs.favorite === resId) badge = ' <span style="color:#2ecc40;font-size:0.75rem;">💖 Loves!</span>';
            else if (knownPrefs.hated === resId) badge = ' <span style="color:#e74c3c;font-size:0.75rem;">😠 Hates!</span>';
            itemsHtml += `<div class="trade-item">
                <div class="res-info">${res.icon} ${res.name} (${qty})${badge}</div>
                <div class="trade-controls">
                    <button class="btn-trade buy" data-action="executeGift" data-id="${personId}" data-val="${resId}" data-qty="1">Gift 1</button>
                </div>
            </div>`;
        }
        if (!itemsHtml) itemsHtml = '<div class="text-dim text-center">No items to give</div>';

        const html = `<div class="detail-section">
            <h3>🎁 Gift to ${person.firstName} ${person.lastName}</h3>
            <div class="detail-row"><span class="label">Relationship</span>
                <span class="value">${relLabel.icon} ${relLabel.name} (${Math.floor(rel.level)})</span></div>
            <div class="detail-row"><span class="label">Type</span>
                <span class="value">${rel.type}</span></div>
            ${prefHtml}
        </div>
        <div class="detail-section">${itemsHtml}</div>`;

        openModal(`🎁 Gift — ${person.firstName}`, html);
    }

    function executeGift(personId, resourceId, qty) {
        try {
            const result = Player.giveGift(personId, resourceId, qty);
            if (result && result.success) {
                toast(result.message, 'success');
                // Story mode: track NPC gift
                if (typeof Player !== 'undefined' && Player.state && Player.state.storyMode) {
                    Player.state.storyMode._giftedNPC = true;
                    if (typeof StoryMode !== 'undefined' && StoryMode.tick) StoryMode.tick(Player.state);
                }
                openGiftDialog(personId);
            } else {
                toast((result && result.message) || 'Cannot give gift', 'warning');
            }
        } catch (e) {
            toast(e.message || 'Gift failed', 'danger');
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  XP BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateXPBar() {
        if (typeof Player === 'undefined') return;
        const xpFill = document.getElementById('xpBarFill');
        const xpLabel = document.getElementById('xpBarLabel');
        const xpDetail = document.getElementById('xpBarDetail');
        if (!xpFill || !xpLabel) return;

        const totalXp = Player.totalXp || 0;
        const level = Player.level || 1;
        const currentLevelXp = Player.getCurrentLevelXP ? Player.getCurrentLevelXP() : 0;
        const nextLevelXp = Player.getNextLevelXP ? Player.getNextLevelXP() : 50;
        const title = Player.getMerchantTitle ? Player.getMerchantTitle() : 'Novice';
        const sp = Player.skillPoints || 0;

        const xpInLevel = totalXp - currentLevelXp;
        const xpNeeded = nextLevelXp - currentLevelXp;
        const maxLevel = 15;
        const pct = level >= maxLevel ? 100 : Math.min(100, Math.floor(xpInLevel / Math.max(1, xpNeeded) * 100));

        xpFill.style.width = pct + '%';
        xpLabel.textContent = `Lv${level} ${title}`;
        if (xpDetail) {
            var xpBankAmt = (typeof Player.xpBank !== 'undefined') ? Player.xpBank : 0;
            var bankStr = xpBankAmt > 0 ? ` • 🏦${xpBankAmt}/1000` : '';
            xpDetail.textContent = level >= maxLevel
                ? `${formatGold(totalXp)} XP • ${sp} SP${bankStr}`
                : `${formatGold(totalXp)}/${formatGold(nextLevelXp)} XP • ${sp} SP${bankStr}`;
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  RANK PROGRESSION TRACKER UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateRankProgress() {
        var container = document.getElementById('rankProgressContent');
        if (!container) return;
        if (typeof Player === 'undefined' || !Player.getRankProgressBars) { container.innerHTML = ''; return; }
        var data = Player.getRankProgressBars();
        if (!data || !data.bars || data.bars.length === 0) {
            container.innerHTML = '';
            var group = document.getElementById('rankProgressGroup');
            if (group) group.style.display = 'none';
            return;
        }
        var group = document.getElementById('rankProgressGroup');
        if (group) group.style.display = '';

        var _activeKName = '';
        if (typeof Player !== 'undefined' && Player.citizenshipKingdomId && typeof Engine !== 'undefined' && Engine.findKingdom) {
            try { var _akK = Engine.findKingdom(Player.citizenshipKingdomId); if (_akK) _activeKName = ' (' + _akK.name + ')'; } catch(e) {}
        }
        var html = '<div style="font-size:10px;color:#d4af37;margin-bottom:3px;display:flex;justify-content:space-between;align-items:center;cursor:help;" title="To see privileges of the next rank, or to proceed once you meet all requirements, go to the Character menu.">';
        html += '<span>Progress to ' + (data.nextRank.icon || '📈') + ' ' + data.nextRank.name + ' Promotion' + _activeKName + '</span>';
        if (data.allMet) html += '<span style="color:#5a5;font-size:9px;">✅ Ready!</span>';
        html += '</div>';
        for (var i = 0; i < data.bars.length; i++) {
            var b = data.bars[i];
            var barColor = b.met ? '#55a868' : (b.pct >= 60 ? '#ccb974' : '#7a6a4a');
            var shortLabel = b.label;
            // Tooltip descriptions for each requirement
            var tooltipMap = {
                '🪙 Gold Earned from Trading': 'Total gold earned through trading in this kingdom. Buy low and sell high to accumulate earnings.',
                '⭐ Reputation': 'Your standing with this kingdom. Increases by trading, completing petitions, and socializing with locals.',
                '💰 Fee': 'One-time promotion fee paid to the kingdom. Make sure you have enough gold on hand.',
                '📅 Residency': 'Days you have lived in this kingdom. Simply stay and go about your business.',
                '📊 Trade Days': 'Days since your first trade. Keep trading regularly to build your merchant reputation.',
                '🏗️ Buildings': 'Buildings you own in this kingdom. Construct or purchase buildings in towns.',
                '🔄 Trades': 'Total buy/sell transactions completed. Each purchase or sale counts as one trade.',
                '🏭 Prod. Buildings': 'Processing or finished-goods buildings you own. Build sawmills, smithies, bakeries, etc.',
                '👷 Workers': 'Employees working in this kingdom. Hire workers at your buildings to increase this count.',
                '🏘️ Towns': 'Number of different towns where you own buildings. Expand your business to new towns.',
                '🏘️ Towns w/ Property': 'Towns where you own buildings or land. Spread your holdings across the kingdom.',
                '🐪 Caravan Goods': 'Total goods transported by your caravans. Send caravans between towns to move goods.',
                '📜 Petitions': 'Successful petitions to the king. Visit the kingdom court to submit petitions.',
                '👑 Noble Endorsements': 'Nobles with 60+ relationship. Build friendships with Minor Nobles and above.',
                '👷 Total Workers': 'All employees across the kingdom. Hire more workers at your various buildings.',
                '🛤️ Infrastructure': 'Roads, bridges, or sea routes you have built. Invest in kingdom infrastructure.',
                '👑 King Relationship': 'Your personal relationship with the king. Attend court and complete royal commissions.'
            };
            var tooltip = tooltipMap[b.label] || '';
            var discountNote = b.discounted ? ' 💍' : '';
            var curStr = b.waived ? 'Waived' : (b.current >= 10000 ? (b.current / 1000).toFixed(0) + 'k' : String(b.current));
            var reqStr = b.waived ? '✓' : (b.required >= 10000 ? (b.required / 1000).toFixed(0) + 'k' : String(b.required));
            var displayValue = b.waived ? 'Waived ✓' : (curStr + '/' + reqStr + discountNote + (b.met ? ' ✓' : ''));
            var tipText = b.waived ? 'Waived by marriage to a noble spouse.' : (b.discounted ? tooltip + ' (Reduced by marriage or skill)' : tooltip);
            html += '<div style="margin-bottom:2px;cursor:help;" title="' + tipText + '">';
            html += '<div style="display:flex;justify-content:space-between;font-size:9px;color:' + (b.met ? '#5a5' : '#999') + ';line-height:1.2;">';
            html += '<span>' + shortLabel + '</span>';
            html += '<span>' + displayValue + '</span>';
            html += '</div>';
            html += '<div style="height:4px;background:#1a1a1a;border-radius:2px;overflow:hidden;">';
            html += '<div style="height:100%;width:' + b.pct + '%;background:' + barColor + ';border-radius:2px;transition:width 0.5s;"></div>';
            html += '</div></div>';
        }
        container.innerHTML = html;
    }

    // ═══════════════════════════════════════════════════════════
    //  HUNGER BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateHungerBar() {
        if (typeof Player === 'undefined') return;
        const hungerFill = document.getElementById('hungerFill');
        const hungerValue = document.getElementById('hungerValue');
        if (!hungerFill || !hungerValue) return;

        const hunger = Player.hunger != null ? Player.hunger : 80;
        hungerFill.style.width = Math.max(0, Math.min(100, hunger)) + '%';
        hungerValue.textContent = '🍖 ' + Math.floor(hunger);

        if (hunger >= 60) {
            hungerFill.style.background = '#55a868';
        } else if (hunger >= 30) {
            hungerFill.style.background = '#ccb974';
        } else {
            hungerFill.style.background = '#c44e52';
        }

        // Update food supply indicator
        var foodInfo = document.getElementById('foodSupplyInfo');
        var btnEat = document.getElementById('btnEatUntilFull');
        if (foodInfo && Player.getFoodSupply) {
            var supply = Player.getFoodSupply();
            foodInfo.textContent = '🍞 ' + supply.total + ' food (~' + supply.daysEstimate + 'd)';
            if (supply.daysEstimate <= 3) foodInfo.style.color = '#c44e52';
            else if (supply.daysEstimate <= 7) foodInfo.style.color = '#ccb974';
            else foodInfo.style.color = '#aaa';
        }
        if (btnEat) {
            btnEat.disabled = hunger >= 100 || !(Player.getFoodSupply && Player.getFoodSupply().total > 0);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  ENERGY & THIRST BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateFatigueBar() {
        if (typeof Player === 'undefined') return;

        // Energy bar (replaces old fatigue)
        var fatigueFill = document.getElementById('fatigueFill');
        var fatigueValue = document.getElementById('fatigueValue');
        if (fatigueFill && fatigueValue) {
            var energy = Player.energy != null ? Player.energy : 100;
            var maxEnergy = Player.maxEnergy || 100;
            var energyPct = Math.max(0, Math.min(100, (energy / maxEnergy) * 100));
            fatigueFill.style.width = energyPct + '%';

            var icon = '⚡';
            if (energyPct <= 15) icon = '😵';
            else if (energyPct <= 30) icon = '😴';
            else if (energyPct <= 50) icon = '😐';
            fatigueValue.textContent = icon + ' ' + Math.floor(energy) + '/' + maxEnergy;

            if (energyPct > 60) fatigueFill.style.background = '#55a868';
            else if (energyPct > 40) fatigueFill.style.background = '#ccb974';
            else if (energyPct > 20) fatigueFill.style.background = '#e8a040';
            else fatigueFill.style.background = '#c44e52';
        }

        // Thirst bar
        var thirstFill = document.getElementById('thirstFill');
        var thirstValue = document.getElementById('thirstValue');
        if (thirstFill && thirstValue) {
            var thirst = Player.thirst != null ? Player.thirst : 80;
            var thirstPct = Math.max(0, Math.min(100, thirst));
            thirstFill.style.width = thirstPct + '%';

            var tIcon = '💧';
            if (thirstPct <= 15) tIcon = '🏜️';
            else if (thirstPct <= 30) tIcon = '😰';
            else if (thirstPct <= 50) tIcon = '🫗';
            thirstValue.textContent = tIcon + ' ' + Math.floor(thirst);

            if (thirstPct > 60) thirstFill.style.background = '#4488cc';
            else if (thirstPct > 40) thirstFill.style.background = '#7799aa';
            else if (thirstPct > 20) thirstFill.style.background = '#cc8844';
            else thirstFill.style.background = '#c44e52';
        }

        // Update drink supply indicator
        var drinkInfo = document.getElementById('drinkSupplyInfo');
        var btnDrink = document.getElementById('btnDrinkUntilFull');
        if (drinkInfo && typeof Player !== 'undefined' && Player.getDrinkSupply) {
            var supply = Player.getDrinkSupply();
            drinkInfo.textContent = '🫗 ' + supply.total + ' drinks (~' + supply.daysEstimate + 'd)';
            if (supply.daysEstimate <= 3) drinkInfo.style.color = '#c44e52';
            else if (supply.daysEstimate <= 7) drinkInfo.style.color = '#ccb974';
            else drinkInfo.style.color = '#aaa';
        }
        if (btnDrink) {
            var thirstVal = typeof Player !== 'undefined' && Player.thirst != null ? Player.thirst : 80;
            btnDrink.disabled = thirstVal >= 100 || !(typeof Player !== 'undefined' && Player.getDrinkSupply && Player.getDrinkSupply().total > 0);
        }
    }

    // ═══════════════════════════════════════════════════════════
    //  HEALTH BAR UPDATE
    // ═══════════════════════════════════════════════════════════
    function updateHealthBar() {
        if (typeof Player === 'undefined') return;
        var healthFill = document.getElementById('healthFill');
        var healthValue = document.getElementById('healthValue');
        if (!healthFill || !healthValue) return;

        var health = Player.health != null ? Player.health : 100;
        var maxHealth = Player.maxHealth || 100;
        var healthPct = Math.max(0, Math.min(100, (health / maxHealth) * 100));
        healthFill.style.width = healthPct + '%';

        var hIcon = '❤️';
        if (healthPct <= 15) hIcon = '💀';
        else if (healthPct <= 30) hIcon = '🩹';
        else if (healthPct <= 50) hIcon = '🤕';
        healthValue.textContent = hIcon + ' ' + Math.floor(health) + '/' + maxHealth;

        if (healthPct > 60) healthFill.style.background = '#55a868';
        else if (healthPct > 40) healthFill.style.background = '#ccb974';
        else if (healthPct > 20) healthFill.style.background = '#e8a040';
        else healthFill.style.background = '#c44e52';
    }

    // ═══════════════════════════════════════════════════════════
    //  MOBILE HUD & HEALTH ALERT
    // ═══════════════════════════════════════════════════════════

    function _abbreviateGold(g) {
        if (g == null || isNaN(g)) return '0';
        g = Math.floor(g);
        if (g >= 1000000) return (g / 1000000).toFixed(1) + 'M';
        if (g >= 10000) return (g / 1000).toFixed(1) + 'K';
        if (g >= 1000) return (g / 1000).toFixed(1) + 'K';
        return String(g);
    }

    function _setHudBarClass(barEl, pct) {
        if (!barEl) return;
        barEl.className = 'hud-bar ' + (pct > 50 ? 'ok' : pct > 25 ? 'warning' : 'critical');
    }

    function updateMobileHud() {
        if (window.innerWidth > 600) return;
        if (typeof Player === 'undefined') return;
        var goldEl = document.getElementById('hudGoldVal');
        if (goldEl) goldEl.textContent = _abbreviateGold(Player.gold);

        var hunger = Player.hunger != null ? Player.hunger : 80;
        var hungerProg = document.getElementById('hudHunger');
        if (hungerProg) hungerProg.value = Math.max(0, Math.min(100, hunger));
        _setHudBarClass(document.getElementById('hudHungerBar'), hunger);

        var thirst = Player.thirst != null ? Player.thirst : 80;
        var thirstProg = document.getElementById('hudThirst');
        if (thirstProg) thirstProg.value = Math.max(0, Math.min(100, thirst));
        _setHudBarClass(document.getElementById('hudThirstBar'), thirst);

        var energy = Player.energy != null ? Player.energy : 100;
        var maxEnergy = Player.maxEnergy || 100;
        var energyPct = (energy / maxEnergy) * 100;
        var energyProg = document.getElementById('hudEnergy');
        if (energyProg) energyProg.value = Math.max(0, Math.min(100, energyPct));
        _setHudBarClass(document.getElementById('hudEnergyBar'), energyPct);

        var health = Player.health != null ? Player.health : 100;
        var maxHealth = Player.maxHealth || 100;
        var healthPct = (health / maxHealth) * 100;
        var healthBar = document.getElementById('hudHealthBar');
        var healthProg = document.getElementById('hudHealth');
        if (healthBar) {
            if (healthPct < 100) {
                healthBar.classList.remove('hidden');
                if (healthProg) healthProg.value = Math.max(0, Math.min(100, healthPct));
                _setHudBarClass(healthBar, healthPct);
            } else {
                healthBar.classList.add('hidden');
            }
        }

        var locEl = document.getElementById('hudLocation');
        if (locEl) {
            var locName = '—';
            if (Player.traveling) {
                locName = '🚶 Traveling...';
            } else if (Player.townId != null) {
                try {
                    var t = Engine.getTown(Player.townId);
                    if (t) locName = t.name;
                } catch (e) { /* no-op */ }
            }
            locEl.textContent = '📍 ' + locName;
        }
    }

    function updateHealthAlert() {
        var alertEl = document.getElementById('healthAlert');
        var alertText = document.getElementById('healthAlertText');
        if (!alertEl || typeof Player === 'undefined') return;

        // Hide during regency — heir is growing up, not sick
        if (Player.regencyMode) {
            alertEl.classList.remove('visible');
            return;
        }

        var isSick = Player.illnesses && Player.illnesses.length > 0;
        var isInjured = Player.injuries && Player.injuries.length > 0;
        var healthLow = (Player.health != null && Player.health < 50);

        if (isSick || isInjured || healthLow) {
            var msgs = [];
            if (isInjured) msgs.push('injured');
            if (isSick) msgs.push('sick');
            if (healthLow && !isInjured && !isSick) msgs.push('low health');
            if (alertText) alertText.textContent = 'You are ' + msgs.join(' & ') + '!';
            alertEl.classList.add('visible');
        } else {
            alertEl.classList.remove('visible');
        }
    }

    // ═══════════════════════════════════════════════════════════
