                html += ' — 💰' + Math.floor(em.gold||0).toLocaleString() + 'g | 📦' + invCount + ' items';
                html += ' | 📍' + (emTown ? emTown.name : '?');
                html += ' | 🎯' + (em.strategy||'?');
                if (em.traveling) html += ' | 🚶 Traveling (' + Math.round((em.travelProgress||0)*100) + '%)';
                html += '</div>';
